-- Misconception layer for the daily warm-up (design handoff "Math Warm-Up Audit", 1c/2c).
-- On a ✗ self-check the app compares the student's answer against each predicted
-- wrong answer ("slip") for the item, using checkAnswer() with the SAME tolerance
-- as the key; first match decides the feedback. No match → the competency fallback.
--
-- Slip shape (math_spiral_items.misconceptions is a JSONB array):
--   { tag:     kebab-case, shared vocabulary across competencies (dashboard aggregates by tag)
--     label:   ≤7 words, what the student did
--     wrong:   static wrong answer, checker-parseable ("12.5 m/s", "4.5 x 10^5", "3/4", "18 N/kg; 12 N/kg")
--     expr:    (templated items instead of `wrong`) expression over the template vars, same
--              grammar as template.answer — instantiate with the student's values, round with
--              template.sigFigs, append `unit` ?? template.answerUnit, then checkAnswer(student, that)
--     unit:    optional override when the slip's unit differs from the key's (unconverted km etc.)
--     message: 1–3 sentences, descriptive (what was right → where it went sideways → next move);
--              may contain {a}-slots on templated items — fill with fillSlots() like the prompt }
-- Bank authored 2026-09-02 from the 216 numeric items (short-answer / teacher-only items carry
-- no slips: the machine never judges them). Validated: every expr evaluates on 25 draws and
-- never equals the key on all draws; no two slips on an item collide.
ALTER TABLE public.math_spiral_items ADD COLUMN IF NOT EXISTS misconceptions JSONB;
COMMENT ON COLUMN public.math_spiral_items.misconceptions IS
  'Predicted wrong answers with descriptive feedback: [{tag,label,wrong|expr,unit?,message}]. See migration 20260902_misconceptions.sql.';
ALTER TABLE public.math_competencies ADD COLUMN IF NOT EXISTS misconception_fallback TEXT;
COMMENT ON COLUMN public.math_competencies.misconception_fallback IS
  'Shown on a ✗ self-check when no slip matched (or the item has no slips).';

UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Decide first whether the question wants a slope (rise ÷ run, a rate) or an area (height × width, a total), then write the change in y and the change in x with units before you compute. Mr. Antocci will read your work either way.' WHERE code = 'GV1';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Ask two things of your graph: which variable is really on each axis (x, x², or 1/x), and whether the slope is the quantity you were asked for or still needs unpacking. Write the axis labels with units, then re-read the question. Mr. Antocci will read your work either way.' WHERE code = 'GV2';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Sketch the vector as a right triangle first: the hypotenuse is the length, the adjacent side goes with cos, the opposite side with sin, and the diagonal comes from the square root of the two squares. Label which side the question asks for before you compute. Mr. Antocci will read your work either way.' WHERE code = 'GV3';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Line the numbers up so the decimal points sit under each other, write the place name over each digit, and compare from the left. Mr. Antocci will read your work either way.' WHERE code = 'NS1';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Check which form the question asks for — fraction, decimal, or percent — and remember they are three names for one value: 3/5 = 0.6 = 60%. Write the value in all three forms before you answer, then pick the one the question wants. Mr. Antocci will read your work either way.' WHERE code = 'NS2';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Ask yourself first: are the two quantities growing together, or does one shrink as the other grows? Then write the known pair as a rate with units, and multiply or divide by the new amount. Mr. Antocci will read your work either way.' WHERE code = 'PR1';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Start by naming the relationship — direct, inverse, square, or inverse-square — then write the factor the input changed by, apply the power to that factor, and only then decide whether the output is multiplied or divided. Mr. Antocci will read your work either way.' WHERE code = 'PR2';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Write the number out long-hand first, then move the decimal point one place at a time and count each move — that count is the exponent, and the sign says which way you moved. Mr. Antocci will read your work either way.' WHERE code = 'QE1';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Write the unit next to every number, then write the conversion factor as a fraction (like 1000 m / 1 km) and check that the old unit cancels and the new one survives. Mr. Antocci will read your work either way.' WHERE code = 'QE2';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected order of magnitude, and it doesn''t match a slip we recognise. Write out your chain as a line of factors with a unit on each one, then count the powers of ten step by step before you combine. Mr. Antocci will read your reasoning either way.' WHERE code = 'QE3';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Ask two things of every number you report: which digit is the last one the instrument actually knows, and how many of the digits you wrote are significant. Write the count next to your answer before you submit. Mr. Antocci will read your work either way.' WHERE code = 'QE4';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected form, and it doesn''t match a slip we recognise. Go back to the original equation and undo one operation at a time, doing the same thing to both sides: undo adding with subtracting, multiplying with dividing, squaring with a square root. Then check by substituting your result back in. Mr. Antocci will read your work either way.' WHERE code = 'SM1';
UPDATE public.math_competencies SET misconception_fallback = 'Not the expected answer, and it doesn''t match a slip we recognise. Go back to the formula, write each value under its letter with its unit, and evaluate one operation at a time — powers, then multiply or divide, then add or subtract. Mr. Antocci will read your work either way.' WHERE code = 'SM2';

UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intercept-ignored", "label": "Divided endpoint by time, skipped intercept", "wrong": "6.67 m/s", "message": "You divided 20 m by 3 s, which is the position at the end, not the change in position. The line starts at 5 m, so the rise is 20 − 5 = 15 m. Slope is the change in y over the change in x: 15 ÷ 3."}, {"tag": "rise-run-swapped", "label": "Divided time by position change", "wrong": "0.2 m/s", "message": "You found the change in position correctly, 15 m, but then put the 3 s on top. Velocity is metres per second, so metres go on top: 15 ÷ 3."}, {"tag": "area-not-slope", "label": "Multiplied instead of dividing", "wrong": "60 m/s", "message": "You multiplied the two numbers, which is an area. On a position–time graph the velocity is the steepness, the slope: rise ÷ run. Find the change in position, 20 − 5, and divide by the 3 s it took."}]'::jsonb WHERE id = '5ffc04f8-c0fe-441a-86ab-2c254aae023f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "halved-not-needed", "label": "Halved the rectangle", "wrong": "12 m", "message": "You multiplied 6 × 4 and then took half. The half belongs to a triangle; a flat line at 6 m/s for 4 s makes a rectangle. Its area is simply height × width: 6 × 4."}, {"tag": "slope-not-area", "label": "Divided velocity by time", "wrong": "1.5 m", "message": "You divided 6 by 4, which is a slope. The question asks for distance, and distance is the area under a velocity–time graph. A flat line makes a rectangle: height 6 m/s × width 4 s."}, {"tag": "added-not-multiplied", "label": "Added velocity and time", "wrong": "10 m", "message": "You added 6 and 4. Area under the graph is height × width, not height + width. Check with units: (m/s) × s gives metres; adding m/s to s gives nothing meaningful."}]'::jsonb WHERE id = '9beb2a57-1186-4bfe-b640-73c0004097d2';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "rise-run-swapped", "label": "Divided run by rise", "wrong": "0.2", "message": "You used the right two points but divided across by up. Slope is rise ÷ run: the y-change (10) over the x-change (2)."}, {"tag": "area-not-slope", "label": "Found the triangle area", "wrong": "10", "message": "½ × 2 × 10 is the area of the triangle under the line, not its slope. Slope is how steep the line is: rise ÷ run, so 10 ÷ 2."}, {"tag": "multiplied-not-divided", "label": "Multiplied rise and run", "wrong": "20", "message": "You multiplied 2 by 10. Slope compares the rise to the run by dividing: for every 1 across, how far up? That is 10 ÷ 2."}]'::jsonb WHERE id = '6ac47f91-e940-419c-b0cb-7aae2aefd9b0';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "constant-as-one", "label": "Gave constant a slope of 1", "wrong": "1", "message": "You read the line as constant, which is right, but a constant position means the object is not moving. The line has no rise, so the slope is 0 ÷ run = 0. Velocity is 0."}, {"tag": "negative-not-zero", "label": "Gave a negative slope", "wrong": "-1", "message": "A negative slope would be a line falling from left to right. A horizontal line neither climbs nor falls, so its rise is 0 and its slope is 0. On a position–time graph, that is an object at rest."}]'::jsonb WHERE id = '7e901bbb-6a21-4e4a-9225-efa89c0ef13f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "rise-run-swapped", "label": "Divided days by pages", "wrong": "0.0625", "message": "You divided 5 by 80, which is days per page. Pages per day puts pages on top: 80 ÷ 5. Check: 0.06 pages a day would take over two weeks per page."}, {"tag": "area-not-slope", "label": "Found the triangle area", "wrong": "200", "message": "½ × 5 × 80 is the area under the line, not its slope. The rate, pages per day, is the steepness of the line: rise ÷ run, or 80 ÷ 5."}, {"tag": "multiplied-not-divided", "label": "Multiplied pages and days", "wrong": "400", "message": "You multiplied 5 by 80. A rate compares the two by dividing: pages ÷ days. 80 pages over 5 days is 80 ÷ 5 each day."}]'::jsonb WHERE id = 'f88d13eb-7cea-432d-a79d-abcae7f44ae6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "rise-run-swapped", "label": "Divided Δx by Δy", "expr": "(c-a)/(d*10-b*10)", "message": "Both differences are right, but the x-change went on top. Slope is rise ÷ run: ({d}0 − {b}0) ÷ ({c} − {a})."}, {"tag": "digit-not-value", "label": "Dropped the trailing zeros", "expr": "(d-b)/(c-a)", "message": "You subtracted {d} − {b}, but the y-values are {b}0 and {d}0. The rise is {d}0 − {b}0, ten times bigger. Then divide by the run, {c} − {a}."}, {"tag": "sign-dropped", "label": "Subtracted in mismatched order", "expr": "(d*10-b*10)/(a-c)", "message": "The sizes are right but the sign is off. You took y in one order and x in the other. Keep both pairs the same way round: ({d}0 − {b}0) ÷ ({c} − {a}). A line climbing to the right has a positive slope."}]'::jsonb WHERE id = '7dca6a0e-9b73-4ef8-8b48-d86c3b8c139e';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intercept-ignored", "label": "Left out the $40 start", "expr": "15*a", "message": "15 × {a} is how much was added over {a} weeks, but the graph did not start at $0. Add the y-intercept: 40 + 15 × {a}."}, {"tag": "added-not-multiplied", "label": "Added weeks instead of multiplying", "expr": "40+15+a", "message": "You kept the $40 start, then added 15 and {a}. The $15 happens every week, so it is 15 × {a}, then add the 40."}, {"tag": "order-of-operations", "label": "Added 40 and 15, then multiplied", "expr": "(40+15)*a", "message": "You combined 40 + 15 first and then multiplied by {a}. Only the $15 repeats each week; the $40 is there once. Multiply first, 15 × {a}, then add 40."}]'::jsonb WHERE id = '5f37014d-9fb0-4270-b668-fd0f1793efff';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "rise-run-swapped", "label": "Divided hours by dollars", "wrong": "0.0667", "message": "You divided 4 by 60, which is hours per dollar. The slope is rise ÷ run, dollars over hours: 60 ÷ 4. That number is the pay rate in $/hour."}, {"tag": "area-not-slope", "label": "Found the triangle area", "wrong": "120", "message": "½ × 4 × 60 is the area under the line, not its slope. The slope is how steep the line is: rise ÷ run, 60 ÷ 4, and it means dollars earned per hour."}, {"tag": "multiplied-not-divided", "label": "Multiplied dollars and hours", "wrong": "240", "message": "You multiplied 4 by 60. A slope divides: for each hour across, how many dollars up? 60 ÷ 4."}]'::jsonb WHERE id = '6ef82a89-2dc5-4de8-adad-6a63a26aae7e';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "slope-not-area", "label": "Divided rate by time", "expr": "a/b", "message": "You divided {a} by {b}, which is a slope. The area under a rate graph is the total: for a flat line it is a rectangle, height {a} L/min × width {b} min = litres."}, {"tag": "halved-not-needed", "label": "Halved the rectangle", "expr": "a*b/2", "message": "You multiplied {a} × {b} and then halved it. Halving is for a triangle; a flat line makes a rectangle, so the area is just {a} × {b}."}, {"tag": "added-not-multiplied", "label": "Added rate and time", "expr": "a+b", "message": "You added {a} and {b}. Area is height × width: {a} L/min × {b} min. Check the units: L/min × min gives litres; L/min + min gives nothing."}]'::jsonb WHERE id = '58c343ea-062c-4190-9ceb-01d94a5fd282';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intercept-ignored", "label": "Divided endpoint y by x", "expr": "y/t", "message": "You divided {y} by {t}, which is the y-value at the end, not the change in y. The line starts at {b}, so the rise is {y} − {b}. Slope is ({y} − {b}) ÷ {t}."}, {"tag": "rise-run-swapped", "label": "Divided run by rise", "expr": "t/(y-b)", "message": "The rise {y} − {b} is right, but you put the run on top. Slope is rise ÷ run: ({y} − {b}) ÷ {t}."}, {"tag": "sign-dropped", "label": "Subtracted in mismatched order", "expr": "(b-y)/t", "message": "The size is right but the sign is off. You took {b} − {y} while going from x = 0 to x = {t}. Keep the order the same for both: ({y} − {b}) ÷ ({t} − 0)."}]'::jsonb WHERE id = '5567062e-1fd1-431f-b10a-73849538034d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "Used ${b}, not ${b}0", "expr": "b/a", "message": "You set up the division correctly, but the start is ${b}0, not ${b}. Solve {b}0 − {a}t = 0: t = {b}0 ÷ {a}."}, {"tag": "inverted-ratio", "label": "Divided slope by intercept", "expr": "a/(b*10)", "message": "You divided the other way round. Losing ${a} each day from ${b}0, the days needed is the money ÷ the rate: {b}0 ÷ {a}."}, {"tag": "sign-dropped", "label": "Answer came out negative", "expr": "-b*10/a", "message": "The size is right. From {b}0 − {a}t = 0, t = {b}0 ÷ {a}, a positive number of days. The minus sign belongs to the slope, not to the time."}, {"tag": "multiplied-not-divided", "label": "Multiplied intercept and slope", "expr": "b*10*a", "message": "You multiplied {b}0 by {a}. Set intercept + slope × t = 0: {b}0 − {a}t = 0, so t = {b}0 ÷ {a}."}]'::jsonb WHERE id = '22befaef-3063-4541-8305-d3eb2b85212f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "half-forgotten", "label": "Forgot the ½ for a triangle", "wrong": "72 L", "message": "6 × 12 is the rectangle that would surround the triangle. The area under this graph is a triangle, so take half: ½ × 6 × 12."}, {"tag": "slope-not-area", "label": "Divided height by base", "wrong": "2 L", "message": "12 ÷ 6 is a slope, the rate of change of the rate. The question asks for the total amount, which is the area: ½ × base × height = ½ × 6 × 12."}, {"tag": "added-not-multiplied", "label": "Added base and height", "wrong": "18 L", "message": "You added 6 and 12. Area multiplies: ½ × base × height. Check the units: min × L/min gives litres."}]'::jsonb WHERE id = '7f187c21-c0c1-46fc-8e18-2bab5821ee36';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "gave the tripling factor as slope", "wrong": "3", "message": "You noticed that tripling F triples a, which is what makes the graph a straight line through the origin. The 3 is the ratio between two trials, not the slope. Slope is rise over run, Δa ÷ ΔF, and since F = ma that ratio is 1 ÷ m. The slope is 1/mass."}, {"tag": "rise-run-swapped", "label": "divided force by acceleration", "wrong": "1/3", "message": "You set up a ratio, but the other way round. With acceleration on the vertical axis the slope is Δa ÷ ΔF, so the force goes on the bottom. From F = ma that gives a/F = 1/m: the slope is 1/mass, and its shape is a straight line through the origin."}]'::jsonb WHERE id = '12d6e310-eb83-46d1-a257-074028874699';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "read the horizontal axis as x", "wrong": "1", "message": "You read a straight line as y proportional to x. Look at the axis label though: the horizontal axis is x², not x. A straight line through the origin means y is proportional to whatever is on that axis, so y is proportional to x². Doubling x quadruples y."}, {"tag": "doubled-not-squared", "label": "turned squaring into doubling", "wrong": "4", "message": "You went past a plain linear reading, which is right. But the horizontal axis is x², a power of 2, not a factor of 4. A straight line on y vs x² means y is proportional to x², so the relationship is y = kx². The 4 shows up only when you double x."}, {"tag": "inverted-ratio", "label": "inverted the power to a root", "wrong": "0.5", "message": "You reached for a power, which is the right idea. A straight line on y vs x² means y grows like x², power 2. The power ½ (a square root) would straighten y² vs x instead. Check with a table: if x doubles, y should quadruple."}]'::jsonb WHERE id = '3d9fcea5-0e0c-477c-afc9-f423e3ac2fda';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "wrong-transform", "label": "plotted y against x squared", "wrong": "2", "message": "You transformed the horizontal axis, which is the right move, but with a square. y = k/x means y falls as x grows, so the thing y is proportional to is 1/x. Plot y against 1/x and the line''s slope is k; y vs x² would curve even more."}, {"tag": "linear-not-inverse-square", "label": "used inverse square, not inverse", "wrong": "-2", "message": "You correctly saw that the relationship is inverse, but y = k/x is x to the power −1, not −2. Plot y against 1/x, not 1/x². If the data go straight, the slope of that line is k."}]'::jsonb WHERE id = '9d4b1f5b-1fc3-4d36-afe9-8148884afbc6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "gave the slope itself", "expr": "a", "message": "You read the slope correctly: {a} dollars for each hour. The question asks for 3 extra hours, so the slope is the rate, not the total. Multiply the rate by the hours: {a} × 3."}, {"tag": "added-not-multiplied", "label": "added 3 to the slope", "expr": "a+3", "message": "You found the slope, {a} dollars per hour, and combined it with the 3 hours by adding. A rate scales with time rather than adding to it: 3 hours at {a} per hour is {a} × 3. Units check: dollars per hour times hours gives dollars."}, {"tag": "multiplied-not-divided", "label": "divided the slope by 3", "expr": "a/3", "message": "You used the slope and the 3 hours, but divided. Slope is dollars per hour, so each extra hour adds {a} dollars and 3 extra hours add three times that: {a} × 3. Dividing would tell you the earnings for a third of an hour."}]'::jsonb WHERE id = '7dd9f6e4-0182-4063-9f4b-fd7e8cce04bf';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sign-dropped", "label": "lost the negative sign", "wrong": "10 %/hour", "message": "Your rise and run are right: 60% over 6 h is 10 %/hour. The line drops though, so the rise is 40 − 100 = −60, and the slope is −10 %/hour. The sign is what tells a reader the battery is draining, not charging."}, {"tag": "value-not-change", "label": "used 40% instead of the change", "wrong": "-6.67 %/hour", "message": "You divided by the 6 hours, which is the right run. The rise is the change in charge, from 100% down to 40%, which is −60%, not the 40% that remains. So the slope is −60 ÷ 6 = −10 %/hour."}, {"tag": "rise-run-swapped", "label": "divided hours by percent", "wrong": "-0.1 hour/%", "message": "You used both endpoints correctly: a change of −60% over 6 h. Slope is rise ÷ run, and the rise is on the vertical axis (percent), so it is −60 ÷ 6 = −10 %/hour. Hours per percent is the reciprocal and answers a different question."}]'::jsonb WHERE id = '61b46473-f145-4877-8ebd-50563d23409d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "multiplied slope by x, not x²", "expr": "a*b", "message": "You used the slope as a multiplier, which is right. But the horizontal axis is x², so the slope multiplies x², not x. Square first: {b}² = {b} × {b}, then multiply by {a}."}, {"tag": "intermediate-answer", "label": "stopped at x squared", "expr": "b^2", "message": "You squared x, which is the first step and the one most people skip. That number is the horizontal position on the graph, not y. Read up to the line: y = slope × x², so multiply by {a}."}, {"tag": "order-of-operations", "label": "squared the whole product", "expr": "a^2*b^2", "message": "You squared and you multiplied by the slope, but the square was applied to the product. Only x is squared: y = {a} × ({b})², so {b}² first, then times {a}. The slope itself stays as it is."}]'::jsonb WHERE id = 'f22b78e3-1941-4deb-a61c-9bb64a24ff87';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse", "label": "multiplied slope by x", "expr": "a*10*b", "message": "You used the slope as a multiplier, which is right, but you multiplied by x. The horizontal axis is 1/x, so y = slope × (1/x) = slope ÷ x. Divide {a}0 by {b}. Check: as x grows, y should shrink."}, {"tag": "intermediate-answer", "label": "gave the slope itself", "expr": "a*10", "message": "You read the slope correctly: {a}0. That is the constant k in y = k/x, not y itself. To find y at x = {b}, divide the slope by x: {a}0 ÷ {b}."}, {"tag": "power-of-ten", "label": "dropped the zero from the slope", "expr": "a/b", "message": "You divided the slope by x, which is exactly the right move for a y vs 1/x line. The slope is {a}0 though, not {a}. Redo it with the full slope: {a}0 ÷ {b}."}, {"tag": "inverted-ratio", "label": "divided x by the slope", "expr": "b/(a*10)", "message": "You put the slope and x together with a division, which is right, but the other way round. y = slope × (1/x), so the slope stays on top: {a}0 ÷ {b}. Check: a bigger slope should give a bigger y."}]'::jsonb WHERE id = '99e9be04-b01d-4a21-a797-80750a228b3a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intercept-ignored", "label": "treated the intercept as zero", "wrong": "0", "message": "You recognised the plot is straight, so y = kx² still describes the shape. But a line that misses the origin has an intercept, and it is real information: it is the value of y when x = 0, a starting amount. Write the model as y = kx² + c and read c off the vertical axis."}, {"tag": "digit-not-value", "label": "read the intercept as the power", "wrong": "2", "message": "You had the power of x in mind, but the intercept is a different thing from the exponent. The 2 lives in the axis label (x²); the intercept is where the line crosses the vertical axis. It tells you y when x = 0, the starting amount c in y = kx² + c."}]'::jsonb WHERE id = '68548b1f-eb53-41de-be87-d9dbb7256ed2';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "wrong-points", "label": "chose where the lines cross", "wrong": "7", "message": "You solved 3.1x − 0.2 = 2.8x + 1.9 and found the crossing at x = 7, which is careful algebra. At the crossing the two fits predict the same y, so a measurement there cannot tell them apart. You want a point where they disagree most: far from the cluster, near x = 0 or at large x."}, {"tag": "intermediate-answer", "label": "gave the slope difference", "wrong": "0.3", "message": "You compared the slopes and found they differ by 0.3, which is a useful start. That difference grows with x, so the fits separate most at large x, and their intercepts separate them near x = 0. Answer with a place to measure, not the difference itself."}, {"tag": "intercept-ignored", "label": "gave the intercept difference", "wrong": "2.1", "message": "You compared the intercepts, which do differ by 2.1 at x = 0. That gap is exactly why a measurement near x = 0 is decisive, so turn it into a location: measure at an x near 0 (or a very large x), where the two lines are farthest apart."}]'::jsonb WHERE id = 'de3a2e21-d923-42f6-9447-596541223cea';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "cos and sin traded places", "wrong": "2540 m/s; 5440 m/s", "message": "Both numbers are right, but they landed on the other axes. The 25° is measured from the horizontal, so the horizontal side is the adjacent one: 6000 × cos25° ≈ 5440 m/s. The vertical side is opposite the angle, 6000 × sin25° ≈ 2540 m/s. A small angle should give the big horizontal part."}, {"tag": "radian-mode", "label": "calculator was in radians", "wrong": "5950 m/s; -794 m/s", "message": "Your setup is right, but a negative vertical part for a vector pointing upward is the tell: the calculator read 25 as radians. Switch to degree mode (DEG, not RAD) and re-enter 6000 × cos25° and 6000 × sin25° — you should get about 5440 and 2540."}, {"tag": "intermediate-answer", "label": "cos25 and sin25 without the 6000", "wrong": "0.906; 0.423", "message": "You found cos25° ≈ 0.906 and sin25° ≈ 0.423, which are the fractions of the length that go each way. The components are those fractions of the actual 6000 m/s, so multiply: 6000 × 0.906 and 6000 × 0.423."}, {"tag": "magnitude-not-component", "label": "gave the full 6000 for both", "wrong": "6000 m/s; 6000 m/s", "message": "You kept the whole 6000 m/s for each direction, but a component is only the shadow of the vector on one axis, so each is shorter than 6000. Draw the right triangle with 6000 as the hypotenuse; the two legs are 6000 × cos25° and 6000 × sin25°."}]'::jsonb WHERE id = '1d9baa73-4094-4f9c-90dd-c18f7600fd44';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-magnitudes", "label": "added 10 and 10", "wrong": "20", "message": "You added the two lengths, which works only when both point the same way. East and north are at right angles, so they form the legs of a triangle and the sum is the diagonal: √(10² + 10²). The diagonal is always shorter than the two legs walked one after the other."}, {"tag": "squared-not-rooted", "label": "stopped at the sum of squares", "wrong": "200", "message": "10² + 10² = 200 is the right middle step — that is the diagonal squared. Pythagoras finishes with a square root, so the magnitude is √200 ≈ 14.1. Sense-check: the answer has to sit between 10 and 20."}, {"tag": "forgot-square", "label": "took the root of 10 + 10", "wrong": "4.47", "message": "You took a square root, but of 10 + 10 instead of 10² + 10². Each leg gets squared first, then add, then root: √(100 + 100) = √200 ≈ 14.1. A result smaller than either leg is the sign that a square went missing."}]'::jsonb WHERE id = '6ea80a24-35a5-42a1-87dd-c6e59ad85f6d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "used sin for the x-part", "wrong": "30 m/s", "message": "You used sin37°, which gives the vertical part. The 37° is measured from the horizontal, so the x-component is the adjacent side: 50 × cos37° ≈ 40 m/s. Adjacent goes with cos, opposite goes with sin."}, {"tag": "radian-mode", "label": "calculator was in radians", "wrong": "38.3 m/s", "message": "Right setup, 50 × cos37, but the calculator treated 37 as radians and gave 0.765 instead of 0.799. Switch to DEG mode and re-enter it; cos37° ≈ 0.799, so the x-component is about 40 m/s."}, {"tag": "intermediate-answer", "label": "cos37 without the 50", "wrong": "0.799", "message": "cos37° ≈ 0.799 is the fraction of the vector that points along x, and it is right. The component is that fraction of 50 m/s, so multiply: 50 × 0.799 ≈ 40 m/s."}, {"tag": "magnitude-not-component", "label": "gave the full 50", "wrong": "50 m/s", "message": "You kept the whole 50 m/s, but only part of it points along x — the rest points up. Draw the right triangle with 50 as the hypotenuse; the horizontal leg is 50 × cos37° ≈ 40 m/s, which has to be shorter than 50."}]'::jsonb WHERE id = '0870fd85-6a54-4b93-af0c-de7d159ef6ef';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "used cos for the y-part", "wrong": "40 m/s", "message": "You used cos37°, which gives the horizontal part. The y-component is the side opposite the 37°, so it goes with sin: 50 × sin37° ≈ 30 m/s. Opposite goes with sin, adjacent goes with cos."}, {"tag": "radian-mode", "label": "calculator was in radians", "wrong": "-32.2 m/s", "message": "A negative vertical part for a vector that points above the horizontal is the tell: the calculator read 37 as radians. Switch to DEG mode and re-enter 50 × sin37°; sin37° ≈ 0.602, so the y-component is about 30 m/s."}, {"tag": "intermediate-answer", "label": "sin37 without the 50", "wrong": "0.602", "message": "sin37° ≈ 0.602 is right — it is the fraction of the vector that points along y. The component is that fraction of 50 m/s, so multiply: 50 × 0.602 ≈ 30 m/s."}, {"tag": "magnitude-not-component", "label": "gave the full 50", "wrong": "50 m/s", "message": "You kept the whole 50 m/s, but only part of it points up — most of it points sideways at this angle. In the right triangle the vertical leg is 50 × sin37° ≈ 30 m/s, which has to be shorter than the 50 hypotenuse."}]'::jsonb WHERE id = 'ea8e8791-353d-4d8d-be2e-c48a090a5028';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-magnitudes", "label": "added 3 N and 4 N", "wrong": "7 N", "message": "You added the two forces head-on, which only works when they pull the same way. At right angles they are the legs of a triangle and the resultant is the diagonal: √(3² + 4²) = 5 N. The diagonal is always less than the two legs added."}, {"tag": "squared-not-rooted", "label": "stopped at the sum of squares", "wrong": "25 N", "message": "3² + 4² = 25 is the right middle step — that is the resultant squared. Pythagoras finishes with a square root: √25 = 5 N. Sense-check: the resultant should sit between 4 N and 7 N."}, {"tag": "forgot-square", "label": "took the root of 3 + 4", "wrong": "2.65 N", "message": "You took a square root, but of 3 + 4 instead of 3² + 4². Square each leg first, then add, then root: √(9 + 16) = 5 N. A result smaller than either force is the sign that a square went missing."}, {"tag": "subtraction-reversed", "label": "subtracted 3 N from 4 N", "wrong": "1 N", "message": "Subtracting is what you do when two forces pull in opposite directions. These are at right angles, so neither cancels the other — they combine as the legs of a triangle: √(3² + 4²) = 5 N."}]'::jsonb WHERE id = 'e3e9e1dd-2d44-4e51-b575-0934ede3c3c3';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "used cos instead of sin", "expr": "b*cos(a)", "message": "You used cos{a}°, which gives the ground distance out to the point under the kite. Height is the side opposite the {a}° angle at the ground, so it goes with sin: {b} × sin{a}°. Opposite with sin, adjacent with cos."}, {"tag": "radian-mode", "label": "calculator was in radians", "expr": "b*sin(a*180/pi)", "message": "Right setup, {b} × sin{a}, but the calculator read {a} as radians, so the sine came out with the wrong size or sign. Switch to DEG mode and re-enter it. A height above the ground has to be positive and less than {b} m."}, {"tag": "magnitude-not-component", "label": "gave the whole string length", "expr": "b", "message": "You answered with the full {b} m of string, but the string is the slanted hypotenuse — only part of it is height. Draw the right triangle: the vertical leg is {b} × sin{a}°, which is shorter than the string."}]'::jsonb WHERE id = 'eb26bb22-820c-410b-b143-4930ed009b02';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-magnitudes", "label": "added the two legs", "expr": "a+b", "message": "You added {a} and {b}, which is the distance you walked. The question asks how far you are from the start — the diagonal across the corner — and that comes from the triangle: √({a}² + {b}²). The diagonal is shorter than the two legs added."}, {"tag": "squared-not-rooted", "label": "stopped at the sum of squares", "expr": "a^2+b^2", "message": "{a}² + {b}² is the right middle step — that is the distance squared. Pythagoras finishes with a square root: √({a}² + {b}²). Sense-check: the answer has to be less than {a} + {b}."}, {"tag": "forgot-square", "label": "took the root of a + b", "expr": "sqrt(a+b)", "message": "You took a square root, but of {a} + {b} instead of {a}² + {b}². Square each leg first, then add, then root. A result smaller than either leg is the sign that a square went missing."}]'::jsonb WHERE id = '2276fd9d-0d27-4f8a-bee5-cf0082c20438';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "displacement-not-distance", "label": "gave the crow-flies diagonal", "expr": "sqrt(a^2+b^2)", "message": "You computed the straight-line distance from the start, and the triangle work is right. But the question asks how far you walked — the path length — and you actually covered both legs: {a} + {b} m. The diagonal would be the answer to a different question."}, {"tag": "subtraction-reversed", "label": "subtracted one leg from the other", "expr": "abs(a-b)", "message": "You subtracted the legs. Subtracting is for legs that point in opposite directions and undo each other; here both legs add to the path you walked, no matter which way they point: {a} + {b} m."}]'::jsonb WHERE id = 'b9307a10-856b-4023-9be7-91658fc5f8ed';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "displacement-not-distance", "label": "picked the 10 m diagonal", "wrong": "10 m", "message": "You answered with the diagonal. The diagonal is the shortcut — it is the shortest way between the two points — so it cannot be the longer walk. The two-leg path is 6 + 8 = 14 m, which is more than 10 m."}, {"tag": "subtraction-reversed", "label": "gave the difference of legs", "wrong": "4 m", "message": "You found 8 − 6 = 4, but the two legs are walked one after the other, so they add: 6 + 8 = 14 m. Compare that 14 m with the 10 m diagonal — the two-leg path is longer."}, {"tag": "added-magnitudes", "label": "added all three lengths", "wrong": "24 m", "message": "You added 6 + 8 + 10, but those are two different routes, not one walk. Route one is the two legs, 6 + 8 = 14 m; route two is the diagonal, 10 m. The question asks which of the two is longer — the 14 m two-leg path."}]'::jsonb WHERE id = '7a3116d1-fbab-4a54-8a4e-284897041d75';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "magnitude-not-angle", "label": "gave the distance, not direction", "wrong": "11.3", "message": "You found the straight-line distance, √(8² + 8²) ≈ 11.3 km, and that is right for a different question. This one asks for the compass direction — an angle. Equal east and north legs make a 45° triangle, so the drone is exactly northeast, 45° north of east."}, {"tag": "radian-mode", "label": "calculator was in radians", "wrong": "0.785", "message": "tan⁻¹(8/8) is the right move, but the calculator gave the angle in radians: 0.785 rad. In degree mode, tan⁻¹(1) = 45°, which is northeast. When the two legs are equal you can skip the calculator — the angle is always 45°."}, {"tag": "intermediate-answer", "label": "stopped at tan = 1", "wrong": "1", "message": "8/8 = 1 is the tangent of the angle, and that is the right middle step. The direction is the angle whose tangent is 1: tan⁻¹(1) = 45°, so the drone is northeast of home."}, {"tag": "part-not-whole", "label": "gave one leg''s length", "wrong": "8", "message": "You answered with the 8 km of one leg. The question asks which way the drone is from home — a direction, not a length. With equal east and north legs, the triangle is 45°, so the direction is northeast (45° north of east)."}]'::jsonb WHERE id = 'aaa7a93a-b4c3-4bf5-9eda-63c36834bd45';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "used sin instead of cos", "expr": "b*sin(a)", "message": "You used sin{a}°, which gives how far NORTH you went. The angle is measured from east, so east is the adjacent side and goes with cos: {b} × cos{a}°. Adjacent with cos, opposite with sin."}, {"tag": "radian-mode", "label": "calculator was in radians", "expr": "b*cos(a*180/pi)", "message": "Right setup, {b} × cos{a}, but the calculator read {a} as radians, so the cosine came out with the wrong size or sign. Switch to DEG mode and re-enter it. The east part must be positive and less than {b} m."}, {"tag": "magnitude-not-component", "label": "gave the whole walk length", "expr": "b", "message": "You answered with the full {b} m, but only part of that walk is eastward — the rest is northward. Draw the right triangle with {b} as the hypotenuse; the east leg is {b} × cos{a}°, which is shorter than {b}."}]'::jsonb WHERE id = 'f1a0b5fc-24db-47c5-8ab0-7062de7417ad';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-magnitudes", "label": "added 3 and 4 blocks", "wrong": "7 blocks", "message": "3 + 4 = 7 is how many blocks you walked. As the crow flies means the straight diagonal from start to finish, and east and north are at right angles, so use the triangle: √(3² + 4²) = 5 blocks. The diagonal is shorter than the walk."}, {"tag": "squared-not-rooted", "label": "stopped at the sum of squares", "wrong": "25 blocks", "message": "3² + 4² = 25 is the right middle step — that is the distance squared. Pythagoras finishes with a square root: √25 = 5 blocks. Sense-check: the answer has to be less than 3 + 4."}, {"tag": "forgot-square", "label": "took the root of 3 + 4", "wrong": "2.65 blocks", "message": "You took a square root, but of 3 + 4 instead of 3² + 4². Square each leg first, then add, then root: √(9 + 16) = 5 blocks. A result smaller than either leg is the sign that a square went missing."}, {"tag": "subtraction-reversed", "label": "subtracted 3 from 4", "wrong": "1 block", "message": "Subtracting is for legs that point in opposite directions. East and north are at right angles, so neither cancels the other — they combine as the legs of a triangle: √(3² + 4²) = 5 blocks."}]'::jsonb WHERE id = '631fd7d2-54f9-4067-8790-c69f27c9abb2';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "used cos instead of sin", "expr": "b*cos(a)", "message": "You used cos{a}°, which gives the horizontal distance along the ground. Height is the side opposite the {a}° at the bottom of the ramp, so it goes with sin: {b} × sin{a}°. Opposite with sin, adjacent with cos."}, {"tag": "radian-mode", "label": "calculator was in radians", "expr": "b*sin(a*180/pi)", "message": "Right setup, {b} × sin{a}, but the calculator read {a} as radians, so the sine came out with the wrong size or sign. Switch to DEG mode and re-enter it. Height gained must be positive and less than the {b} m you travelled."}, {"tag": "magnitude-not-component", "label": "gave the whole ramp length", "expr": "b", "message": "You answered with the full {b} m, but that is the slanted distance along the ramp — the hypotenuse. Only part of it is height. Draw the right triangle: the vertical leg is {b} × sin{a}°, which is shorter than {b}."}, {"tag": "substituted-wrong-variable", "label": "used tan instead of sin", "expr": "b*tan(a)", "message": "You used tan{a}°, but tan is height over ground distance, and {b} m is the ramp itself, not the ground distance. When the hypotenuse is what you know, height is {b} × sin{a}°."}]'::jsonb WHERE id = '84f33a76-c561-475b-b873-f087761edc2b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "squared-not-rooted", "label": "stopped at the sum of squares", "expr": "b^2", "message": "Both components are right, and squaring and adding them is the right check — you got {b}², the length squared. Pythagoras finishes with the square root, and that root should land back on the original {b} m. That is the whole point of the check."}, {"tag": "added-magnitudes", "label": "added the two components", "expr": "b*cos(a)+b*sin(a)", "message": "Both components are right, but you added them straight, and cos plus sin does not come back to 1. The check is Pythagoras: square each component, add, then root — √(east² + north²) should rebuild the {b} m you started with."}, {"tag": "part-not-whole", "label": "reported only the east part", "expr": "b*cos(a)", "message": "{b} × cos{a}° is the east component, and it is right. The north component is {b} × sin{a}°, and the final check is √(east² + north²), which should rebuild the original {b} m."}]'::jsonb WHERE id = '9d59dc85-b0a0-4121-8a4f-21bf6ba7d06a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "stopped at tan = 1", "wrong": "1", "message": "Equal parts means east/north = 1, so tan of the angle is 1 — that is the right middle step. The question asks for the angle itself: tan⁻¹(1) = 45°. Check: sin45° and cos45° are both 0.707."}, {"tag": "radian-mode", "label": "calculator was in radians", "wrong": "0.785", "message": "tan⁻¹(1) is the right move, but the calculator gave the angle in radians: 0.785 rad. In degree mode the same angle is 45°. Sense-check: an angle that splits a 90° corner exactly in half has to be 45°."}, {"tag": "component-not-angle", "label": "gave sin45 instead of 45", "wrong": "0.707", "message": "0.707 is the value of sin and cos at the angle you want, and finding that they match is the right idea. The question asks for the angle itself, the one where sin and cos are equal: 45°."}]'::jsonb WHERE id = 'aa4b2c74-ddaf-4d49-a556-17cbf2ea2253';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sin-cos-swapped", "label": "used cos instead of sin", "expr": "b*10*cos(a)", "message": "You used cos{a}°, which gives the paces EAST. The angle is measured from east, so north is the side opposite the angle and goes with sin: {b}0 × sin{a}°. Opposite with sin, adjacent with cos."}, {"tag": "radian-mode", "label": "calculator was in radians", "expr": "b*10*sin(a*180/pi)", "message": "Right setup, {b}0 × sin{a}, but the calculator read {a} as radians, so the sine came out with the wrong size or sign. Switch to DEG mode and re-enter it. Paces north must be positive and fewer than {b}0."}, {"tag": "decimal-shift", "label": "used {b} paces, not {b}0", "expr": "b*sin(a)", "message": "Your trig is right, but the map says {b}0 paces, and you multiplied by {b}. The north part is {b}0 × sin{a}° — ten times bigger than what you have."}, {"tag": "magnitude-not-component", "label": "gave all {b}0 paces", "expr": "b*10", "message": "You answered with the full {b}0 paces, but that walk is slanted — only part of it is northward. Draw the right triangle with {b}0 as the hypotenuse; the north leg is {b}0 × sin{a}°, which is fewer paces than {b}0."}]'::jsonb WHERE id = '663cea01-64ee-4b58-b781-ed22906f2833';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sign-dropped", "label": "added west and south as positives", "wrong": "7; 10", "message": "You added every move as if it pushed the same way. West undoes east and south undoes north, so opposite directions subtract: 5 − 2 = 3 m east and 7 − 3 = 4 m north. Give the opposite direction a minus sign before you add."}, {"tag": "part-not-whole", "label": "ignored the west and south moves", "wrong": "5; 7", "message": "5 east and 7 north are the first moves only. The 2 m west and 3 m south move you back, so the net is 5 − 2 = 3 m east and 7 − 3 = 4 m north."}, {"tag": "subtraction-reversed", "label": "subtracted the other way round", "wrong": "-3; -4", "message": "You subtracted in the right pairs but the other way round, so the signs flipped. 5 east is more than 2 west, so the net still points east: 5 − 2 = +3 m east, and 7 − 3 = +4 m north."}]'::jsonb WHERE id = '36e791b6-7df8-4809-8d8c-3de86337d9fd';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Chose 0.68 for having more digits", "wrong": "0.68; 6000", "message": "You got the 6: it sits in the thousands place, so it is worth 6,000. For the decimal you picked 0.68, the longer number. Length does not decide size — compare the tenths first: 7 tenths against 6 tenths. Line them up as 0.70 and 0.68 and read left to right."}, {"tag": "digit-not-value", "label": "Gave the digit 6, not its value", "wrong": "0.7; 6", "message": "0.7 is the larger decimal — 7 tenths beats 6 tenths. For the second part you wrote the digit itself. The question asks what the 6 is worth, and it sits three places left of the ones, in the thousands. Name the place, then write the digit followed by that many zeros."}, {"tag": "place-value-off", "label": "Put the 6 one place too low", "wrong": "0.7; 600", "message": "0.7 is larger, and you know the 6 carries place value — you gave it hundreds. Count the places from the right: 0 ones, 0 tens, 2 hundreds, then the 6. That is the thousands place, so the 6 is worth 6,000."}]'::jsonb WHERE id = 'a035af33-6857-48e9-97b0-4fed960a8e3f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Ranked by number of digits", "wrong": "0.3; 0.25; 0.305", "message": "Your order follows how many digits each number has, shortest to longest. Digits after the point do not add size on their own. Pad each to three places — 0.300, 0.250, 0.305 — and compare tenths first, then hundredths, then thousandths."}, {"tag": "fewer-digits-bigger", "label": "Treated longer decimals as smaller", "wrong": "0.25; 0.305; 0.3", "message": "You started right with 0.25 as the least. Then you placed 0.305 below 0.3, as if more decimal places made it smaller. Pad to three places: 0.300 and 0.305 share tenths and hundredths, and 5 thousandths beats 0. So 0.305 goes last."}, {"tag": "order-reversed", "label": "Listed greatest to least", "wrong": "0.305; 0.3; 0.25", "message": "Your comparison is right in every pair — 0.305 is the biggest and 0.25 is the smallest. The list runs the other way from what was asked. Least to greatest means the smallest number comes first. Flip the order."}]'::jsonb WHERE id = '671ea285-9202-426c-9daa-2dc20f025e3f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "Wrote the number of hundreds", "wrong": "62", "message": "62 is how many hundreds are in 6,238 — that is the rounding step done. The answer is the rounded number itself, so put the zeros back: 62 hundreds is 6,200."}, {"tag": "rounding-direction", "label": "Rounded the hundreds up", "wrong": "6,300", "message": "You found the hundreds place, which is the main step. You rounded the 2 up to 3. The decision digit is the one right after the hundreds — the 3 in the tens place — and 3 is under 5, so the hundreds digit stays a 2. 6,238 is closer to 6,200 than to 6,300."}, {"tag": "power-of-ten", "label": "Rounded to the nearest thousand", "wrong": "6,000", "message": "6,000 is the nearest thousand, so you rounded one place too far left. The nearest hundred keeps the thousands digit and rounds the hundreds: 6,2|38. The 3 after the 2 says stay, so the answer ends in 200."}]'::jsonb WHERE id = '62799b7a-3f8c-424a-acd9-d1341af88971';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Picked 0.09 for its extra digit", "wrong": "0.09", "message": "You picked 0.09, the number with more digits. After the decimal point, more digits does not mean more value. Write both to hundredths: 0.10 and 0.09. Ten hundredths is more than nine hundredths, so 0.1 is larger."}, {"tag": "leading-zero-dropped", "label": "Read 0.09 as 0.9", "wrong": "0.9", "message": "You compared 0.9 against 0.1 — but the number is 0.09. That zero right after the point is a placeholder: it pushes the 9 from the tenths into the hundredths. 0.09 is nine hundredths, which is less than one tenth. Keep every digit where it is."}]'::jsonb WHERE id = 'e8cc1c4e-fb1b-4ff8-80a4-55b60aa893f9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "Gave the digit, not its value", "wrong": "7", "message": "You found the 7. The question asks what it is worth, not which digit it is. Count places from the right: 0 ones, 0 tens, 5 hundreds, then the 7 in the thousands. So the 7 is worth 7,000 — the digit followed by three zeros."}, {"tag": "place-value-off", "label": "Placed the 7 in the hundreds", "wrong": "700", "message": "You know the 7 carries place value and you gave it hundreds. It is one place further left than that. Reading from the right: 0, 0, 5 — that is ones, tens, hundreds — and the 7 comes next, in the thousands. Its value is 7,000."}, {"tag": "power-of-ten", "label": "Placed the 7 in the ten-thousands", "wrong": "70,000", "message": "You gave the 7 a value one place too high. The 4 sits in the ten-thousands; the 7 is just to its right, in the thousands. Say the number aloud — forty-seven thousand — and the 7 is the seven thousand."}]'::jsonb WHERE id = '8cc1098a-45e8-4a63-ba1b-f1cde2325038';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "compared-from-right", "label": "Picked 18 by its ones digit", "expr": "18", "message": "You saw the thousands and hundreds match and then judged by the last digit, where 8 beats 1, so you went with {a},{b}18. Comparing runs left to right: the first place that differs is the tens, and there 8 beats 1. So the larger number is {a},{b}81 — write the whole number."}, {"tag": "part-not-whole", "label": "Wrote only the digits that differ", "expr": "81", "message": "You spotted the place where the numbers differ and that 81 beats 18 — that is the comparison. The answer is the whole number that wins, not just the piece: write all four digits, {a},{b}81."}, {"tag": "intermediate-answer", "label": "Gave the difference between them", "expr": "63", "message": "You subtracted and found how far apart they are, which shows you saw that {a},{b}81 is bigger. The question only asks which one is larger, so the answer is the number itself: {a},{b}81."}]'::jsonb WHERE id = 'a4355aec-32ee-44ac-92aa-6288123dc59f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "interval-wrong-end", "label": "Gave the top of the range", "wrong": "6.35", "message": "You found the edge of the range, but the top edge. 6.35 rounds up to 6.4, so it is just outside, and the question asks for the smallest. Go the other way: numbers from 6.25 upward round to 6.3, and 6.25 is where that starts."}, {"tag": "place-value-off", "label": "Went half a whole below", "wrong": "5.8", "message": "You went down from 6.3, which is the right direction, and by a half — but half of a whole. The rounding here is to the nearest tenth, so the range reaches only half a tenth below: 6.25. Its hundredths digit is 5, so it rounds up to 6.3, and 6.24 would not."}]'::jsonb WHERE id = '393bf3f8-fe5d-4393-9469-6321705e2eea';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Said the 5-digit decimal is bigger", "wrong": "5", "message": "You picked the longer number. Digits after the point can add size (0.41234 beats 0.400) or not (0.39999 is less than 0.400). Since you only know the first two places, there is no way to decide. The answer is that you cannot tell without seeing the next digits."}, {"tag": "fewer-digits-bigger", "label": "Said the 3-digit decimal is bigger", "wrong": "3", "message": "You picked the shorter number, as if more decimal places shrink a value. They can go either way: 0.400 is less than 0.41234 and more than 0.39999. Knowing the first two places is not enough, so the answer is that you cannot tell."}]'::jsonb WHERE id = 'ef618824-370b-4fef-89b1-0ea7ad98c486';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "subtracted-not-divided", "label": "Took 3 cents off", "wrong": "0.27", "message": "You took 3 away from 30 cents. ''A third'' is a fraction of the price, not a number of cents. A third of $0.30 means $0.30 ÷ 3. Ask: what times 3 gives 30 cents?"}, {"tag": "complement-not-part", "label": "Kept two-thirds instead of one", "wrong": "0.20", "message": "You subtracted a third — 10 cents — and kept the other two-thirds, which is ''fell BY a third''. This price fell TO a third, so the new price is the third itself: $0.30 ÷ 3 = $0.10."}, {"tag": "multiplied-not-divided", "label": "Multiplied by 3", "wrong": "0.90", "message": "You tripled the price. A third of something is smaller than the thing, so the price has to go below $0.30. ''A third of'' means divide by 3: $0.30 ÷ 3."}]'::jsonb WHERE id = '8bb63355-0784-493a-af92-6df3ce67a0df';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "Gave the digit, not its value", "wrong": "7", "message": "You found the 7. The question asks what it is worth. Count places from the right: 2 ones, 6 tens, 0 hundreds, then the 7 in the thousands. So the 7 stands for 7,000."}, {"tag": "place-value-off", "label": "Placed the 7 in the hundreds", "wrong": "700", "message": "You gave the 7 place value, but one place too low. Read from the right: 2, 6, 0 fill the ones, tens and hundreds — the zero still takes up a place — and the 7 comes next, in the thousands. Its value is 7,000."}, {"tag": "power-of-ten", "label": "Placed the 7 in the ten-thousands", "wrong": "70,000", "message": "You gave the 7 a value one place too high. The 4 is in the ten-thousands and the 7 sits just right of it, in the thousands. Say it aloud — forty-seven thousand sixty-two — and the 7 is the seven thousand."}]'::jsonb WHERE id = 'fd4a037f-0239-4b1c-8ae6-635955a5eb92';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "Read the hundredths digit as the count", "expr": "0", "message": "You looked in the hundredths place and found nothing there, so you answered 0. That digit tells you how many extra hundredths past the tenths, not how many hundredths in the whole number. Each 1 is 100 hundredths and each tenth is 10 hundredths, so {a}.{b} holds {a}×100 + {b}×10 of them."}, {"tag": "place-value-off", "label": "Read the tenths digit instead", "expr": "b", "message": "You read off the {b} — that is the tenths digit, and it says {b} tenths. Each tenth is 10 hundredths, and each whole is 100 hundredths. So count all of them: {a} wholes give {a}00 hundredths, plus {b} tenths give {b}0 more."}, {"tag": "decimal-shift", "label": "Counted tenths, not hundredths", "expr": "a*10+b", "message": "You multiplied by 10, which counts the tenths in {a}.{b}. Hundredths are ten times smaller, so there are ten times more of them. Multiply by 100 instead — slide the decimal point two places right."}, {"tag": "power-of-ten", "label": "Counted thousandths, not hundredths", "expr": "a*1000+b*100", "message": "You moved the decimal point three places, which counts thousandths. A hundredth is 1/100, so multiply by 100 — the point moves two places, giving {a}{b}0."}]'::jsonb WHERE id = '9591a836-95f4-4498-8b8a-e90d634c7ba3';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "Found half the gap, then stopped", "expr": "(b-a)/2", "message": "You found the distance from {a} to {b} and halved it — that is the distance to the midpoint. The question asks where the midpoint sits on the line, so add your half-gap back onto {a}. Or add the two ends and divide by 2."}, {"tag": "half-forgotten", "label": "Added the ends without halving", "expr": "a+b", "message": "You added {a} and {b}, which is the first step toward the average. Halfway means the average of the two, so divide that sum by 2. Check: the midpoint must land between {a} and {b}."}, {"tag": "part-not-whole", "label": "Halved only the larger number", "expr": "b/2", "message": "You halved {b}. Half of the bigger number is halfway between 0 and {b}, not between {a} and {b}. Both ends matter: add {a} and {b}, then divide by 2."}]'::jsonb WHERE id = '5d70c568-9db7-407a-bf4f-a478598e85a5';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Chose the longer decimal", "expr": "a+b/100", "message": "You picked {a}.0{b}, the number with more digits. The zero after the point pushes the {b} into the hundredths, making it {b} hundredths. In {a}.{b} the {b} is in the tenths, and a tenth is ten times a hundredth. Line them up as {a}.0{b} and {a}.{b}0 and compare the tenths."}, {"tag": "part-not-whole", "label": "Wrote only the decimal part", "expr": "b/10", "message": "You compared the decimal parts and saw {b} tenths beats {b} hundredths — that is the comparison. The answer is the whole number that wins, ones digit included: {a}.{b}."}]'::jsonb WHERE id = '25a30845-38a9-44cb-bb8d-4d29e66d0e8d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "negative-order-flipped", "label": "Called it a drop of 7", "wrong": "-7", "message": "You found the size of the change, 7. The direction is the other way: on a number line −5 sits to the right of −12, so the balance rose. Owing $5 is better than owing $12. Up by 7."}, {"tag": "added-not-subtracted", "label": "Added 12 and 5", "wrong": "17", "message": "You combined 12 and 5 into 17. Both balances are on the negative side, so the change is the gap between them: from −12 up to −5 is 7 steps. Draw the two on a number line and count."}]'::jsonb WHERE id = 'e64740e6-b862-4e5b-a000-fc019a9b4c63';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Ranked by number of digits", "wrong": "0.1; 0.09; 0.089", "message": "Your order runs shortest to longest, so you treated extra digits as extra size. Pad all three to thousandths: 0.090, 0.100, 0.089. Now compare tenths first — only 0.100 has a 1 there, so it is the largest — then hundredths."}, {"tag": "leading-zero-dropped", "label": "Read 0.09 as 0.9", "wrong": "0.089; 0.1; 0.09", "message": "You put 0.089 first, which is right, and 0.1 before 0.09 — that would hold if 0.09 were 0.9. The zero after the point is a placeholder that keeps the 9 in the hundredths. 0.09 is nine hundredths, less than ten hundredths (0.1)."}, {"tag": "place-value-off", "label": "Swapped 0.09 and 0.089", "wrong": "0.09; 0.089; 0.1", "message": "0.1 as the largest is right. Then 0.09 went below 0.089, as if 89 beats 9. Pad to thousandths: 0.090 and 0.089. Same tenths, same hundredths, and 0 thousandths is less than 9, so 0.089 is the smaller one and comes first."}]'::jsonb WHERE id = '5ae44190-6e23-4b37-8aa0-da87f18f999c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "truncated-not-rounded", "label": "Cut off the hundredths", "expr": "a+b/10", "message": "You kept the tenths digit and dropped the 6 — that is truncating, not rounding. The 6 in the hundredths is 5 or more, so it pushes the tenths digit up by one: {a}.{b}6 rounds to the next tenth above {a}.{b}."}, {"tag": "place-value-off", "label": "Rounded to a whole number", "expr": "a+1", "message": "You rounded, but to the nearest whole. The nearest tenth keeps one digit after the point. Underline the tenths digit ({b}), look at the 6 beside it, and since 6 is 5 or more the {b} goes up by one."}, {"tag": "digit-not-value", "label": "Wrote only the rounded tenths", "expr": "(b+1)/10", "message": "You rounded the tenths correctly — the 6 pushes {b} up by one. The answer is the whole number, ones place included: {a} and the new tenths digit, not the tenths alone."}]'::jsonb WHERE id = 'f6cfd880-2194-4416-a2a6-18183d57ed01';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "negative-order-flipped", "label": "Chose −3 since 3 < 8", "wrong": "-3", "message": "You compared 8 and 3 and picked the smaller digit. Below zero the order flips: the bigger the number after the minus, the further left on the number line, and further left is colder. −8 is 8 below freezing; −3 is only 3 below."}, {"tag": "sign-dropped", "label": "Dropped the minus sign", "wrong": "3", "message": "You went for the 3, which is the smaller number, and left off the sign. Both temperatures are negative, and among negatives the one further from zero is lower. −8 is further from zero than −3, so −8 is colder. Keep the minus in your answer."}]'::jsonb WHERE id = '6f7032f0-d75a-4b93-bd0b-891a27169dfb';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "endpoint-not-between", "label": "Gave one of the endpoints", "wrong": "3.7", "message": "3.7 is one of the two ends, so it is not between them. There is room in the gap: write both as hundredths, 3.60 and 3.70, and any number from 3.61 to 3.69 fits. Try 3.65."}, {"tag": "interval-wrong-end", "label": "Gave the starting endpoint", "wrong": "3.6", "message": "3.6 is the lower end, not a number between the two. Write both as hundredths — 3.60 and 3.70 — and the gap opens up: 3.61, 3.62, up to 3.69 all sit between. Pick one of those."}, {"tag": "place-value-off", "label": "Went past 3.7", "wrong": "3.75", "message": "You added a hundredths digit, which is the right move, but on the far side of 3.7 — 3.75 is above both numbers. Between 3.6 and 3.7 means bigger than 3.60 and smaller than 3.70, so the tenths digit stays a 6: 3.65 works."}]'::jsonb WHERE id = '75252cc5-7e56-466f-b77f-a3cdd31d9147';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "more-digits-bigger", "label": "Picked 0.45 for having more digits", "wrong": "0.45", "message": "You picked 0.45, the longer number. More digits after the point do not mean more value. Line them up with the same number of places: 0.50 and 0.45. Tenths first — 5 beats 4 — so 0.5 is larger."}, {"tag": "decimal-shift", "label": "Compared 5 and 45 as whole numbers", "wrong": "45", "message": "You dropped the decimal points and compared 5 with 45. The point matters: 0.5 is 5 tenths and 0.45 is 4 tenths and 5 hundredths. Give both the same number of places — 0.50 and 0.45 — and then the digits can be compared: 50 beats 45."}]'::jsonb WHERE id = 'c57891dd-fd8a-48a8-ac79-c2692f5c8c70';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "moved the point one place for percent", "wrong": "0.4; 4%", "message": "The decimal is right: 2 ÷ 5 = 0.4. Going from decimal to percent moves the point two places, not one. 0.4 → 4.0 → 40, so it is 40%. Check: 0.4 is nearly half, and half is 50%."}, {"tag": "percent-decimal-swap", "label": "kept the decimal and added %", "wrong": "0.4; 0.4%", "message": "2 ÷ 5 = 0.4 is right. But 0.4% would be less than one percent — a tiny sliver. Percent means per hundred, so multiply the decimal by 100 before you write the sign: 0.4 × 100 = 40%."}, {"tag": "inverted-ratio", "label": "divided 5 by 2", "wrong": "2.5; 250%", "message": "You divided, but the other way round. 2/5 means 2 ÷ 5, top divided by bottom. 2/5 is less than one whole, so the decimal has to be below 1: 0.4, which is 40%."}, {"tag": "digit-not-value", "label": "read 2/5 as 0.2", "wrong": "0.2; 20%", "message": "You took the top digit as tenths. A fraction is a division: 2/5 means 2 ÷ 5. Five goes into 2.0 four tenths of a time, so 0.4 and 40%. Check: 2/5 is more than 1/5 = 0.2."}]'::jsonb WHERE id = '50c9c110-52d0-4613-9c68-35365a5025d9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "moved the point one place for percent", "wrong": "3/5; 6%", "message": "3/5 is right. For the percent, the point moves two places, not one: 0.6 → 60. Check: 0.6 is more than half, and half is 50%, so 6% cannot be it."}, {"tag": "percent-decimal-swap", "label": "kept the decimal and added %", "wrong": "3/5; 0.6%", "message": "3/5 is right. 0.6% would be less than one hundredth — a tiny sliver. Percent means per hundred, so multiply 0.6 by 100 first: 60%."}, {"tag": "place-value-off", "label": "read 0.6 as 6 hundredths", "wrong": "6/100; 6%", "message": "The 6 in 0.6 sits in the tenths place, one step right of the point, so it is 6/10, not 6/100. 6/10 reduces to 3/5, and 6 tenths is 60 hundredths, so 60%."}, {"tag": "digit-not-value", "label": "wrote 0.6 as 1/6", "wrong": "1/6; 60%", "message": "60% is right. For the fraction, 0.6 means six tenths, 6/10, which reduces to 3/5. 1/6 is about 0.17 — check by dividing: 1 ÷ 6 does not give 0.6."}]'::jsonb WHERE id = '8462048b-3e5b-4384-9a90-8c7a49c5d9ed';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "picked 0.6, read 2/3 as 0.23", "wrong": "0.6", "message": "You chose 0.6. To compare, put both in the same form: 2 ÷ 3 = 0.666..., which is more than 0.6. The digits 2 and 3 do not become 0.23 — a fraction is a division, top by bottom."}, {"tag": "inverted-ratio", "label": "divided 3 by 2", "wrong": "1.5", "message": "You compared by dividing, which is the right move, but 2/3 means 2 ÷ 3, not 3 ÷ 2. 2/3 is less than one whole, so it is 0.666..., still bigger than 0.6."}]'::jsonb WHERE id = 'bfc5460d-e158-47a7-aa54-41a70073d723';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "percent-as-whole", "label": "left the decimal as 25", "wrong": "1/4; 25", "message": "1/4 is right. For the decimal, percent means per hundred, so 25% is 25 ÷ 100 = 0.25. Check: a quarter is less than one whole, so the decimal must be below 1."}, {"tag": "decimal-shift", "label": "moved the point one place", "wrong": "1/4; 2.5", "message": "1/4 is right. Percent to decimal moves the point two places left, not one: 25 → 2.5 → 0.25. Check: a quarter is less than one whole, so 2.5 is too big."}, {"tag": "digit-not-value", "label": "wrote 25% as 1/25", "wrong": "1/25; 0.25", "message": "0.25 is right. For the fraction, 25% is 25 out of 100, so 25/100, which reduces to 1/4. 1/25 would be 4 out of 100, only 4%."}]'::jsonb WHERE id = '0c075d63-6b27-4c3a-8d5d-a469315370e9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "wrote the digits 1 and 8", "wrong": "0.18", "message": "A fraction is a division: 1/8 means 1 ÷ 8. Write it out: 8 goes into 1.000 as 0.125. Check with a landmark: 1/4 is 0.25, so 1/8 is half of that, 0.125."}, {"tag": "inverted-ratio", "label": "divided 8 by 1", "wrong": "8", "message": "You divided, but bottom by top. 1/8 is one piece of eight, less than one whole, so its decimal has to be below 1: 1 ÷ 8 = 0.125."}, {"tag": "decimal-shift", "label": "point one place too far right", "wrong": "1.25", "message": "The digits 125 are right — 1 ÷ 8 does give 125 thousandths. But 1/8 is less than one whole, so the value must be below 1: 0.125."}]'::jsonb WHERE id = '96c6e13f-031c-4918-b003-1034fbc40b90';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "part-not-whole", "label": "gave the full part", "wrong": "62.5%", "message": "5/8 = 62.5% is right, and that is the part that is FULL. The question asks for empty. The whole tank is 100%, so empty is 100 − 62.5 = 37.5%, which is the other 3/8."}, {"tag": "intermediate-answer", "label": "stopped at 1/8 = 12.5%", "wrong": "12.5%", "message": "1/8 = 12.5% is the right first step. But 3 eighths are empty (8 − 5), so multiply: 3 × 12.5 = 37.5%."}, {"tag": "rounded-early", "label": "rounded 3/8 to 0.4", "wrong": "40%", "message": "3/8 empty is right. 3 ÷ 8 is exactly 0.375, so 37.5%. Keep the full decimal until the last step — rounding 0.375 up to 0.4 changes the answer by a whole 2.5%."}]'::jsonb WHERE id = 'd296e84a-9f62-4b8c-9a22-f6f78455cdf7';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "picked 70%, compared numerals", "wrong": "70%", "message": "You chose 70%. To compare, put both in the same form: 3 ÷ 4 = 0.75 = 75%, which is more than 70%. The numerals 3 and 4 look small, but 3/4 means three quarters of the whole."}, {"tag": "percent-as-whole", "label": "compared 70 with 0.75", "wrong": "70", "message": "You typed 70 — that reads as 70 wholes, not 70%. Convert both to the same form before comparing: 70% = 0.70 and 3/4 = 0.75, so 3/4 is bigger."}]'::jsonb WHERE id = '31e62803-8e68-44f2-bcbc-2ce06230f19e';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "part-not-whole", "label": "gave the fraction eaten", "wrong": "3/8", "message": "3/8 is the part you ATE. The question asks what is left. 8 − 3 = 5 slices remain out of 8, so 5/8. The two parts should add to one whole: 3/8 + 5/8 = 8/8."}, {"tag": "digit-not-value", "label": "gave slices, not a fraction", "wrong": "5", "message": "5 slices left is right. A fraction compares the part to the whole pizza: 5 slices out of 8, written 5/8."}, {"tag": "inverted-ratio", "label": "compared left to eaten", "wrong": "3/5", "message": "You compared the 3 eaten to the 5 left. A fraction of the pizza needs the whole pizza on the bottom: 8 slices. 5 left out of 8 is 5/8."}]'::jsonb WHERE id = 'a226c6e4-7dce-48cc-afea-0667d666d75d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "symmetric-percent", "label": "said it returns to 100%", "wrong": "100%", "message": "Up 50% and down 50% look like they cancel, but each percent is taken of a different number. Try $100: up 50% is $150, then 50% off $150 is $75. It ends at 75% of the start — the drop was taken from the bigger number."}, {"tag": "added-not-multiplied", "label": "added +50 and −50 to get 0", "wrong": "0%", "message": "You added the percents: +50 − 50 = 0. Percent changes multiply, they do not add. Try $100: × 1.5 gives $150, then × 0.5 gives $75. The net change is −25%, and the price sits at 75% of the start."}, {"tag": "part-not-whole", "label": "gave the 25% lost, not the price", "wrong": "25%", "message": "$100 → $150 → $75 is right, and 25% is what was lost. The question asks where the price ends up: 75% of the original, so no, it is not back where it started."}]'::jsonb WHERE id = 'e8a2a72e-0817-4333-adb1-80cf5a37d877';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "moved the point one place", "expr": "a/10", "message": "The point moved one place, but percent means per hundred, so it moves two: {a} → {a}/100. Check: {a}% is less than one whole, so the decimal must be below 1."}, {"tag": "percent-as-whole", "label": "left the percent as a whole number", "expr": "a", "message": "{a} on its own reads as {a} wholes. The % sign means ÷ 100, so {a}% = {a}/100 as a decimal. Check: 100% is 1, so {a}% has to be below 1."}, {"tag": "power-of-ten", "label": "moved the point three places", "expr": "a/1000", "message": "The point went one place too far. Percent is per hundred, so divide by 100 exactly, not 1000: {a}/100. Check with a landmark: 50% is 0.5, one place after the point."}, {"tag": "percent-decimal-swap", "label": "kept the % sign on the decimal", "expr": "a/10000", "message": "The division is right, but the % sign was left on. Writing the decimal with a % after it divides by 100 again, making it a hundred times too small. The decimal form drops the sign: {a}/100 with no %."}]'::jsonb WHERE id = 'e22f4e73-647b-4a46-af57-1c8f69285db1';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "moved the point one place", "wrong": "3.5%", "message": "7 ÷ 20 = 0.35 is right. Decimal to percent moves the point two places, not one: 0.35 → 35%. Check: 7/20 is more than 1/4, and 1/4 is 25%."}, {"tag": "percent-decimal-swap", "label": "kept the decimal and added %", "wrong": "0.35%", "message": "0.35 is the right decimal. But 0.35% would be less than one percent. Percent means per hundred, so scale the fraction to hundredths: 7/20 = 35/100 = 35%."}, {"tag": "inverted-ratio", "label": "divided 20 by 7", "wrong": "286%", "message": "You divided, but bottom by top. 7/20 is 7 ÷ 20, and it is less than one whole, so it must be under 100%. Multiply top and bottom by 5 to get hundredths: 35/100 = 35%."}]'::jsonb WHERE id = '8dd2e9e2-f91a-4e19-ad8b-0bdde1e00222';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "percent-as-whole", "label": "subtracted {a} dollars", "expr": "b - a", "message": "You took ${a} off, but the discount is {a} PERCENT of the price, not {a} dollars. Find {a}% of ${b} first — {a}/100 × {b} — then subtract that from ${b}."}, {"tag": "decimal-shift", "label": "used {a}% as 0.0{a}", "expr": "b - a*b/1000", "message": "You subtracted a discount, which is the right plan, but the percent was a tenth of what it should be. {a}% is {a}/100 = 0.{a}, so the discount is 0.{a} × {b}. Check: {a}% of ${b} should be a noticeable chunk."}, {"tag": "sign-dropped", "label": "added the discount", "expr": "b + a*b/100", "message": "The discount amount is right — {a}% of ${b}. But a discount comes OFF the price, so subtract it. Check: a sale price is lower than the ticket price."}]'::jsonb WHERE id = 'bcdcd404-a96e-4bd2-88ae-bd9253a8fa12';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "part-not-whole", "label": "divided by the new score", "expr": "100*(b-a)/b", "message": "The change, {b} − {a}, is right. But percent increase compares the change to where you STARTED, so divide by {a}, not {b}. ({b} − {a}) ÷ {a} × 100."}, {"tag": "didnt-rearrange", "label": "found new as percent of old", "expr": "100*b/a", "message": "{b} ÷ {a} × 100 tells you the new score as a percent of the old one, which includes the original 100%. The INCREASE is what is above that: subtract first, ({b} − {a}) ÷ {a} × 100."}, {"tag": "intermediate-answer", "label": "gave the point change", "expr": "b - a", "message": "{b} − {a} is the change in points — the right first step. A percent increase compares that change to the original: ({b} − {a}) ÷ {a}, then × 100."}, {"tag": "percent-decimal-swap", "label": "left the ratio as a decimal", "expr": "(b-a)/a", "message": "({b} − {a}) ÷ {a} is exactly the right ratio. To write it as a percent, multiply by 100. Check: going from {a} to {b} is a big jump, so the percent should be well above 1."}]'::jsonb WHERE id = 'd6e59535-2837-472a-afa0-d6af8b796b73';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "place-value-off", "label": "wrote 125 over 100", "wrong": "125/100", "message": "The 5 in 0.125 sits three places after the point, so this is 125 thousandths, 125/1000, not hundredths. 125/1000 reduces to 1/8. Check: 0.125 is less than 1, so the top must be smaller than the bottom."}, {"tag": "digit-not-value", "label": "wrote 1 over 125", "wrong": "1/125", "message": "The digits are there, but 0.125 means 125 thousandths: 125/1000. Divide top and bottom by 125 to get 1/8. Check: 1 ÷ 125 is 0.008, far smaller than 0.125."}, {"tag": "inverted-ratio", "label": "gave the reciprocal, 8", "wrong": "8", "message": "8 is the bottom of the fraction — 1 ÷ 8 gives 0.125 — so you are close. But 0.125 is one eighth of a whole, so the fraction is 1/8, not 8."}]'::jsonb WHERE id = 'c258aa3a-b732-43ff-9e2c-6f9517cc69ba';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "used the percent as tenths", "wrong": "60; 64", "message": "The multiplication 15 × 40 = 600 and 20 × 32 = 640 is right, but percent means per hundred, so divide by 100, not 10: $6.00 and $6.40. Check: a tip is a small part of the bill, not bigger than it."}, {"tag": "percent-decimal-swap", "label": "divided by 100 twice", "wrong": "0.6; 0.64", "message": "15 × 40 = 600 and 20 × 32 = 640 are right. Divide by 100 once to get the tip in dollars: $6.00 and $6.40. Dividing again moves the point one place too far."}, {"tag": "intermediate-answer", "label": "computed the first tip only", "wrong": "6", "message": "15% of $40 = $6.00 is right. Now do the second: 20% of $32 = 0.20 × 32 = $6.40. The smaller bill with the bigger percent comes out ahead here."}]'::jsonb WHERE id = '9a61d3cb-8cdb-4b8d-9905-ce381a97232a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided attempts by makes", "expr": "100*b/a", "message": "You divided, but attempts by makes. The fraction made is makes over attempts, {a}/{b} — part over whole. Then {a} ÷ {b} × 100 gives the percent, which has to be under 100 since you missed some."}, {"tag": "percent-decimal-swap", "label": "left the fraction as a decimal", "expr": "a/b", "message": "{a}/{b} is right and so is the division. To turn that decimal into a percent, multiply by 100. Check: {a} of {b} is a real share of the shots, so the percent should be a two-digit number."}, {"tag": "decimal-shift", "label": "moved the point one place", "expr": "10*a/b", "message": "{a}/{b} is right. Decimal to percent moves the point two places, not one — multiply by 100. Check with a landmark: half the shots would be 50%, so {a} of {b} should land somewhere near that scale."}]'::jsonb WHERE id = '4e4505b1-e34d-47ea-b1ca-6f8aa52652cd';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "percent-as-whole", "label": "multiplied by {a}, not 0.{a}", "expr": "a*b", "message": "Multiplying is the right move, but {a}% is {a}/100, not {a}. So it is {a}/100 × {b}. Check: a percent under 100 gives a part of {b}, which must be smaller than {b}."}, {"tag": "decimal-shift", "label": "moved the point one place", "expr": "a*b/10", "message": "You multiplied, and the digits are right, but percent means per hundred, so divide by 100, not 10: {a} × {b} ÷ 100. Check: {a}% of {b} has to be smaller than {b}."}, {"tag": "inverted-ratio", "label": "divided {b} by the percent", "expr": "100*b/a", "message": "You divided {b} by the decimal form of {a}%. That finds a number that {b} is {a}% OF — the reverse question. Here you want {a}% of {b}, so multiply: {a}/100 × {b}."}]'::jsonb WHERE id = 'a8becc1d-56c3-4680-b612-63b5a9e3b001';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "wrong-form", "label": "gave a percent, not a fraction", "wrong": "60%", "message": "60% is the same value as 0.6, so the conversion is right — but the question asks for a fraction. 0.6 is six tenths, 6/10, and dividing top and bottom by 2 gives 3/5."}, {"tag": "place-value-off", "label": "read 0.6 as hundredths", "wrong": "6/100", "message": "The 6 is one place after the point, which is the tenths place, so 0.6 is 6/10, not 6/100. 6/10 reduces to 3/5. Check: 6/100 is only 0.06."}, {"tag": "digit-not-value", "label": "wrote 1/6", "wrong": "1/6", "message": "0.6 is six tenths, so the 6 goes on top: 6/10, which reduces to 3/5. 1/6 is about 0.17 — check by dividing 1 by 6."}]'::jsonb WHERE id = '17e0768d-110c-42d9-8019-f9dea661acac';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "picked 30% off, compared numerals", "wrong": "30%", "message": "You chose 30% off. To compare, put all three in the same form: 1/3 off is 33.3% off, and paying 2/3 leaves 1/3 off, also 33.3%. Both take more off than 30%. The numeral 30 is bigger than 1 or 3, but 1/3 is bigger than 0.30."}, {"tag": "part-not-whole", "label": "read pay-2/3 as 2/3 off", "wrong": "2/3", "message": "''Pay 2/3 of the price'' means you keep paying 2/3, so the discount is the other 1/3, about 33.3% off. That makes it the same deal as 1/3 off — and both beat 30% off."}]'::jsonb WHERE id = '90329911-79c6-462f-aa28-8f3839c6ae3f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "found {a}% of {b}", "expr": "a*b/100", "message": "You found {a}% of {b}, but {b} is already the {a}% part. The whole is bigger than its part, so divide: {b} ÷ ({a}/100). Check: {a}% of your answer should give {b} back."}, {"tag": "percent-as-whole", "label": "divided by {a}, not 0.{a}", "expr": "b/a", "message": "Dividing is the right move, but divide by the decimal form: {a}% = {a}/100, not {a}. So {b} ÷ ({a}/100). Check: the whole must be larger than the {a}% part, {b}."}, {"tag": "decimal-shift", "label": "used {a}% as tenths, then multiplied", "expr": "a*b/10", "message": "The point moved one place instead of two, and the operation went the other way. {b} is {a}% of the number, so the number is {b} ÷ ({a}/100). Check by taking {a}% of your answer — it should give {b}."}]'::jsonb WHERE id = '1f82f349-72c5-4ac4-b3f4-be29651b18dd';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided by 3 instead of multiplying", "wrong": "3.0 x 10^7 km", "message": "You found the factor 3 between 12 days and 36 days, then divided by it. More days means more distance, so the distance should grow: 9.0 × 10⁷ × 3. Check: your answer is smaller than the 12-day distance."}, {"tag": "intermediate-answer", "label": "gave km per day, not total", "wrong": "7.5 x 10^6 km", "message": "9.0 × 10⁷ ÷ 12 is the distance covered each day, and that part is right. The question asks for 36 days of travel, so there is one more step: multiply that daily distance by 36."}, {"tag": "power-of-ten", "label": "exponent off by one", "wrong": "2.7 x 10^7 km", "message": "The coefficient is right: 9.0 × 3 = 27. Then 27 × 10⁷ has to be rewritten with one digit before the point, and sliding the point left one place pushes the exponent up one: 2.7 × 10⁸."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "wrong": "3", "message": "36 ÷ 12 = 3 is the scale factor, and that is the right first move. The question asks for a distance, so apply the factor to the 12-day distance: 9.0 × 10⁷ km × 3."}]'::jsonb WHERE id = 'abcc34c4-cf99-49d9-8799-61aca2b90cd4';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "scaled up instead of down", "wrong": "640 km", "message": "You set up the proportion with the fuel ratio upside down. 6 L is less fuel than 16 L, so the car goes less far than 240 km, not more. The factor is 6 ÷ 16, and 240 × 6 ÷ 16 is the distance."}, {"tag": "intermediate-answer", "label": "gave km per litre only", "wrong": "15 km", "message": "240 ÷ 16 = 15 km per litre is the right rate. The question asks how far on 6 L, so there is one more step: 15 km per litre × 6 L."}, {"tag": "added-not-multiplied", "label": "subtracted the fuel difference", "wrong": "230 km", "message": "You noticed 6 L is 10 L less than 16 L and took 10 off the distance. Distance and fuel scale by multiplying, not by adding. Find the km per litre first (240 ÷ 16), then multiply by 6."}, {"tag": "substituted-wrong-variable", "label": "cross-multiplied, divided by 240", "wrong": "0.4 km", "message": "You cross-multiplied 16 × 6 and then divided by 240. The unknown is a distance, so the distance 240 belongs on top and the known fuel 16 is what you divide by: 240 × 6 ÷ 16. A car does not go 0.4 km on 6 L."}]'::jsonb WHERE id = 'fdbc78ab-69ba-4ad9-abf2-dc5fd3fcd4db';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-not-multiplied", "label": "added 6 eggs for 6 more people", "wrong": "12 eggs", "message": "You saw 6 more people and added 6 more eggs. Eggs scale with people by a factor, not a fixed amount: each person needs 6 ÷ 4 = 1.5 eggs, so 10 people need 1.5 × 10."}, {"tag": "inverted-ratio", "label": "scaled down instead of up", "wrong": "2.4 eggs", "message": "You used 4 ÷ 10 as the factor, which shrinks the recipe. 10 people is more than 4, so the eggs should go up: the factor is 10 ÷ 4 = 2.5, and 6 × 2.5 is the answer."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "wrong": "2.5", "message": "10 ÷ 4 = 2.5 is the scale factor, and finding it first is the right move. The question asks for eggs, so apply the factor to the 6 eggs: 6 × 2.5."}, {"tag": "intermediate-answer", "label": "gave eggs per person only", "wrong": "1.5 eggs", "message": "6 ÷ 4 = 1.5 eggs per person is the right rate. The question asks for 10 people, so there is one more step: 1.5 × 10."}]'::jsonb WHERE id = '0d974e4c-aa64-4081-bde8-70f76ac83661';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "gave the price of one pen", "wrong": "1.40", "message": "4.20 ÷ 3 = 1.40 per pen is the right rate. The question asks about 7 pens, so there is one more step: 1.40 × 7."}, {"tag": "added-not-multiplied", "label": "added 4 for 4 more pens", "wrong": "8.20", "message": "You noticed 7 pens is 4 more than 3 and added 4 to the price. Each extra pen costs 1.40, not 1.00. Find the price per pen (4.20 ÷ 3), then multiply by 7."}, {"tag": "inverted-ratio", "label": "scaled down instead of up", "wrong": "1.80", "message": "You used 3 ÷ 7 as the factor, which makes 7 pens cheaper than 3. More pens cost more, so the factor is 7 ÷ 3: 4.20 × 7 ÷ 3."}, {"tag": "multiplied-not-divided", "label": "multiplied by 7, skipped ÷ 3", "wrong": "29.40", "message": "4.20 × 7 treats 4.20 as the price of one pen, but 4.20 buys three. Divide by 3 first to get the price of one, then multiply by 7."}]'::jsonb WHERE id = '7ee2c0bc-d64c-41ac-9710-4df32c80b927';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "used 1 cm = 5 km", "wrong": "45 km", "message": "You multiplied 9 by 5, which treats every centimetre as 5 km. The scale says 2 cm is 5 km, so one centimetre is 5 ÷ 2 = 2.5 km. Then 9 × 2.5."}, {"tag": "inverted-ratio", "label": "used km per cm upside down", "wrong": "3.6 km", "message": "You multiplied 9 by 2 ÷ 5 instead of 5 ÷ 2. Each centimetre stands for more than a kilometre, so the answer has to be bigger than 9. Kilometres per centimetre is 5 ÷ 2 = 2.5, then 9 × 2.5."}, {"tag": "intermediate-answer", "label": "gave km per cm only", "wrong": "2.5 km", "message": "5 ÷ 2 = 2.5 km per centimetre is the right rate. The question asks about 9 cm, so there is one more step: 2.5 × 9."}, {"tag": "added-not-multiplied", "label": "added the difference 5 − 2", "wrong": "12 km", "message": "You treated the scale as adding 3 to the map distance. A scale is a multiplier: each centimetre stands for 2.5 km, so 9 cm stands for 9 × 2.5 km."}]'::jsonb WHERE id = 'e0a7038b-3aaa-4a2d-b9ec-a3d9799736fe';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided by 5 instead of multiplying", "expr": "a/5", "message": "You divided {a} by 5. Every centimetre on the map stands for 5 real kilometres, so the real distance is bigger than the map distance: {a} × 5."}, {"tag": "added-not-multiplied", "label": "added 5 instead of multiplying", "expr": "a+5", "message": "You added 5 to {a}. A scale is a multiplier, not an amount to add: each of the {a} centimetres is worth 5 km, so the distance is {a} × 5."}, {"tag": "unit-not-converted", "label": "copied the map distance as km", "expr": "a", "unit": "km", "message": "{a} is the map measurement in centimetres. The scale converts it: each centimetre is 5 km, so multiply {a} by 5 to get the real distance."}]'::jsonb WHERE id = 'a8c0a6d0-fc60-4af7-a339-5625638c809f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided by 3 instead of tripling", "expr": "a/3", "message": "You found the factor 3 between 12 and 36 cookies, then divided by it. More cookies need more flour, so the flour goes up: {a} × 3."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "expr": "3", "message": "36 ÷ 12 = 3 is the scale factor, and that is the right first move. The question asks for cups of flour, so apply the factor to the {a} cups: {a} × 3."}, {"tag": "added-not-multiplied", "label": "added the extra 24 cookies", "expr": "a+24", "message": "You added the 24 extra cookies to the flour. Cookies and cups are different things, and they scale by a factor: 36 is 3 × 12, so the flour is also 3 × {a}."}]'::jsonb WHERE id = '1bdf950e-8d5b-4dd4-a4df-d49d6f0c07b6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "multiplied count by price", "expr": "b*a", "message": "You multiplied {a} by {b}. The ${b} is the price of all {a} bars together, so sharing it out means dividing: {b} ÷ {a} for one bar. Check: one bar cannot cost more than the whole box."}, {"tag": "total-not-rate", "label": "answered the total price", "expr": "b", "message": "${b} is what all {a} bars cost together. The question asks for one bar, so divide the total by the count: {b} ÷ {a}."}, {"tag": "subtracted-not-divided", "label": "subtracted count from price", "expr": "b-a", "message": "You took {a} away from {b}. Splitting a price across {a} bars is division, not subtraction: {b} ÷ {a} gives what one bar costs."}]'::jsonb WHERE id = 'dbee229d-fb30-4c64-8edf-b5eaf0d5f6f9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "used pages ÷ minutes upside down", "wrong": "40 minutes", "message": "You multiplied 60 pages by 20 ÷ 30 instead of 30 ÷ 20. Each page takes 30 ÷ 20 = 1.5 minutes, so 60 pages take 60 × 1.5. Check: three times the pages cannot take less time than 60 minutes."}, {"tag": "added-not-multiplied", "label": "added the 10-minute difference", "wrong": "70 minutes", "message": "You added 10 to 60 because 30 is 10 more than 20. Reading time scales by a factor: 60 pages is 3 × 20 pages, so the time is 3 × 30 minutes."}, {"tag": "intermediate-answer", "label": "gave minutes per page only", "wrong": "1.5 minutes", "message": "30 ÷ 20 = 1.5 minutes per page is the right rate. The question asks about 60 pages, so there is one more step: 1.5 × 60."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "wrong": "3", "message": "60 ÷ 20 = 3 is the scale factor, and that is the right first move. The question asks for a time, so apply the factor to the 30 minutes: 30 × 3."}]'::jsonb WHERE id = '1bfa7254-734d-4d05-915f-e6ef86381c95';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "used gallons per mile", "expr": "10*a/b", "message": "You set up the rate as {a} ÷ {b}, gallons per mile, then multiplied by 10. The question asks for miles, so the rate you need is miles per gallon: {b} ÷ {a}. Then multiply that by 10 gallons."}, {"tag": "intermediate-answer", "label": "gave miles per gallon only", "expr": "b/a", "message": "{b} ÷ {a} is the miles per gallon, and that rate is right. The question asks how far on 10 gallons, so there is one more step: multiply the rate by 10."}, {"tag": "multiplied-not-divided", "label": "multiplied by 10, skipped ÷ gallons", "expr": "10*b", "message": "{b} × 10 treats {b} miles as the distance for one gallon, but it took {a} gallons. Divide {b} by {a} to get miles per gallon, then multiply by 10."}, {"tag": "added-not-multiplied", "label": "added the extra gallons as miles", "expr": "b+10-a", "message": "You added the extra gallons on to the miles. Each gallon is worth {b} ÷ {a} miles, not one mile, so find the miles per gallon first and multiply by 10."}]'::jsonb WHERE id = 'f859c8a3-8e48-4b97-acfc-c7258286391c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "total-not-rate", "label": "picked the cheaper total price", "wrong": "6", "message": "You chose the pack with the lower price tag. A better buy is about the price of one roll, not the total. Divide each price by its roll count (4.50 ÷ 6 and 5.60 ÷ 8) and compare the two unit prices."}, {"tag": "intermediate-answer", "label": "gave a unit price, not the pack", "wrong": "0.70", "message": "0.70 per roll is the right unit price for the 8-pack, and 0.75 for the 6-pack. The question asks which is the better buy, so the answer is the pack itself: 8 rolls for $5.60."}, {"tag": "subtracted-not-divided", "label": "subtracted the two totals", "wrong": "1.10", "message": "5.60 − 4.50 = 1.10 is how much more the 8-pack costs, but it also has more rolls. Comparing packs means dividing price by rolls: 4.50 ÷ 6 and 5.60 ÷ 8, then choosing the smaller unit price."}]'::jsonb WHERE id = '95549019-2511-499e-8e46-1c337eab0988';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "multiplied pairs by 3", "expr": "a*3", "message": "You multiplied {a} by 3. Each pack already holds 3 pairs, so grouping {a} pairs into threes is division: {a} ÷ 3. Check: you need fewer packs than pairs."}, {"tag": "subtracted-not-divided", "label": "subtracted 3 from the pairs", "expr": "a-3", "message": "You took 3 away from {a}. Sorting {a} pairs into packs of 3 asks how many threes fit, which is division: {a} ÷ 3."}, {"tag": "inverted-ratio", "label": "divided 3 by the pairs", "expr": "3/a", "message": "You divided the other way round, 3 ÷ {a}. The number of packs is pairs ÷ pairs per pack, so {a} ÷ 3. Check: a fraction of a pack cannot hold {a} pairs."}]'::jsonb WHERE id = '5af7f276-fdf3-4247-81cd-06da60872743';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "scaled down instead of up", "wrong": "2 lb", "message": "You used 18 ÷ 45 as the factor, which shrinks the bag. 45 people is more than 18, so the rice goes up: the factor is 45 ÷ 18 = 2.5, and 5 × 2.5 is the answer."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "wrong": "2.5", "message": "45 ÷ 18 = 2.5 is the scale factor, and that is the right first move. The question asks for pounds of rice, so apply the factor to the 5-lb bag: 5 × 2.5."}, {"tag": "substituted-wrong-variable", "label": "divided people by pounds", "wrong": "9 lb", "message": "45 ÷ 5 pairs the new people with the old pounds, which mixes the two quantities. Compare like with like: 45 people ÷ 18 people = 2.5, then scale the 5 lb by 2.5."}, {"tag": "added-not-multiplied", "label": "added the 27 extra people", "wrong": "32 lb", "message": "You added the 27 extra people on to the pounds. People and pounds are different things, and they scale by a factor: 45 is 2.5 × 18, so the rice is also 2.5 × 5 lb."}]'::jsonb WHERE id = 'f0ccd967-63f1-4cc8-86a6-e953f2caa4f1';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "left the distance in centimetres", "expr": "a*250000", "unit": "km", "message": "{a} × 250,000 is the real distance in centimetres, and that step is right. The question asks for kilometres, so convert: 100 cm in a metre and 1000 m in a kilometre, so divide by 100,000."}, {"tag": "intermediate-answer", "label": "stopped at metres", "expr": "a*2500", "unit": "km", "message": "You converted {a} × 250,000 cm to metres, which is right so far. There is one more step to kilometres: divide by 1000. Each centimetre on this map is 2.5 km."}, {"tag": "power-of-ten", "label": "conversion off by a factor of 10", "expr": "a*25", "message": "You set up the scale correctly but slipped a power of ten in the conversion. 250,000 cm ÷ 100 = 2500 m, and 2500 m ÷ 1000 = 2.5 km. So each centimetre is 2.5 km, and {a} cm is {a} × 2.5."}, {"tag": "inverted-ratio", "label": "divided by 2.5 instead of multiplying", "expr": "a/2.5", "message": "You found 2.5 km per centimetre, then divided by it. Real distances are bigger than map distances, so multiply: {a} × 2.5."}]'::jsonb WHERE id = '8ba8071d-bb2c-4bf6-8eb3-cb3aecf6d662';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse", "label": "doubled the time with the crew", "wrong": "12 hours", "message": "You doubled the time because the crew doubled. More painters means the fence gets done sooner, not later. This is an inverse relationship: twice the workers, half the time, so 6 ÷ 2."}, {"tag": "added-not-multiplied", "label": "subtracted 4 hours for 4 workers", "wrong": "2 hours", "message": "You spotted that more workers means less time, which is right. But the time shrinks by a factor, not by a fixed 4 hours: the crew doubled, so the time halves, 6 ÷ 2."}, {"tag": "intermediate-answer", "label": "gave hours per worker", "wrong": "1.5 hours", "message": "6 ÷ 4 = 1.5 is a rate, not the finish time. Think in worker-hours instead: 4 workers × 6 hours = 24 worker-hours of painting. Spread across 8 workers, that is 24 ÷ 8 hours."}, {"tag": "substituted-wrong-variable", "label": "divided 6 by the new crew", "wrong": "0.75 hours", "message": "6 ÷ 8 mixes the old time with the new crew. The job is 4 × 6 = 24 worker-hours; 8 workers share that, so 24 ÷ 8. Check: a crew of 8 finishing in 45 minutes would be a lot faster than doubling the crew allows."}]'::jsonb WHERE id = '97d93079-371b-4861-93e9-0dee3c60a6a3';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "part-not-whole", "label": "used 8 parts as the whole", "wrong": "16.5 cups", "message": "You scaled 3 parts against 8 parts, but 8 is only the water. The whole drink is 3 + 8 = 11 parts. 44 ÷ 11 = 4 cups per part, and the mix is 3 parts: 3 × 4."}, {"tag": "intermediate-answer", "label": "gave cups per part only", "wrong": "4 cups", "message": "44 ÷ 11 = 4 cups per part is the right first step. The mix is 3 of those parts, so there is one more step: 3 × 4."}, {"tag": "substituted-wrong-variable", "label": "answered the water, not the mix", "wrong": "32 cups", "message": "Your 11-part setup is right and 4 cups per part is right, but 8 × 4 is the water. The question asks for the mix, which is 3 parts: 3 × 4."}]'::jsonb WHERE id = '882cd511-9466-4c15-99a7-342f5c434a1b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "scaled 45 down instead of up", "expr": "45*a/100", "message": "You multiplied 45 minutes by {a} ÷ 100, which shrinks it. A full battery is 100%, which is more than {a}%, so the time goes up: 45 × 100 ÷ {a}."}, {"tag": "intermediate-answer", "label": "gave minutes per percent only", "expr": "45/a", "message": "45 ÷ {a} is the minutes per percent of battery, and that rate is right. The question asks about a full 100%, so there is one more step: multiply by 100."}, {"tag": "added-not-multiplied", "label": "added the remaining percent as minutes", "expr": "45+100-a", "message": "You added the remaining {a}-to-100 percentage points on to the 45 minutes. Percent and minutes are different things, and they scale by a factor: 100 ÷ {a} times as much battery means 100 ÷ {a} times as many minutes."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "expr": "100/a", "message": "100 ÷ {a} is the scale factor from {a}% to a full charge, and that is the right first move. The question asks for minutes, so apply the factor to the 45 minutes: 45 × 100 ÷ {a}."}]'::jsonb WHERE id = '75ee7a27-a262-4a54-abbf-64ca430e5aae';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-not-multiplied", "label": "added 6 in to the height", "wrong": "12 in", "message": "You added 6 to the height because the width grew by 6. An enlargement scales by a factor, so the photo keeps its shape: the width went 4 to 10, a factor of 2.5, and the height goes 6 × 2.5."}, {"tag": "inverted-ratio", "label": "inverted the height-to-width ratio", "wrong": "6.67 in", "message": "You multiplied 10 by 4 ÷ 6 instead of 6 ÷ 4. The photo is taller than it is wide, so the new height must be more than 10 in. Height ÷ width = 6 ÷ 4 = 1.5, then 10 × 1.5."}, {"tag": "scale-factor-not-quantity", "label": "answered the scale factor", "wrong": "2.5", "message": "10 ÷ 4 = 2.5 is the enlargement factor, and that is the right first move. The question asks for the new height, so apply the factor to 6 in: 6 × 2.5."}, {"tag": "multiplied-not-divided", "label": "multiplied 10 by 6, skipped ÷ 4", "wrong": "60 in", "message": "10 × 6 is a start, but the proportion needs the old width too: new height = 10 × 6 ÷ 4. Check: a 5-foot-tall print of a 10-inch-wide photo would not keep the same shape."}]'::jsonb WHERE id = 'a5ff326f-ca47-42c2-a372-9c5d27bae20f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "multiplied area by coverage", "expr": "a*b", "message": "You multiplied {b} by {a}. Each litre already covers {a} m², so the question is how many lots of {a} fit into {b}: {b} ÷ {a}. Check: a {b} m² wall should take fewer litres than square metres."}, {"tag": "inverted-ratio", "label": "divided coverage by area", "expr": "a/b", "message": "You divided the other way round, {a} ÷ {b}. Litres = area ÷ coverage per litre, so {b} ÷ {a}. Check: a fraction of a litre cannot paint a {b} m² wall."}, {"tag": "subtracted-not-divided", "label": "subtracted coverage from area", "expr": "b-a", "message": "You took {a} away from {b}. Each litre takes care of {a} m², so counting litres means asking how many {a}s are in {b}: {b} ÷ {a}."}]'::jsonb WHERE id = '02af6d07-9a0a-4cfe-ac7e-a348b8a781e9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "gave the price of one ticket", "expr": "b/a", "message": "{b} ÷ {a} is the price of one ticket, and that rate is right. The question asks about 7 tickets, so there is one more step: multiply by 7."}, {"tag": "inverted-ratio", "label": "used tickets per dollar", "expr": "7*a/b", "message": "You set up the rate as {a} ÷ {b}, tickets per dollar, then multiplied by 7. The question asks for dollars, so the rate you need is dollars per ticket: {b} ÷ {a}. Then multiply by 7 tickets."}, {"tag": "multiplied-not-divided", "label": "multiplied by 7, skipped ÷ tickets", "expr": "7*b", "message": "{b} × 7 treats ${b} as the price of one ticket, but it bought {a}. Divide {b} by {a} to get the price of one, then multiply by 7."}]'::jsonb WHERE id = 'a1ddd105-3c08-4e6c-b7f4-6e5024749dca';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "Divided by 2 and 3, not squared", "wrong": "18 N/kg; 12 N/kg", "message": "You saw the field gets weaker with distance and divided — that direction is right. But gravity is inverse-SQUARE, so the divisor is the distance factor squared: 2² = 4 and 3² = 9. Try 36 ÷ 4 and 36 ÷ 9."}, {"tag": "multiplied-not-divided", "label": "Multiplied by the square instead", "wrong": "144 N/kg; 324 N/kg", "message": "You squared the distance factors — 4 and 9 — which is the key step. But farther away means a weaker field, so those numbers divide 36 rather than multiply it. Check: at 2d the field should be smaller than 36."}, {"tag": "squared-not-doubled", "label": "Multiplied by 2 and 3", "wrong": "72 N/kg; 108 N/kg", "message": "You scaled by the distance factor, but in the growing direction and without the square. Farther out the field drops, and it drops by the factor squared: 36 ÷ 2² at 2d and 36 ÷ 3² at 3d."}, {"tag": "intermediate-answer", "label": "Gave the divisors, not the field", "wrong": "4 N/kg; 9 N/kg", "message": "4 and 9 are the right divisors — 2² and 3². The question asks for the field itself, so finish the step: 36 ÷ 4 and 36 ÷ 9, still in N/kg."}]'::jsonb WHERE id = '4b375be1-d48f-428c-ad87-664a3b0d9b44';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "Divided by 5, not 25", "wrong": "20 units", "message": "You divided by the distance factor, which is the right direction — light spreads out and gets dimmer. But intensity follows an inverse SQUARE, so the divisor is 5² = 25, not 5. Try 100 ÷ 25."}, {"tag": "intermediate-answer", "label": "Gave 5² instead of the intensity", "wrong": "25 units", "message": "25 is the correct divisor — 5 squared. The question asks for the intensity at 5 m, so one more step: 100 ÷ 25."}, {"tag": "multiplied-not-divided", "label": "Multiplied by 25 instead of dividing", "wrong": "2500 units", "message": "You squared the distance factor to get 25 — that''s the key move. But farther from the source means dimmer, so 25 divides the 100 rather than multiplies it. Check: the answer at 5 m must be less than 100."}, {"tag": "squared-not-doubled", "label": "Multiplied by 5", "wrong": "500 units", "message": "You scaled by 5, but light gets dimmer with distance, not brighter, and it drops by the factor squared. Write it as 100 ÷ 5² and compare: the answer must be smaller than 100."}]'::jsonb WHERE id = 'a0be357a-4c3f-4da7-8d3a-8280fa809166';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "F/4 — divided by 4, not 16", "wrong": "1/4", "message": "You divided by 4 — the direction is right, since force weakens with distance. But gravity is inverse-SQUARE, so the divisor is 4² = 16. At 4r the force is F/16."}, {"tag": "doubled-not-squared", "label": "F/8 — doubled 4 instead of squaring", "wrong": "1/8", "message": "You knew the divisor grows faster than the distance factor, but 4 × 2 = 8 is doubling. Squaring means 4 × 4 = 16, so the force at 4r is F/16."}, {"tag": "multiplied-not-divided", "label": "4F — grew instead of shrank", "wrong": "4", "message": "You scaled by the distance factor, but in the growing direction. Moving farther out makes gravity weaker, and it weakens by the factor squared: F ÷ 4² = F/16."}]'::jsonb WHERE id = 'ca37a79e-25c3-41a2-b374-f68cebc86056';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "x2 — halved distance, doubled field", "wrong": "2", "message": "You saw the distance halve and made the field stronger — the direction is right. But a field follows an inverse SQUARE, so halving the distance multiplies it by 2² = 4, not 2."}, {"tag": "multiplied-not-divided", "label": "÷4 — direction flipped", "wrong": "0.25", "message": "You squared the factor — 2² = 4 — which is the key step. But moving CLOSER to a source makes the field stronger, so the field is multiplied by 4, not divided. Closer means more, not less."}, {"tag": "linear-not-inverse", "label": "÷2 — halved distance, halved field", "wrong": "0.5", "message": "You halved the field along with the distance. Two things to revisit: closer means stronger, and the change is by the square of the factor. Half the distance gives 2² = 4 times the field."}]'::jsonb WHERE id = 'c5157ef6-e746-4317-8023-a22f8f508b5d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "1/4 — squared instead of cubed", "wrong": "1/4", "message": "You applied the halving twice, which is squaring: (1/2)² = 1/4. This relationship is a cube, so the factor is applied three times: (1/2)³ = 1/8."}, {"tag": "linear-not-inverse", "label": "1/2 — treated it as direct linear", "wrong": "1/2", "message": "You halved y along with x — that''s what a straight-line relationship would do. Here y depends on x³, so the factor 1/2 gets cubed: (1/2)³ = 1/8."}, {"tag": "doubled-not-squared", "label": "1/6 — multiplied by 3, not cubed", "wrong": "1/6", "message": "You used the 3 from the cube, but multiplied by it: 2 × 3 = 6. A cube means multiply the factor by itself three times: 2 × 2 × 2 = 8, so y becomes 1/8."}, {"tag": "multiplied-not-divided", "label": "8 — direction flipped", "wrong": "8", "message": "You cubed the factor 2 to get 8 — that''s the key step. But x got smaller, and y grows with x, so y also gets smaller: y becomes 1/8 of the original, not 8 times it."}]'::jsonb WHERE id = 'd4d7f149-cb11-43e5-a4a2-d7ba396db3a8';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "Area ×2, perimeter ×2", "wrong": "2; 2", "message": "Perimeter ×2 is right — it''s a length, so it scales with the side. Area is side × side, so it picks up the factor twice: 2 × 2 = 4. Sketch it: the doubled square holds four of the original."}, {"tag": "squared-not-doubled", "label": "Area ×4, perimeter ×4", "wrong": "4; 4", "message": "Area ×4 is right — side² picks up the 2 twice. Perimeter is just 4 sides added up, a length, so it only doubles: ×2."}, {"tag": "inverted-ratio", "label": "Area ×2, perimeter ×4 — swapped", "wrong": "2; 4", "message": "You have the two factors, 2 and 4, but on the wrong quantities. Perimeter is a length, so it scales with the side (×2). Area is side², so it scales with the square (×4)."}]'::jsonb WHERE id = '14126b47-0008-45f0-9748-55a721ec5478';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "$30 — doubled the share", "wrong": "$30", "message": "You doubled the share when the number of people doubled. More people sharing the same $60 means LESS each — the relationship is inverse. Twice the people, half the share: $15 ÷ 2. Check: 8 × $30 is far more than $60."}, {"tag": "added-not-multiplied", "label": "$11 — subtracted $4 per person", "wrong": "$11", "message": "You reasoned additively: 4 more people, $4 less each. Sharing is a division, not a subtraction — the share is $60 ÷ (number of people). Check: 8 × $11 isn''t $60. Try $60 ÷ 8."}, {"tag": "linear-not-inverse-square", "label": "$3.75 — quartered instead of halved", "wrong": "$3.75", "message": "You shrank the share, which is right, but by 4 rather than 2. Sharing is plain inverse, not inverse-square: doubling the people halves the share. Check: 8 × $3.75 comes to only $30."}]'::jsonb WHERE id = 'bc3e03a5-de4d-4244-a6a6-f304976a3644';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "doubled-not-squared", "label": "Doubled y instead of tripling", "expr": "a*2", "message": "You scaled y up, which is right for a direct relationship. But x went from 2 to 6 — that''s a factor of 3, not 2. Triple {a}."}, {"tag": "added-not-multiplied", "label": "Added 4 to y like x", "expr": "a+4", "message": "x went up by 4, so you added 4 to y. Proportional means SCALING, not shifting: x tripled (2 → 6), so y triples too. Multiply {a} by 3."}, {"tag": "inverted-ratio", "label": "Divided y by 3", "expr": "a/3", "message": "You used the factor 3, which is the right factor. But y is proportional to x — when x grows, y grows with it. Multiply {a} by 3 rather than dividing."}]'::jsonb WHERE id = '4d399a27-f7ba-4eaf-a70e-25a43cf615f1';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "Doubled the time to 24", "wrong": "24 minutes", "message": "You doubled the time when the faucets doubled. Two faucets pour twice as fast, so the tub fills in LESS time — this is an inverse relationship. Twice the faucets, half the time: 12 ÷ 2."}, {"tag": "linear-not-inverse-square", "label": "Quartered the time to 3", "wrong": "3 minutes", "message": "You shrank the time, which is the right direction, but by 4 rather than 2. Fill time is plain inverse with the number of faucets: two faucets, half the time. 12 ÷ 2."}]'::jsonb WHERE id = '3a858eca-c299-4207-8aa1-02bb495c7201';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "2 — treated it as linear", "wrong": "2", "message": "You doubled y along with x — that''s what y = k·x would do. Here y depends on x², so the factor 2 gets squared: 2² = 4 times bigger."}, {"tag": "doubled-not-squared", "label": "8 — doubled 4 or cubed 2", "wrong": "8", "message": "You went past the square. Squaring the factor 2 means 2 × 2 = 4, done — no extra doubling and no third factor. y becomes 4 times bigger."}, {"tag": "multiplied-not-divided", "label": "1/4 — direction flipped", "wrong": "0.25", "message": "You squared the factor to get 4 — the key step. But y = k·x² grows when x grows, so y is multiplied by 4, not divided. The question asks how many times BIGGER."}]'::jsonb WHERE id = '92c8b2bb-430f-4cd6-9776-ed4bd770b64d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "Halved y instead of quartering", "expr": "a/2", "message": "You made y smaller when x doubled — right direction for an inverse relationship. But this is inverse SQUARE, so the divisor is 2² = 4, not 2. Try {a} ÷ 4."}, {"tag": "multiplied-not-divided", "label": "Multiplied by 4 instead of dividing", "expr": "a*4", "message": "You squared the factor — 2² = 4 — which is the key step. But y = k/x² gets smaller as x grows, since x is on the bottom. Divide: {a} ÷ 4."}, {"tag": "linear-not-inverse", "label": "Doubled y with x", "expr": "a*2", "message": "You doubled y along with x, as a direct relationship would. Here x sits on the bottom and is squared, so doubling x DIVIDES y by 2² = 4. Try {a} ÷ 4."}]'::jsonb WHERE id = '4c100d6f-3896-44f3-a890-7ee6863c1bd5';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "Divided by 3, not 9", "wrong": "12 units", "message": "You found the distance tripled and divided by 3 — the right factor, right direction. But the signal drops with the SQUARE of distance, so the divisor is 3² = 9. Try 36 ÷ 9."}, {"tag": "substituted-wrong-variable", "label": "Divided by 6² instead of 3²", "wrong": "1 unit", "message": "You squared a distance, but the new distance itself (6²) rather than the factor it grew by. From 2 m to 6 m is ×3, so the signal falls by 3² = 9. Try 36 ÷ 9."}, {"tag": "wrong-points", "label": "Divided by 2² instead of 3²", "wrong": "9 units", "message": "You squared the starting distance, 2² = 4, and divided. The number to square is how many times farther you moved: 6 m ÷ 2 m = 3, so divide by 3² = 9."}, {"tag": "multiplied-not-divided", "label": "Multiplied by 9", "wrong": "324 units", "message": "You squared the factor 3 to get 9 — the key step. But the signal drops as you move away, so 9 divides the 36 rather than multiplies it. Check: at 6 m the bars must read less than 36."}]'::jsonb WHERE id = 'bf6ade46-bd49-4ec5-a325-0fcc97b29f76';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "Scaled by b/c instead of c/b", "expr": "a*b/c", "message": "You scaled {a} by a ratio of the x-values, but upside down. x went from {b} to {c}, so the factor is {c} ÷ {b}, and y grows with x. Multiply {a} by {c}/{b}."}, {"tag": "intermediate-answer", "label": "Gave k, not the new y", "expr": "a/b", "message": "{a} ÷ {b} is k — the right first step. The question asks for y when x = {c}, so finish with y = k · x: multiply that k by {c}."}, {"tag": "didnt-rearrange", "label": "Used k = a instead of a/b", "expr": "a*c", "message": "You multiplied by the new x, which is the right shape for y = k·x. But k isn''t {a} — k = y ÷ x = {a} ÷ {b}. Then y = k × {c}."}, {"tag": "added-not-multiplied", "label": "Added the change in x to y", "expr": "a+(c-b)", "message": "x rose by {c} − {b}, so you added that to y. Proportional means scaling, not shifting: find k = {a} ÷ {b}, then y = k × {c}."}]'::jsonb WHERE id = 'd31f68ae-9de4-4de0-a917-ec9b477a858a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "1.5 — time grew with speed", "wrong": "1.5", "message": "You multiplied the time by 1.5. Faster means a SHORTER trip — time and speed are inverse — so the time is divided by 1.5: 1 ÷ 1.5 = 2/3 of what it was."}, {"tag": "symmetric-percent", "label": "0.5 — 50% faster, 50% less", "wrong": "0.5", "message": "You treated 50% faster as 50% less time. Inverse means DIVIDE by the factor, not subtract the percent: 1 ÷ 1.5 = 2/3, so the time drops by a third, not a half."}, {"tag": "linear-not-inverse-square", "label": "0.44 — divided by 1.5²", "wrong": "0.444", "message": "You divided, which is the right direction, but by 1.5² = 2.25. Time and speed are plain inverse, no square: 1 ÷ 1.5 = 2/3."}]'::jsonb WHERE id = 'e06d3d07-ebae-4ff9-b5f5-0a2c4f2e2e8f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "Doubled y instead of quadrupling", "expr": "a*2", "message": "You made y bigger when x halved — right direction for an inverse relationship. But this is inverse SQUARE, so halving x multiplies y by 2² = 4, not 2. Try {a} × 4."}, {"tag": "multiplied-not-divided", "label": "Divided by 4 instead of multiplying", "expr": "a/4", "message": "You squared the factor — 2² = 4 — which is the key step. But x is on the bottom of y = k/x², so a smaller x makes y BIGGER. Multiply: {a} × 4."}, {"tag": "linear-not-inverse", "label": "Halved y with x", "expr": "a/2", "message": "You halved y along with x, as a direct relationship would. Here x is on the bottom and squared, so halving x MULTIPLIES y by 2² = 4. Try {a} × 4."}]'::jsonb WHERE id = 'a4efeaab-9323-42af-9909-4b6ca438ff80';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "1.4 — scaled by diameter, not diameter²", "wrong": "1.4", "message": "14 ÷ 10 = 1.4 is the right ratio of diameters. But the amount of pizza is AREA, which scales with diameter squared: 1.4² ≈ 1.96 — roughly double."}, {"tag": "doubled-not-squared", "label": "2.8 — doubled 1.4 instead of squaring", "wrong": "2.8", "message": "You have the ratio 1.4 and you knew area grows faster than the diameter — but 1.4 × 2 = 2.8 is doubling. Squaring is 1.4 × 1.4 ≈ 1.96, so roughly twice the pizza."}, {"tag": "percent-as-whole", "label": "96 — percent given, not factor", "wrong": "96", "message": "96% more is the right amount — 1.4² = 1.96. The checker wants the factor, so write it as 1.96 (about 2). Percent more and times-as-much are two ways of saying the same thing."}, {"tag": "inverted-ratio", "label": "0.51 — squared 10/14", "wrong": "0.51", "message": "You squared the ratio, which is the right idea for area, but the ratio was upside down: (10/14)² ≈ 0.51 says the pizza shrank. It grew, so use (14/10)² ≈ 1.96."}]'::jsonb WHERE id = 'af88083d-5bfe-46c6-aa18-cd97f0e22ecd';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "linear-not-inverse-square", "label": "4 — used the distance factor unsquared", "wrong": "4", "message": "Distance fell to 1/4 (8 m → 2 m), and you scaled quality up by 4 — right factor, right direction. But q = k/x² is inverse SQUARE, so the factor gets squared: 4² = 16."}, {"tag": "multiplied-not-divided", "label": "1/16 — direction flipped", "wrong": "1/16", "message": "You squared the factor 4 to get 16 — the key step. But you moved CLOSER to the router, and q = k/x² grows as x shrinks. Quality goes up by 16, not down."}, {"tag": "doubled-not-squared", "label": "8 — doubled 4 instead of squaring", "wrong": "8", "message": "You knew the change is bigger than the distance factor of 4, but 4 × 2 = 8 is doubling. Squaring is 4 × 4 = 16, so quality rises by ×16."}]'::jsonb WHERE id = 'dc99669c-d1f5-41fe-b520-2e8224ca44aa';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponent-sign", "label": "Positive exponent on the small number", "wrong": "6.7 x 10^4; 3.1 x 10^3", "message": "67,000 is right — 6.7 × 10⁴. For 0.0031 you moved the point three places, which is correct, but you moved it to the right to get from 0.0031 to 3.1. A number smaller than 1 needs a negative exponent: 3.1 × 10⁻³."}, {"tag": "place-value-off", "label": "Counted digits instead of moves", "wrong": "6.7 x 10^5; 3.1 x 10^-4", "message": "Both coefficients are right and both exponents are one too big. 67,000 has five digits but the point only moves four places to reach 6.7; 0.0031 has four decimals but the point moves three to reach 3.1. Count the moves, not the digits."}, {"tag": "decimal-shift", "label": "Point moved one place too few", "wrong": "6.7 x 10^3; 3.1 x 10^-2", "message": "The coefficients 6.7 and 3.1 are right. Each exponent is one short: 6.7 × 10³ is only 6,700 and 3.1 × 10⁻² is 0.031. Write the number out and count every place the point crosses — four for 67,000, three for 0.0031."}]'::jsonb WHERE id = 'ea28031f-5f76-4b0b-8a53-ccf8be644d99';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponents-added", "label": "Added exponents while dividing", "wrong": "4 x 10^8", "message": "8 ÷ 2 = 4 is right. The exponents were added, but this is a division, so they subtract: 6 − 2 = 4. Check the size: 8,000,000 ÷ 200 should be smaller than 8,000,000, and 4 × 10⁸ is bigger."}, {"tag": "subtraction-reversed", "label": "Subtracted exponents the wrong way", "wrong": "4 x 10^-4", "message": "8 ÷ 2 = 4 is right and you knew to subtract the exponents. The order got flipped: it is top minus bottom, 6 − 2 = 4, not 2 − 6. A big number divided by a small one stays big, so the exponent stays positive."}, {"tag": "exponents-divided", "label": "Divided the exponents", "wrong": "4 x 10^3", "message": "8 ÷ 2 = 4 is right. The exponents were divided too (6 ÷ 2), but powers of ten divide by subtracting the exponents: 6 − 2 = 4. Check with the long form: 8,000,000 ÷ 200 = 40,000, which is 4 × 10⁴."}, {"tag": "subtracted-not-divided", "label": "Subtracted the fronts", "wrong": "6 x 10^4", "message": "The exponent is right — 6 − 2 = 4. The fronts were subtracted (8 − 2) instead of divided. Only the exponents subtract; the coefficients divide like ordinary numbers: 8 ÷ 2 = 4."}]'::jsonb WHERE id = 'a5fe1989-ba56-4cb1-bcce-2d8384e3fcbb';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "place-value-off", "label": "Point moved one place too few", "wrong": "4.2 x 10^4", "message": "You moved the point the right direction but stopped one place early — 42,000 is 4.2 × 10⁴. The exponent 5 means the point moves five places to the right: 4.2 → 42 → 420 → 4,200 → 42,000 → 420,000."}, {"tag": "digit-not-value", "label": "Added five zeros after 42", "wrong": "4.2 x 10^6", "message": "You wrote five zeros after the digits 42, but the first move only takes the point past the 2 — that move doesn''t add a zero. Five moves from 4.2 gives 420,000, which has four zeros, not five."}, {"tag": "exponent-sign", "label": "Moved the point left", "wrong": "4.2 x 10^-5", "message": "You moved the point five places, which is right, but to the left. A positive exponent means the number is bigger than 4.2, so the point moves right: 420,000. Moving left would need 10⁻⁵."}]'::jsonb WHERE id = '3d6b29d4-f40b-4ac0-a44c-66cf7514b7f2';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponents-multiplied", "label": "Multiplied the exponents", "wrong": "6 x 10^12", "message": "3 × 2 = 6 is right. The exponents were multiplied (4 × 3), but multiplying powers of ten adds the exponents: 4 + 3 = 7. Check with the long form: 30,000 × 2,000 = 60,000,000, which is 6 × 10⁷."}, {"tag": "added-not-multiplied", "label": "Added the fronts", "wrong": "5 x 10^7", "message": "The exponent is right — 4 + 3 = 7. The fronts were added (3 + 2) instead of multiplied. Only the exponents add; the coefficients multiply like ordinary numbers: 3 × 2 = 6."}, {"tag": "exponent-unchanged", "label": "Kept the first exponent", "wrong": "6 x 10^4", "message": "3 × 2 = 6 is right, but the 10³ from the second number went missing. When you multiply, both powers of ten count: 10⁴ × 10³ = 10⁷. The answer should be much bigger than 30,000, not the same size."}, {"tag": "subtraction-reversed", "label": "Subtracted the exponents", "wrong": "6 x 10^1", "message": "3 × 2 = 6 is right. The exponents were subtracted, which is the rule for dividing. This is a multiplication, so they add: 4 + 3 = 7. A quick size check: 30,000 × 2,000 is far bigger than 60."}]'::jsonb WHERE id = '541d16d8-eb96-4ea0-8a98-c4a3dc80e98e';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponent-sign", "label": "Positive exponent on a small number", "wrong": "5.6 x 10^4", "message": "Four moves is right and 5.6 is the right coefficient. But 0.00056 is less than 1, so the exponent must be negative: 5.6 × 10⁻⁴. A positive 4 would mean 56,000."}, {"tag": "place-value-off", "label": "Counted decimal places, not moves", "wrong": "5.6 x 10^-5", "message": "Coefficient and sign are right. 0.00056 has five decimal places, but the point only moves four to land after the 5: 0.00056 → 0.0056 → 0.056 → 0.56 → 5.6. Count the moves, not the digits."}, {"tag": "decimal-shift", "label": "Counted only the zeros", "wrong": "5.6 x 10^-3", "message": "Coefficient and sign are right. You counted the three zeros after the point, but the point also has to move past the position where the 5 sits — four moves in total: 5.6 × 10⁻⁴. Check: 5.6 × 10⁻³ is 0.0056, ten times too big."}]'::jsonb WHERE id = '6ee1d079-6bfe-467f-b8d4-1246a9333eb5';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponent-sign", "label": "Positive exponent on a small number", "wrong": "8.1 x 10^4", "message": "Four moves is right and 8.1 is the right coefficient. But 0.00081 is less than 1, so the exponent must be negative: 8.1 × 10⁻⁴. A positive 4 would mean 81,000."}, {"tag": "place-value-off", "label": "Counted decimal places, not moves", "wrong": "8.1 x 10^-5", "message": "Coefficient and sign are right. 0.00081 has five decimal places, but the point moves four to land after the 8: 0.00081 → 0.0081 → 0.081 → 0.81 → 8.1. Count the moves, not the digits."}, {"tag": "decimal-shift", "label": "Counted only the zeros", "wrong": "8.1 x 10^-3", "message": "Coefficient and sign are right. You counted the three zeros after the point, but the point also moves past the position where the 8 sits — four moves in total: 8.1 × 10⁻⁴. Check: 8.1 × 10⁻³ is 0.0081, ten times too big."}]'::jsonb WHERE id = 'ea0a9d68-bb4d-4aac-a0a2-6850df53ad46';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "Stopped after the powers of ten", "wrong": "1 x 10^2 years", "message": "10⁹ ÷ 10⁷ = 10² is the right first step. But a year is about 3.15 × 10⁷ seconds, not 10⁷, so the 100 still has to be divided by 3.15: roughly 32 years."}, {"tag": "inverted-ratio", "label": "Divided seconds-per-year by seconds", "wrong": "3.2 x 10^-2 years", "message": "You used the right two numbers, but divided them the other way round. Years = total seconds ÷ seconds per year, so 10⁹ goes on top: 10⁹ ÷ (3.15 × 10⁷). A billion seconds is a lot longer than a year, so the answer must be bigger than 1."}, {"tag": "place-value-off", "label": "Seconds per year off by ten", "wrong": "3.2 x 10^2 years", "message": "Your division is set up the right way. The seconds-per-year figure is ten times too small: 60 × 60 × 24 × 365 ≈ 3.15 × 10⁷, not 10⁶. With 10⁹ ÷ (3.15 × 10⁷) you get 10² ÷ 3.15 ≈ 32 years."}, {"tag": "decimal-shift", "label": "Result off by a power of ten", "wrong": "3.2 years", "message": "The 3.2 shows the division of the fronts went well. The powers of ten came out one short: 10⁹ ÷ 10⁷ = 10², so 1 ÷ 3.15 × 10² ≈ 32, not 3.2. Sanity check: even a billion seconds at 3.15 × 10⁷ per year is a few decades."}]'::jsonb WHERE id = '6f05e68f-3d59-4b21-be87-679e5957891a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponent-sign", "label": "Product exponent came out positive", "wrong": "8 x 10^7", "message": "4 × 2 = 8 is right and 7 is the right count. Adding two negative exponents keeps the sign negative: (−4) + (−3) = −7. Two numbers smaller than 1 multiply to something even smaller, so 8 × 10⁻⁷."}, {"tag": "exponents-multiplied", "label": "Multiplied the exponents", "wrong": "8 x 10^12", "message": "4 × 2 = 8 is right. The exponents were multiplied ((−4)(−3) = 12), but multiplying powers of ten adds the exponents: (−4) + (−3) = −7. Size check: 0.0004 × 0.002 must be tiny, not a trillion."}, {"tag": "place-value-off", "label": "One exponent off by one", "wrong": "8 x 10^-6", "message": "4 × 2 = 8 is right and you added the exponents. One of the starting exponents is off by one: 0.0004 is 4 × 10⁻⁴ (four moves) and 0.002 is 2 × 10⁻³ (three moves). Recount the moves, then add: −4 + −3 = −7."}, {"tag": "subtraction-reversed", "label": "Subtracted the exponents", "wrong": "8 x 10^-1", "message": "4 × 2 = 8 is right. The exponents were subtracted, which is the rule for dividing. Multiplying adds them: (−4) + (−3) = −7. Check: 0.0004 × 0.002 is far smaller than 0.8."}]'::jsonb WHERE id = '3f3b1a0d-5adc-48e3-aa9b-5ff4de3e38f9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "Reported 100^10 rewritten as 10^20", "wrong": "10^20", "message": "Rewriting 100¹⁰ as (10²)¹⁰ = 10²⁰ is exactly the right move. That is the size of the smaller number, though. The question asks which is bigger — 10¹⁰⁰ — and by how much: 10¹⁰⁰ ÷ 10²⁰ = 10⁸⁰."}, {"tag": "place-value-off", "label": "Treated 100 as one power of ten", "wrong": "10^90", "message": "You compared exponents, which is the right idea, and 10¹⁰⁰ is indeed the bigger one. But 100 is 10², not 10¹, so 100¹⁰ = 10²⁰, not 10¹⁰. The gap is 100 − 20 = 80 powers of ten."}, {"tag": "exponents-divided", "label": "Divided exponents to compare", "wrong": "10^5", "message": "Getting 100¹⁰ = 10²⁰ is right, and 10¹⁰⁰ is the bigger one. To find how many times bigger, divide the numbers — which means subtracting the exponents, 100 − 20 = 80 — not dividing the exponents 100 ÷ 20."}]'::jsonb WHERE id = '064db8b3-c90a-4b2b-9c0a-a40136ef751f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponent-unchanged", "label": "Kept 10^3 after multiplying", "expr": "a*b*10^3", "message": "{a} × {b} is the right front. But each thousand carries a 10³, and both of them count: 10³ × 10³ = 10⁶. Your answer is only {a}{b} thousand, and {a},000 × {b},000 is much bigger than that."}, {"tag": "exponents-multiplied", "label": "Multiplied the exponents", "expr": "a*b*10^9", "message": "{a} × {b} is the right front. The exponents were multiplied (3 × 3 = 9), but multiplying powers of ten adds them: 3 + 3 = 6. Check the zeros: {a},000 × {b},000 has six zeros, not nine."}, {"tag": "place-value-off", "label": "Exponent off by one", "expr": "a*b*10^5", "message": "{a} × {b} is the right front and you added exponents. One of the starting powers is off: {a},000 is {a} × 10³ (three moves) and so is {b},000. Then 3 + 3 = 6, giving {a}·{b} × 10⁶."}]'::jsonb WHERE id = 'bc0903dd-dfec-453a-9bed-0499a0e8ed97';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponents-added", "label": "Added exponents while dividing", "wrong": "2 x 10^13", "message": "6 ÷ 3 = 2 is right. ''How many times larger'' is a division, so the exponents subtract: 8 − 5 = 3. Check the size: 6 × 10⁸ is not ten trillion times 3 × 10⁵; it is 2,000 times."}, {"tag": "subtraction-reversed", "label": "Subtracted exponents the wrong way", "wrong": "2 x 10^-3", "message": "6 ÷ 3 = 2 is right and you knew to subtract the exponents. The order got flipped: it is the bigger number''s exponent minus the smaller''s, 8 − 5 = 3. ''Times larger'' has to come out bigger than 1."}, {"tag": "subtracted-not-divided", "label": "Subtracted the fronts", "wrong": "3 x 10^3", "message": "The exponent is right — 8 − 5 = 3. The fronts were subtracted (6 − 3) instead of divided. Only the exponents subtract; the coefficients divide: 6 ÷ 3 = 2, so 2 × 10³ = 2,000 times."}, {"tag": "inverted-ratio", "label": "Divided the fronts upside down", "wrong": "5 x 10^2", "message": "The exponent came out right, 8 − 5 = 3, but the fronts were divided the other way (3 ÷ 6). ''How many times larger is 6 × 10⁸'' puts the 6 on top: 6 ÷ 3 = 2. Answer: 2 × 10³."}]'::jsonb WHERE id = '675c3ebf-f33f-4f88-9b37-0f5d492116b2';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "Divided song size by plan size", "expr": "a*10^6/(b*10^9)", "message": "You divided the two sizes, but the other way round. Streams = plan ÷ one stream, so the plan goes on top: {b} × 10⁹ ÷ ({a} × 10⁶). A plan with billions of bytes holds many streams, so the answer must be bigger than 1."}, {"tag": "subtraction-reversed", "label": "Subtracted exponents the wrong way", "expr": "b/a*10^-3", "message": "{b} ÷ {a} is the right front and you subtracted the exponents. The order is top minus bottom: 9 − 6 = 3, not 6 − 9. That gives {b}/{a} × 10³ streams — thousands, not thousandths."}, {"tag": "exponents-added", "label": "Added exponents while dividing", "expr": "b/a*10^15", "message": "{b} ÷ {a} is the right front. This is a division, so the exponents subtract: 9 − 6 = 3. A 10⁹-byte plan split into 10⁶-byte streams gives thousands of streams, not quadrillions."}, {"tag": "intermediate-answer", "label": "Divided the fronts only", "expr": "b/a", "message": "{b} ÷ {a} is the right first step, but the powers of ten still need handling: 10⁹ ÷ 10⁶ = 10³. Multiply your front by 1,000 to get the number of streams."}]'::jsonb WHERE id = 'e2cd119e-9940-4d7a-9e0c-8d2441351177';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "exponent-unchanged", "label": "Moved the point, kept the exponent", "wrong": "7.2 x 10^5", "message": "Sliding the point to make 7.2 is the right move. But 72 became 7.2 — ten times smaller — so the power of ten has to grow by one to compensate: 10⁵ becomes 10⁶. Check: 7.2 × 10⁵ is 720,000, while 72 × 10⁵ is 7,200,000."}, {"tag": "exponent-sign", "label": "Exponent moved the wrong way", "wrong": "7.2 x 10^4", "message": "7.2 is the right coefficient and you knew the exponent had to change. It went the wrong way: making the front smaller (72 → 7.2) means the power must get bigger, 5 → 6, so the number stays the same size."}, {"tag": "place-value-off", "label": "Exponent moved two places", "wrong": "7.2 x 10^7", "message": "7.2 is the right coefficient and the exponent went the right direction. It moved two places, but the point only moved one (72 → 7.2), so the exponent moves by one: 5 → 6. Check: 7.2 × 10⁶ = 7,200,000 = 72 × 10⁵."}]'::jsonb WHERE id = '049986ca-167c-40ae-80dd-d27a658c7a8a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "subtraction-reversed", "label": "Subtracted exponents the wrong way", "expr": "2*10^(b-a)", "message": "8 ÷ 4 = 2 is right and you knew to subtract the exponents. The order is top minus bottom: {a} − {b}, not {b} − {a}. A big number divided by a smaller one stays big, so the exponent stays positive."}, {"tag": "exponents-added", "label": "Added exponents while dividing", "expr": "2*10^(a+b)", "message": "8 ÷ 4 = 2 is right. Adding exponents is the rule for multiplying; dividing subtracts them: {a} − {b}. Size check: dividing should make 8 × 10^{a} smaller, and 2 × 10^({a}+{b}) is bigger."}, {"tag": "subtracted-not-divided", "label": "Subtracted the fronts", "expr": "4*10^(a-b)", "message": "The exponent is right — {a} − {b}. The fronts were subtracted (8 − 4) instead of divided. Only the exponents subtract; the coefficients divide like ordinary numbers: 8 ÷ 4 = 2."}, {"tag": "inverted-ratio", "label": "Divided the fronts upside down", "expr": "0.5*10^(a-b)", "message": "The exponent is right — {a} − {b} — but the fronts went in the wrong order (4 ÷ 8). The first number is on top, so 8 ÷ 4 = 2, giving 2 × 10^({a}−{b})."}]'::jsonb WHERE id = '94657673-d6ac-4a79-95c0-28ba4203e348';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-not-multiplied", "label": "Added the fronts", "expr": "5*10^(a+b)", "message": "The exponent is right — {a} + {b}. The fronts were added (2 + 3) instead of multiplied. Only the exponents add; the coefficients multiply like ordinary numbers: 2 × 3 = 6."}, {"tag": "exponent-unchanged", "label": "Kept the first exponent", "expr": "6*10^a", "message": "2 × 3 = 6 is right, but the 10^{b} from the second number went missing. Both powers of ten count when you multiply: 10^{a} × 10^{b} = 10^({a}+{b})."}, {"tag": "subtraction-reversed", "label": "Subtracted the exponents", "expr": "6*10^(a-b)", "message": "2 × 3 = 6 is right. The exponents were subtracted, which is the rule for dividing. This is a multiplication, so they add: {a} + {b}. Multiplying two big numbers should give something bigger, not smaller."}]'::jsonb WHERE id = '24b8d268-ac7e-4320-98ca-98fd1395bc01';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "place-value-off", "label": "Read 10^6 as ten million", "wrong": "3 x 10^1", "message": "You have the right idea that 10⁶ is a big round number. A million is 1,000,000 — six zeros — so 10⁶ is exactly one million and 3 × 10⁶ is 3 million. Ten million would be 10⁷."}, {"tag": "decimal-shift", "label": "Read 10^6 as a hundred thousand", "wrong": "3 x 10^-1", "message": "Your answer says 3 × 10⁶ is less than a million. Count the zeros: a million is 1,000,000, which is 10⁶, so 3 × 10⁶ is 3 million exactly. A hundred thousand would be 10⁵."}, {"tag": "power-of-ten", "label": "Answered in thousands", "wrong": "3 x 10^3", "message": "3 × 10⁶ is 3,000 thousand, so that number is right in thousands. The question asks in millions, and a million is 10⁶, so 3 × 10⁶ is 3 million."}]'::jsonb WHERE id = 'de22e7ca-eba7-42c1-a0a7-b864c2c62e84';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "front-compared-first", "label": "Compared the fronts before the exponents", "wrong": "9 x 10^7", "message": "9 is bigger than 2, and if the powers matched that would settle it. But the exponents differ, and the exponent wins: 10⁸ is ten times 10⁷. Written out, 90,000,000 is less than 200,000,000."}, {"tag": "added-not-compared", "label": "Added the two numbers", "wrong": "2.9 x 10^8", "message": "You combined the two numbers, and 90,000,000 + 200,000,000 = 290,000,000 is right for a sum. The question asks which one is larger, though — compare the exponents first: 10⁸ beats 10⁷, so 2 × 10⁸."}]'::jsonb WHERE id = '83f0cf0c-529f-43f9-986b-63a3847c3562';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "Added four zeros after 32", "wrong": "3.2 x 10^5", "message": "You wrote four zeros after the digits 32, but the first move only takes the point past the 2 — that move doesn''t add a zero. Four moves from 3.2 gives 32,000, which has three zeros."}, {"tag": "place-value-off", "label": "Point moved one place too few", "wrong": "3.2 x 10^3", "message": "You moved the point the right direction but stopped one place early — 3,200 is 3.2 × 10³. The exponent 4 means four moves to the right: 3.2 → 32 → 320 → 3,200 → 32,000."}, {"tag": "exponent-sign", "label": "Moved the point left", "wrong": "3.2 x 10^-4", "message": "Four moves is right, but they went to the left. A positive exponent means the number is bigger than 3.2, so the point moves right: 32,000. Moving left would need 10⁻⁴."}]'::jsonb WHERE id = '5fbe4fed-7b01-438c-97f1-1754626f6225';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "place-value-off", "label": "Point moved one place too few", "wrong": "4.5 x 10^5", "message": "4.5 is the right coefficient. The exponent is one short: 4.5 × 10⁵ is only 450,000. Count each place the point crosses from 4,500,000. back to 4.5 — six moves, so 10⁶."}, {"tag": "digit-not-value", "label": "Counted digits instead of moves", "wrong": "4.5 x 10^7", "message": "4.5 is the right coefficient. 4,500,000 has seven digits, but the point only moves six places to sit after the 4. Count the moves, not the digits: 4.5 × 10⁶."}, {"tag": "exponent-sign", "label": "Negative exponent on a big number", "wrong": "4.5 x 10^-6", "message": "4.5 is right and six moves is right. But 4,500,000 is bigger than 1, so the exponent is positive: 4.5 × 10⁶. A negative exponent would make it a tiny fraction, 0.0000045."}]'::jsonb WHERE id = 'af4979c4-b87a-4bc2-ad3f-d81d87dc7755';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "substituted-wrong-variable", "label": "plugged in g to fix the unit", "wrong": "9.8", "message": "You reached for 9.8 to force the unit into newtons. The number isn''t the issue — the unit kg·m/s is missing one per-second, which means a velocity was used where an acceleration belongs. Rewrite F = m·a with a in m/s² and the units come out as kg·m/s² on their own."}, {"tag": "exponent-sign", "label": "aimed for s to the minus one", "wrong": "-1", "message": "You identified that the seconds are the problem, which is the right place to look. A newton is kg·m/s², so the seconds need to be squared in the denominator, not left at the first power. Acceleration carries m/s²; check whether you multiplied mass by a velocity instead."}]'::jsonb WHERE id = '4cfdfdb4-1277-4e37-89b3-367c7680f84b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "divided by 1000 instead of multiplying", "wrong": "0.005 m", "message": "You used the right factor, 1000, but went the other way. A metre is smaller than a kilometre, so the same distance takes more metres: 5 × 1000. A number that gets smaller when you move to a smaller unit is the signal to flip."}, {"tag": "power-of-ten", "label": "used 100 as the factor", "wrong": "500 m", "message": "You multiplied, which is the right direction, but by 100. That is the centi- factor; kilo- means 1000. 5 km × 1000 m/km — the km cancel and the metres stay."}, {"tag": "decimal-shift", "label": "moved the point one place short", "wrong": "50 m", "message": "Direction and factor are both right — kilo- means ×1000 — but the decimal point moved one place instead of three. 5 × 1000 needs three zeros."}]'::jsonb WHERE id = '7653b397-7fe6-4133-bc7f-e9ad32b83993';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sixty-vs-3600", "label": "used 60 instead of 3600", "wrong": "150 s", "message": "You multiplied 2.5 by 60 — that gives 150 minutes, which is correct as far as it goes. Seconds need one more step: another ×60. An hour is 60 × 60 = 3600 s, so 2.5 × 3600."}, {"tag": "conversion-direction", "label": "divided by 3600 instead of multiplying", "wrong": "0.000694 s", "message": "You used the right factor, 3600, but divided. A second is a much smaller unit than an hour, so the count must grow: 2.5 × 3600. Two and a half hours is far more than a fraction of a second."}, {"tag": "decimal-shift", "label": "answer ten times too large", "wrong": "90000 s", "message": "The setup is right — 2.5 × 3600 — but the decimal point ended up one place over. 2 × 3600 is 7200 and half of 3600 is 1800; add them and check your zeros."}]'::jsonb WHERE id = '2bca1275-feed-4e8f-b851-f08003eef438';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "multiplied by 3.6 instead of dividing", "wrong": "324 m/s", "message": "You used 3.6, which is the right shortcut, but multiplied. km/h → m/s is ×1000 then ÷3600, and 1000/3600 = 1/3.6, so you divide. Sanity check: 90 km/h is highway speed, roughly 25 m each second, not 324."}, {"tag": "unit-not-converted", "label": "converted hours but left km", "wrong": "0.025 m/s", "message": "You divided by 3600 to move from per-hour to per-second — that part is right. The distance is still in kilometres, so your answer is 0.025 km/s. Multiply by 1000 to finish in m/s."}, {"tag": "factor-skipped", "label": "converted km but left hours", "wrong": "90000 m/s", "message": "You multiplied by 1000 to turn km into m — that part is right, and 90,000 m/h is a true statement. The time unit hasn''t changed yet. Divide by 3600 to get per second."}, {"tag": "sixty-vs-3600", "label": "divided by 60 not 3600", "wrong": "1.5 m/s", "message": "You divided by 60, which takes you from per-hour to per-minute, not per-second. An hour is 3600 s. Try 90 × 1000 ÷ 3600, or just 90 ÷ 3.6."}]'::jsonb WHERE id = '9df491d8-4ab8-4cce-87a9-442b5d1d8bb6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "left the volume in mL", "wrong": "4320 mL", "message": "Your time scaling is right: 3 × 60 × 24 = 4,320 mL per day. The question asks for litres, so one more step — 4,320 ÷ 1000."}, {"tag": "intermediate-answer", "label": "answered per hour, not per day", "wrong": "0.18 L", "message": "You scaled minutes up to an hour (3 × 60 = 180 mL) and converted to litres — both correct. That is the hourly amount. A day has 24 of those hours, so multiply by 24."}, {"tag": "factor-skipped", "label": "skipped the minutes-to-hours step", "wrong": "0.072 L", "message": "You multiplied by 24 for the hours in a day and divided by 1000 for litres — both right. But the rate is per minute, and there are 60 minutes in each of those hours. Put the ×60 back in."}]'::jsonb WHERE id = '8c68d9b9-a326-4f88-ae8d-a3ea9ca051ec';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "answered km per minute", "expr": "a/b", "unit": "km/min", "message": "{a} ÷ {b} is a real speed — it''s km per minute. The question asks for km per hour, and an hour holds 60 of those minutes, so multiply by 60."}, {"tag": "multiplied-not-divided", "label": "multiplied by the minutes", "expr": "a*b/60", "message": "You brought in the 60 and the {b} minutes — the right pieces. But speed is distance divided by time, so the {b} goes underneath: {a} ÷ {b} gives km per minute, then × 60 for km per hour."}, {"tag": "sixty-vs-3600", "label": "used 3600 instead of 60", "expr": "a*3600/b", "message": "You scaled the time up, which is the right idea, but by 3600. That''s seconds in an hour; your time is in minutes, and an hour is 60 minutes. {a} ÷ {b} × 60."}]'::jsonb WHERE id = '23f45039-3c9d-4132-934c-0e2b0e546860';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "multiplied by 3.6 instead of dividing", "expr": "a*3.6", "message": "You used 3.6, which is the right shortcut, but multiplied. It comes from ×1000 ÷3600 = ÷3.6. Check: m/s numbers are always smaller than the km/h number for the same speed, since a second is so short."}, {"tag": "sixty-vs-3600", "label": "divided by 60 not 3600", "expr": "a*1000/60", "message": "The ×1000 for metres is right. Then you divided by 60, which gives metres per minute. An hour is 3600 seconds, so divide by 3600 — or simply {a} ÷ 3.6."}, {"tag": "unit-not-converted", "label": "converted hours but left km", "expr": "a/3600", "message": "You divided by 3600 to reach per-second — correct. The distance is still kilometres, so this is km/s. Multiply by 1000 to get m/s."}, {"tag": "factor-skipped", "label": "converted km but left hours", "expr": "a*1000", "message": "You multiplied by 1000 for metres — correct, and {a}000 m/h is true. The time is still per hour; divide by 3600 to get per second."}]'::jsonb WHERE id = '1e65757c-4c31-4601-aa68-72dd19e9ccc0';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intercept-ignored", "label": "skipped the minus 32", "wrong": "194 C", "message": "You scaled by 5/9, which is the right factor, but on 350 directly. The two scales don''t start at the same place — 0 °C is 32 °F — so subtract 32 first, then multiply by 5/9."}, {"tag": "inverted-ratio", "label": "used 9/5 instead of 5/9", "wrong": "572 C", "message": "You subtracted 32 first — good. Then you multiplied by 9/5, which is the °C → °F factor. Going from °F to °C the fraction is 5/9. Check: a Celsius reading is always a smaller number than the same temperature in Fahrenheit above freezing."}, {"tag": "order-of-operations", "label": "multiplied before subtracting", "wrong": "162 C", "message": "You did the 5/9 first and subtracted 32 after. The formula has the parentheses around (°F − 32) for a reason: the offset comes off before the scaling. 350 − 32 = 318, then × 5/9."}, {"tag": "conversion-direction", "label": "converted Celsius to Fahrenheit", "wrong": "662 C", "message": "You ran the conversion the other way — ×9/5 then +32 turns °C into °F. The oven needs °F → °C: subtract 32, then multiply by 5/9. Ovens don''t go to 662 °C."}]'::jsonb WHERE id = '0531332f-78f6-4818-a664-7285bc67778e';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "half-forgotten", "label": "answered the whole day, not one dose", "wrong": "120 mg", "message": "5 mg/kg × 24 kg = 120 mg — the kg cancel and that''s the correct daily total. The question asks for one of the two doses it''s split into: 120 ÷ 2."}, {"tag": "multiplied-not-divided", "label": "multiplied by 2 instead of dividing", "wrong": "240 mg", "message": "The daily total, 120 mg, is right. ''Split in 2 doses'' means each dose is a share of the total, so divide by 2 rather than multiply."}, {"tag": "unit-not-converted", "label": "never multiplied by the child''s mass", "wrong": "2.5 mg", "message": "You split 5 in half — but 5 is mg per kilogram, a rate, not an amount. It has to be multiplied by the child''s 24 kg first so the kg cancel and you''re left with mg. Then halve it."}]'::jsonb WHERE id = 'eec1afeb-4b2f-4d36-bc2b-9519194c5173';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "multiplied by 100 instead of dividing", "expr": "a*100", "message": "You used 100, which is the right factor, but multiplied. A metre is bigger than a centimetre, so the same length is fewer metres: {a} ÷ 100."}, {"tag": "decimal-shift", "label": "divided by 10 not 100", "expr": "a/10", "message": "You divided, which is the right direction, but the point moved one place instead of two. There are 100 cm in a metre — {a} ÷ 100."}, {"tag": "power-of-ten", "label": "used 1000 as the factor", "expr": "a/1000", "message": "Direction is right, but 1000 is the kilo/milli factor. Centi- means one hundredth, so {a} ÷ 100."}]'::jsonb WHERE id = 'dc9e6e0e-1e7e-4f3b-99e6-801468a127e3';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "multiplied by 60 instead of dividing", "expr": "a*60", "message": "You used 60, which is right, but multiplied. An hour is the bigger unit, so {a} minutes is fewer hours: {a} ÷ 60."}, {"tag": "sixty-vs-3600", "label": "divided by 3600", "expr": "a/3600", "message": "You divided, which is right, but by 3600 — that''s seconds per hour. Your number is in minutes, and there are 60 of those in an hour: {a} ÷ 60."}, {"tag": "decimal-shift", "label": "treated 100 minutes as an hour", "expr": "a/100", "message": "You divided by 100. Minutes don''t go in hundreds — an hour is 60 minutes, so {a} ÷ 60. Check: 90 minutes is an hour and a half, 1.5 h."}]'::jsonb WHERE id = 'd8284f1a-f363-40d8-a2f3-edfba6fd8b3c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "multiplied by 1000 instead of dividing", "expr": "a*1000", "message": "You used 1000, which is right, but multiplied. A litre is the bigger unit, so {a} mL is fewer litres: {a} ÷ 1000."}, {"tag": "power-of-ten", "label": "divided by 100 not 1000", "expr": "a/100", "message": "Direction is right. But milli- means one thousandth, not one hundredth: {a} ÷ 1000."}, {"tag": "decimal-shift", "label": "moved the point one place", "expr": "a/10", "message": "You divided, but the point moved only one place. Milli- is three places — {a} ÷ 1000. Check: a 2-litre bottle is 2000 mL."}]'::jsonb WHERE id = 'ca5b8849-c494-4e80-9509-8e5a7111ee56';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "divided by 1000 instead of multiplying", "expr": "a/1000", "message": "You used 1000, which is right, but divided. A gram is smaller than a kilogram, so the same mass is more grams: {a} × 1000."}, {"tag": "power-of-ten", "label": "used 100 as the factor", "expr": "a*100", "message": "Direction is right, but 100 is the centi- factor. Kilo- means 1000: {a} × 1000."}, {"tag": "decimal-shift", "label": "moved the point one place", "expr": "a*10", "message": "You multiplied, but by 10. Kilo- means a thousand — three zeros: {a} × 1000."}]'::jsonb WHERE id = 'e68b085a-db1a-4efd-9775-3b708360f92d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "multiplied by 60 instead of dividing", "expr": "a*60", "message": "You used 60, which is right, but multiplied. Hours are the bigger unit, so {a} minutes is fewer hours: {a} ÷ 60, and the remainder is the leftover minutes."}, {"tag": "decimal-shift", "label": "treated 100 minutes as an hour", "expr": "a/100", "message": "You divided by 100. An hour is 60 minutes, not 100, so {a} ÷ 60 for the whole hours and whatever is left over is the minutes."}, {"tag": "intermediate-answer", "label": "gave only the leftover minutes", "expr": "a-60", "unit": "min", "message": "You took off an hour and reported what was left. That remainder is the minutes part — now attach the hours in front of it (and check whether a second whole hour also comes out of {a})."}]'::jsonb WHERE id = '8379b0e0-60cd-499e-9d2a-030e30f464d5';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "picked km because km are bigger", "wrong": "2.4 km", "message": "You went with the kilometre value because a km is the larger unit. But the numbers have to be compared in the same unit: 2.4 km × 1000 = 2400 m, which is less than 2500 m."}, {"tag": "intermediate-answer", "label": "answered the difference, not the choice", "wrong": "100 m", "message": "You converted and subtracted — 2500 − 2400 = 100 m is a correct difference. The question asks which one is longer, so name that distance: 2,500 m."}, {"tag": "power-of-ten", "label": "converted 2.4 km to 24,000 m", "wrong": "24000 m", "message": "You converted the km to m to compare — the right move — but with a factor of 10,000. Kilo- is 1000, so 2.4 km = 2400 m, which is shorter than 2500 m."}]'::jsonb WHERE id = 'a7047b81-a258-4a97-80a0-a67c9f74abff';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "used {b} instead of 0.{b} kg", "expr": "a*b", "message": "You multiplied price by mass — right setup. But {b}00 g is {b}00 ÷ 1000 = 0.{b} kg, not {b} kg. So ${a} × 0.{b}."}, {"tag": "unit-not-converted", "label": "treated the grams as kilograms", "expr": "a*b*100", "message": "You multiplied ${a} per kg by {b}00 as if it were kilograms. The price is per kg and the mass is in grams, so convert first: {b}00 g ÷ 1000 = 0.{b} kg, then × ${a}."}, {"tag": "inverted-ratio", "label": "divided price by mass", "expr": "10*a/b", "message": "You divided instead of multiplying. Cost is price-per-kg × kg — the kg cancel and dollars remain. ${a}/kg × 0.{b} kg."}]'::jsonb WHERE id = '5581c6de-5241-453d-9409-da0f3e85593c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "conversion-direction", "label": "divided by 60 instead of multiplying", "expr": "a/60", "message": "You used 60, the right factor, but divided. An hour holds 60 minutes, so the printer gets 60 rounds of {a} pages: {a} × 60."}, {"tag": "sixty-vs-3600", "label": "used 3600 instead of 60", "expr": "a*3600", "message": "You scaled up, which is right, but by 3600 — that''s seconds in an hour. The rate is per minute, and an hour is 60 minutes: {a} × 60."}, {"tag": "decimal-shift", "label": "treated 100 minutes as an hour", "expr": "a*100", "message": "You multiplied by 100. An hour is 60 minutes, not 100: {a} × 60."}]'::jsonb WHERE id = '9ebb64af-319b-4e5c-9ed2-b345f78914fd';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "converted metres but left minutes", "expr": "a*100", "unit": "cm/min", "message": "The ×100 for centimetres is right — {a}00 cm/min is true. The time is still per minute, though. A minute is 60 s, so divide by 60 to get cm/s."}, {"tag": "factor-skipped", "label": "converted minutes but left metres", "expr": "a/60", "unit": "m/s", "message": "The ÷60 to reach per-second is right. The distance is still in metres, so this is m/s. Multiply by 100 to get cm."}, {"tag": "conversion-direction", "label": "multiplied by 60 instead of dividing", "expr": "a*100*60", "message": "The ×100 for centimetres is right. Then you multiplied by 60 — but a second is a shorter stretch than a minute, so fewer cm go by each second: divide by 60."}, {"tag": "sixty-vs-3600", "label": "divided by 3600 not 60", "expr": "a*100/3600", "message": "The ×100 is right. Then you divided by 3600, which is seconds per hour. Your rate is per minute, and a minute is 60 s, so ÷ 60."}]'::jsonb WHERE id = '1c237701-99de-47fb-9b43-a07de9265799';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "used v instead of v squared", "wrong": "4 x 10^14", "message": "Your mass and your speed conversion are right — 12 km/s is 1.2 × 10⁴ m/s. But KE is ½mv², so the speed gets squared: (1.2 × 10⁴)² ≈ 1.4 × 10⁸. Multiply that by ½ × 7 × 10¹⁰ and the exponent lands near 18."}, {"tag": "unit-not-converted", "label": "kept speed in km/s", "wrong": "5 x 10^12", "message": "The ½mv² setup is right, but the 12 was still in km/s. Joules need m/s, so 12 km/s becomes 1.2 × 10⁴ m/s. Squaring that adds six more powers of ten than 12² does — that is the whole gap between 10¹² and 10¹⁸."}, {"tag": "intermediate-answer", "label": "stopped at v squared", "wrong": "1.4 x 10^8", "message": "1.4 × 10⁸ is v² in m²/s² — a correct middle step. The question asks for the energy, so it still needs ½ × 7 × 10¹⁰ × 1.4 × 10⁸. Carry the exponents: 10 + 8 gives 10¹⁸."}, {"tag": "power-of-ten", "label": "exponent slipped when squaring", "wrong": "5 x 10^17", "message": "Your chain is the right shape and the 5 in front is right. Check the squaring: (1.2 × 10⁴)² doubles the exponent to 10⁸, not 10⁷. Then 10¹⁰ × 10⁸ = 10¹⁸ before the ½ and the 1.44 trim it to 5 × 10¹⁸."}]'::jsonb WHERE id = '6ba377f0-d35c-4f63-9d95-e1dc6b484fe9';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "power-of-ten", "label": "dropped a zero", "wrong": "800", "message": "Rounding to 400 × 20 is the right move. Then 4 × 2 = 8, and the zeros come along: two from 400 and one from 20, so three zeros — 8,000. Count the zeros separately from the digits."}, {"tag": "decimal-shift", "label": "added an extra zero", "wrong": "80000", "message": "400 × 20 is the right rounding. There are three zeros to carry, not four: 400 brings two and 20 brings one. 4 × 2 = 8 followed by three zeros is 8,000."}, {"tag": "sig-figs-over", "label": "gave the exact product", "wrong": "7828", "message": "412 × 19 = 7,828 is the exact product. The question asks for one significant figure, so round it — the leading digit is 7, the next is 8, so it rounds up to 8,000. Rounding the factors first (400 × 20) gets there without the long multiplication."}, {"tag": "rounded-too-far", "label": "rounded 19 down to 10", "wrong": "4000", "message": "You rounded 412 to 400, which is good. But 19 is much closer to 20 than to 10 — rounding it to 10 halves the answer. 400 × 20 = 8,000."}]'::jsonb WHERE id = '5e813001-e139-4cde-90e9-6664e947276a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "decimal-shift", "label": "treated 0.49 as about 5", "wrong": "4000", "message": "You saw 0.49 as roughly a half — the right instinct — but the decimal point moved. 0.49 is about ½, not 5, so the answer should be about half of 802, which is around 400."}, {"tag": "power-of-ten", "label": "one power of ten too small", "wrong": "40", "message": "Half of 802 is the right idea. Half of 800 is 400, not 40 — sense-check it: 0.49 is nearly ½, so the result should be a little under half of 802."}, {"tag": "divided-not-multiplied", "label": "divided 802 by 0.49", "wrong": "1600", "message": "You divided 802 by 0.49 instead of multiplying. Multiplying by a number less than 1 makes things smaller, so the answer must be below 802. About half of 800 is 400."}, {"tag": "sig-figs-over", "label": "gave the exact product", "wrong": "393", "message": "0.49 × 802 = 392.98 is the exact product. The question asks ''about how much'', so round it to one figure — about 400. The quick route is ½ × 800."}]'::jsonb WHERE id = 'baa66153-a996-40eb-8a3d-b2b3cef24e62';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "digit-not-value", "label": "gave the exponent only", "wrong": "6", "message": "The 6 is the right exponent — 3,150,000 is 3.15 × 10⁶. The order of magnitude is the power of ten itself, so write 10⁶, not just the 6."}, {"tag": "power-of-ten", "label": "rounded up to 10^7", "wrong": "10^7", "message": "You counted six zeros and then rounded up. In scientific notation the number is 3.15 × 10⁶, and 3.15 is closer to 1 than to 10 on a log scale (the crossover is about 3.16), so the order of magnitude stays at 10⁶."}, {"tag": "coefficient-kept", "label": "gave scientific notation, not power", "wrong": "3 x 10^6", "message": "3 × 10⁶ is the number in rounded scientific notation, and the exponent is right. The order of magnitude is just the power of ten, so drop the 3 and write 10⁶."}, {"tag": "place-value-off", "label": "miscounted the zeros", "wrong": "10^5", "message": "Your method is right; the count is one short. 3,150,000 has the 3 in the millions place — six digits follow it — so it is 3.15 × 10⁶. Group the digits in threes: 3 | 150 | 000 gives six places past the 3."}]'::jsonb WHERE id = '40d57b0c-a287-4090-a663-47f75016bc95';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "power-of-ten", "label": "one power of ten too small", "wrong": "50", "message": "Rounding to 10,000 ÷ 20 is a good move. Then 10,000 ÷ 20 = 500, not 50: 20 × 50 is only 1,000. Check by multiplying back — 20 × 500 = 10,000."}, {"tag": "decimal-shift", "label": "one power of ten too large", "wrong": "5000", "message": "10,000 ÷ 20 is the right rounding. 20 × 5,000 would be 100,000 — ten times too big. Multiplying back gives 20 × 500 = 10,000, so the answer is about 500."}, {"tag": "sig-figs-over", "label": "gave the exact quotient", "wrong": "467", "message": "9,800 ÷ 21 = 466.7 is the exact quotient. The question says ''roughly'', so round to one figure — about 500. The quick route is 10,000 ÷ 20."}, {"tag": "multiplied-not-divided", "label": "multiplied instead of dividing", "wrong": "200000", "message": "You multiplied 9,800 by 21. Dividing by 21 asks how many 21s fit into 9,800 — that has to be much smaller than 9,800. 10,000 ÷ 20 ≈ 500."}]'::jsonb WHERE id = '1a3f5daa-dc69-4ee7-88a2-e374f7bdd0b6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "gave the per-day count", "wrong": "50", "message": "About 50 a day is a sensible first link. The question asks for a year, so the chain has one more step: 50 per day × 365 days ≈ 18,000, about 2 × 10⁴."}, {"tag": "power-of-ten", "label": "one power of ten low", "wrong": "2 x 10^3", "message": "50 per day × 365 is the right chain. Check the zeros: 50 × 365 is a bit under 50 × 400 = 20,000, so about 2 × 10⁴, not 2 × 10³."}, {"tag": "wrong-time-span", "label": "multiplied by a week", "wrong": "350", "message": "50 a day × 7 gives a week, about 350. The question asks for a year, so multiply by 365 days instead: 50 × 365 ≈ 2 × 10⁴."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "2 x 10^5", "message": "The chain 50 × 365 is right. 50 × 365 is a bit under 50 × 400 = 20,000, which is 2 × 10⁴. An extra zero crept in somewhere — recount them."}]'::jsonb WHERE id = 'ddb8b760-ca24-422f-9605-e7c1cbf7dcca';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "stopped at breaths per hour", "wrong": "900", "message": "15 per minute × 60 minutes = 900 per hour is a correct middle step. The question asks for a day, so there are 24 more of those: 900 × 24 ≈ 22,000, about 2 × 10⁴."}, {"tag": "unit-not-converted", "label": "multiplied per-minute rate by hours", "wrong": "360", "message": "You used 15 per minute × 24, but the 24 counts hours, not minutes. Minutes and hours need the ×60 link between them: 15 × 60 × 24 ≈ 2 × 10⁴."}, {"tag": "extra-chain-step", "label": "converted through seconds too", "wrong": "1.3 x 10^6", "message": "Your chain has one link too many. Breaths per minute already sits in minutes, so you only need ×60 (to an hour) and ×24 (to a day). The extra ×60 for seconds pushes the answer up by a factor of 60, to over a million."}, {"tag": "power-of-ten", "label": "one power of ten low", "wrong": "2 x 10^3", "message": "15 × 60 × 24 is the right chain. 15 × 60 = 900, and 900 × 24 is about 900 × 25 = 22,500 — that is 2 × 10⁴, one power of ten above what you entered."}]'::jsonb WHERE id = '750a4dd2-7eb2-4e0d-ba07-2db00026f5eb';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "wrong-time-span", "label": "used 365 days", "wrong": "548", "message": "1.5 h × 365 counts every calendar day. The question says school days — about 180 in a year — so it is 1.5 × 180 ≈ 270 h."}, {"tag": "intermediate-answer", "label": "gave the number of school days", "wrong": "180", "message": "180 is the number of school days — a correct link in the chain. The question asks for hours, so multiply by 1.5 h per day: 1.5 × 180 ≈ 270 h."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "2700", "message": "1.5 × 180 is the right chain. 180 + half of 180 (90) is 270, not 2,700 — the decimal point moved a place. Sense-check: even 2 h × 180 days is only 360 h."}, {"tag": "rounded-early", "label": "rounded 180 to 200 first", "wrong": "300", "message": "1.5 × 200 = 300 is a fair estimate and the right chain. The expected value uses the usual 180 school days: 1.5 × 180 = 270 h. Rounding a factor up by 10% moves the answer up by 10%, so round at the end when the numbers are easy anyway."}]'::jsonb WHERE id = 'b5c6784a-d7d4-4b34-854e-b20854b6540b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "power-of-ten", "label": "one power of ten low", "wrong": "4 x 10^5", "message": "60,000 × 70 kg is the right chain. 6 × 7 = 42, and the zeros: four from 60,000 and one from 70 make five, so 4.2 × 10⁶ kg. Count zeros separately from the digits."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "4 x 10^7", "message": "60,000 × 70 kg is the right chain and 42 is the right leading pair. There are five zeros to carry — four from 60,000, one from 70 — so 4,200,000 = 4 × 10⁶ kg."}, {"tag": "intermediate-answer", "label": "gave the head count", "wrong": "6 x 10^4", "message": "6 × 10⁴ is the number of people, which is given. The question asks for mass, so each person still needs a mass: 60,000 × ~70 kg ≈ 4 × 10⁶ kg."}]'::jsonb WHERE id = 'f9aae9ba-a14b-4937-88b8-f4ce885c277d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "divided litres by millilitres", "wrong": "0.75", "message": "30 ÷ 40 is the right division, but the 30 is in litres and the 40 is in millilitres. Put both in mL first: 30 L = 30,000 mL, so 30,000 ÷ 40 ≈ 750 — a few hundred once you allow for gaps between balls."}, {"tag": "power-of-ten", "label": "one power of ten high", "wrong": "7500", "message": "Backpack volume ÷ ball volume is the right chain. 30 L is 30,000 mL (three zeros for L → mL), and 30,000 ÷ 40 = 750, not 7,500. Recount the conversion zeros."}, {"tag": "intermediate-answer", "label": "gave the backpack volume in mL", "wrong": "30000", "message": "30,000 mL is the backpack''s volume — a correct middle step. The question asks how many balls, so divide by the volume of one ball: 30,000 ÷ 40 ≈ 750, or a few hundred with packing gaps."}]'::jsonb WHERE id = '7154924b-ea13-4b76-9468-e63dfa734342';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "gave the exact product", "wrong": "2190", "message": "$6 × 365 = $2,190 is the exact product and the chain is right. The question says ''roughly'', so the expected entry is the rounded figure — about $2,000. For an estimate, 6 × 365 ≈ 6 × 350 or 6 × 400 both land near 2,000."}, {"tag": "wrong-time-span", "label": "multiplied by 52 weeks", "wrong": "312", "message": "$6 × 52 counts one coffee a week. The question says daily, so the count is 365 days: 6 × 365 ≈ $2,000."}, {"tag": "power-of-ten", "label": "one power of ten low", "wrong": "200", "message": "6 × 365 is the right chain. 6 × 365 is a bit under 6 × 400 = 2,400, so about $2,000 — not $200. Sense-check: $200 would only buy about a month of daily coffee."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "20000", "message": "6 × 365 is the right chain. 6 × 400 would be 2,400, so 6 × 365 is a bit under that — about $2,000. An extra zero crept in; recount them."}]'::jsonb WHERE id = 'ec3fca1c-5dc5-48e3-8ffb-86e5dee1116c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "left the area in square metres", "wrong": "2 x 10^9", "message": "8 × 10⁹ people ÷ 4 per m² = 2 × 10⁹ m² is a correct step. To compare with a city, convert to km²: 1 km² = 10⁶ m², so 2 × 10⁹ m² = 2,000 km². LA county is a few thousand km² more than that."}, {"tag": "multiplied-not-divided", "label": "multiplied people by density", "wrong": "3.2 x 10^10", "message": "You multiplied 8 × 10⁹ people by 4 people/m². Area is people ÷ (people per m²) — the people cancel and m² is left. 8 × 10⁹ ÷ 4 = 2 × 10⁹ m² = 2,000 km²."}, {"tag": "forgot-square", "label": "used 1000 m² per km²", "wrong": "2 x 10^6", "message": "The people ÷ density step is right: 2 × 10⁹ m². The conversion slipped — 1 km is 1,000 m, so 1 km² is 1,000 × 1,000 = 10⁶ m². Dividing by 10⁶ gives 2 × 10³ km², not 2 × 10⁶."}, {"tag": "conversion-direction", "label": "multiplied by 1000 converting to km²", "wrong": "2 x 10^12", "message": "2 × 10⁹ m² is the right area. Going from m² to km² makes the number smaller, since a km² is a much bigger unit — divide by 10⁶ rather than multiplying. 2 × 10⁹ ÷ 10⁶ = 2,000 km²."}]'::jsonb WHERE id = '8a82a17b-f0b6-4100-bd62-1dd1d42b8589';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "gave the exact product", "wrong": "730", "message": "2 × 365 = 730 is the exact product and the chain is right. As an estimate the expected entry is about 700 — the question only wants the size, so one figure is enough."}, {"tag": "wrong-time-span", "label": "multiplied by 52 weeks", "wrong": "104", "message": "2 × 52 counts two slices a week. The estimate is two slices a day, and a year has 365 days: 2 × 365 ≈ 700."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "7000", "message": "2 × 365 is the right chain. Double 365 is 730, about 700 — not 7,000. Sense-check: 7,000 slices a year would be about 20 a day."}, {"tag": "intermediate-answer", "label": "gave the per-day count", "wrong": "2", "message": "About 2 a day is a good first link. The question asks for a year, so multiply by 365 days: 2 × 365 ≈ 700."}]'::jsonb WHERE id = '563bfb19-c83f-41a3-a5bb-3b62a868ee3d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "unit-not-converted", "label": "stopped at minutes", "wrong": "8 x 10^6", "message": "16 × 365 × 24 × 60 ≈ 8 × 10⁶ is the number of minutes — the chain is right so far. Seconds need one more ×60: 8 × 10⁶ × 60 ≈ 5 × 10⁸."}, {"tag": "intermediate-answer", "label": "gave seconds in one year", "wrong": "3 x 10^7", "message": "About 3 × 10⁷ is the number of seconds in one year — a correct and useful middle step. Multiply by 16 years: 16 × 3.15 × 10⁷ ≈ 5 × 10⁸."}, {"tag": "power-of-ten", "label": "one power of ten low", "wrong": "5 x 10^7", "message": "The 5 in front is right. Check the exponent: one year is 3.15 × 10⁷ s, and 16 of them is 50 × 10⁷ = 5 × 10⁸. Multiplying by 16 lifts the power by one."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "5 x 10^9", "message": "The 5 in front is right. One year is 3.15 × 10⁷ s, so 16 years is 16 × 3.15 × 10⁷ ≈ 50 × 10⁷ = 5 × 10⁸, one power of ten below your entry. Recount the zeros in 365 × 24 × 3600."}]'::jsonb WHERE id = 'd323128f-7458-43d4-88bb-4ccef1aad6c6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "gave the exact product", "wrong": "720", "message": "180 × 4 = 720 is the exact product and the chain is right. The question asks for an estimate, so the expected entry is the rounded figure, about 700."}, {"tag": "intermediate-answer", "label": "gave days in one year", "wrong": "180", "message": "180 is the number of school days in one year — a correct first link. High school is 4 years, so multiply: 180 × 4 ≈ 700."}, {"tag": "wrong-time-span", "label": "used 365 days per year", "wrong": "1500", "message": "365 × 4 counts every calendar day. The question asks for school days, which are about 180 a year: 180 × 4 ≈ 700."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "7000", "message": "180 × 4 is the right chain. 180 × 4 = 720, about 700 — not 7,000. Sense-check: 7,000 days is nearly 20 years."}]'::jsonb WHERE id = '64bda71a-6283-4eee-bc23-e5488c4fb265';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "power-of-ten", "label": "one power of ten high", "wrong": "10^3", "message": "A typical novel is a few hundred pages — say 300. In powers of ten, 300 sits between 10² and 10³ and is closer to 10² on a log scale (the crossover is about 316), so the order of magnitude is 10²."}, {"tag": "coefficient-kept", "label": "gave a page count, not a power", "wrong": "300", "message": "About 300 pages is a good estimate. The question asks for the nearest power of ten, so express that as 10²: 300 = 3 × 10², and 3 is closer to 1 than to 10 on a log scale."}, {"tag": "digit-not-value", "label": "gave the exponent only", "wrong": "2", "message": "The 2 is the right exponent. The order of magnitude is the power of ten itself, so write it as 10², not just the 2."}]'::jsonb WHERE id = '5f032079-9170-417a-be21-014b96a8c0b7';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "rounded-early", "label": "rounded to 40 and never adjusted", "expr": "a*40", "message": "Rounding 39 to 40 is the right first move: {a} × 40 is easy. But 40 is one more than 39, so you have added one extra {a}. Take {a} away from {a} × 40 to land on {a} × 39."}, {"tag": "added-not-multiplied", "label": "added instead of multiplying", "expr": "a+39", "message": "You added {a} and 39. The × sign asks for {a} groups of 39 — about {a} groups of 40, then a small adjustment down. That is far bigger than {a} + 39."}, {"tag": "rounded-too-far", "label": "rounded 39 down to 30", "expr": "a*30", "message": "Rounding first is the right idea, but 39 is much closer to 40 than to 30. Use {a} × 40 and then subtract one {a} to adjust for the 1 you added."}, {"tag": "power-of-ten", "label": "dropped a zero from 40", "expr": "a*4", "message": "Rounding 39 to 40 is right, and {a} × 4 is the right digit work. Now put the zero back: {a} × 40 is ten times {a} × 4. Then adjust down by one {a}."}]'::jsonb WHERE id = '0f7c6958-1019-4739-b650-c230e7731609';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "gave the number of pianos", "wrong": "10^4", "message": "About 10⁴ pianos in a city of a million (1 per 100 people) is a sound first link. The question asks for tuners, so two more links: tunings needed per year, and tunings one tuner can do per year (roughly 4 a day × 250 days ≈ 10³). 10⁴ ÷ 10³ ≈ 10 tuners."}, {"tag": "multiplied-not-divided", "label": "multiplied pianos by tunings per tuner", "wrong": "10^7", "message": "Your links look right — about 10⁴ pianos and about 10³ tunings per tuner per year. Tuners = tunings needed ÷ tunings each can do, so the last step is a division: 10⁴ ÷ 10³ ≈ 10, not 10⁴ × 10³."}, {"tag": "power-of-ten", "label": "gave tunings per tuner per year", "wrong": "10^3", "message": "About 10³ is how many tunings one tuner can do in a year — a correct link. The city needs about 10⁴ tunings a year, so 10⁴ ÷ 10³ ≈ 10 tuners. The final step divides the demand by one tuner''s capacity."}, {"tag": "inverted-ratio", "label": "divided the other way round", "wrong": "0.1", "message": "Your links are right, but the last division went the other way round. Tuners = tunings needed ÷ tunings per tuner = 10⁴ ÷ 10³ ≈ 10. A fraction of a tuner can''t serve a whole city, so the answer must be more than 1."}]'::jsonb WHERE id = '12dd7b16-4627-4613-acad-d620572420f8';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "power-of-ten", "label": "one power of ten low", "wrong": "10^4", "message": "Density × scalp area is the right chain. With about 200 per cm² and about 500 cm² of scalp, 200 × 500 = 100,000 = 10⁵. Count the zeros: 2 × 5 = 10, then two zeros from 200 and two from 500."}, {"tag": "decimal-shift", "label": "one power of ten high", "wrong": "10^6", "message": "Density × scalp area is the right chain. 200 × 500 = 100,000, which is 10⁵ — an extra zero crept in. A scalp is about 500 cm² (roughly a 20 cm × 25 cm patch), not 5,000."}, {"tag": "intermediate-answer", "label": "gave the scalp area", "wrong": "500", "message": "About 500 cm² is a reasonable scalp area — a correct link. The question asks for hairs, so multiply by the density: 200 per cm² × 500 cm² ≈ 10⁵."}, {"tag": "unit-not-converted", "label": "mixed cm² density with m² area", "wrong": "10", "message": "Your density was per cm² but your area was in m² (about 0.05 m²). Keep one unit: 0.05 m² is 500 cm², so 200 per cm² × 500 cm² ≈ 10⁵. Ten hairs would be a very sparse head."}]'::jsonb WHERE id = '5220cdd2-4f75-4bc2-acc2-e271a914d895';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "stopped at hours", "wrong": "8760", "message": "365 × 24 = 8,760 is the number of hours in a year — a correct middle step. Minutes need one more ×60: 8,760 × 60 ≈ 5 × 10⁵."}, {"tag": "sig-figs-over", "label": "gave the exact count", "wrong": "525600", "message": "525,600 is the exact number of minutes, and the chain 365 × 24 × 60 is right. The question asks for a power of ten, so the expected entry is the rounded form: about 5 × 10⁵."}, {"tag": "extra-chain-step", "label": "converted through seconds too", "wrong": "3 x 10^7", "message": "Your chain has one link too many: 365 × 24 × 60 already gives minutes. The second ×60 turns minutes into seconds, which is why you landed near 3 × 10⁷. Minutes are about 5 × 10⁵."}, {"tag": "power-of-ten", "label": "one power of ten low", "wrong": "5 x 10^4", "message": "The 5 in front is right. Check the exponent: 365 × 24 ≈ 8,800 hours, and 8,800 × 60 ≈ 530,000, which is 5 × 10⁵. Multiplying by 60 adds more than one power of ten to 8,800."}]'::jsonb WHERE id = '3c3d0780-87e4-4db2-b891-d169e1134e63';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "count-not-value", "label": "Reported the sig-fig count, not mass", "wrong": "3", "message": "You found that the report needs three significant figures, and that count is right. The question asks for the mass itself, so write the rounded reading with its unit: 2.3865 kg to the nearest 0.01 kg is 2.39 kg."}, {"tag": "precision-not-value", "label": "Reported the scale''s resolution instead", "wrong": "0.01 kg", "message": "You picked out the 0.01 kg the scale can be trusted to, and that is the right place to look. That number tells you where to cut the reading, not what to report. Round 2.3865 kg at the hundredths place and write that mass."}, {"tag": "sig-figs-under", "label": "Rounded to a whole kilogram", "wrong": "2 kg", "message": "You rounded, which is the right move, but you cut at the ones place. The scale is trusted to 0.01 kg, so the hundredths digit is real information. Keep 2.38|65 and round at the vertical bar: 2.39 kg."}]'::jsonb WHERE id = '4690ff30-8955-47f7-b54c-f9165f0ff069';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-under", "label": "Kept only two significant figures", "wrong": "3.1", "message": "You rounded at the tenths place, which gives two significant figures. The 3 before the point counts as the first one, so three figures means 3, 1, and 4. Look at the fourth digit (a 1) to decide, and keep 3.14."}, {"tag": "sig-figs-one", "label": "Rounded to a whole number", "wrong": "3", "message": "You rounded to the nearest whole number, which is one significant figure. Three significant figures means the first three digits reading left to right: 3, 1, 4. The digit after them is a 1, so nothing rounds up: 3.14."}]'::jsonb WHERE id = '8d670cc4-213e-4e80-8115-2d34e9b90971';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "leading-zeros-counted", "label": "Counted the leading zeros too", "wrong": "5", "message": "You counted every digit after the decimal point. The zeros before the 4 only fix the size of the number, so they are placeholders, not measured digits. Start counting at the first non-zero digit: 4, 5, and the final 0 give three."}, {"tag": "trailing-zero-dropped", "label": "Dropped the trailing zero", "wrong": "2", "message": "You counted 4 and 5 and stopped, which handles the leading zeros correctly. A zero written after the last non-zero digit in a decimal is there on purpose: it says the thousandths place was measured. Count it, giving three."}, {"tag": "all-digits-counted", "label": "Counted every digit, including the first zero", "wrong": "6", "message": "You counted all six characters that are digits. The zero before the point and the two right after it only place the decimal; they are not measured. Count from the first non-zero digit: 4, 5, 0 is three."}]'::jsonb WHERE id = 'ccc28391-af37-49a4-8463-ba919902e20f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-under", "label": "Rounded to one significant figure", "wrong": "9", "message": "Your product 8.55 is right, and you rounded it. You went to one figure, but the rule for multiplying is the fewest sig figs among the inputs, and 2.5 has two. Round 8.55 to two figures: 8.6."}, {"tag": "rounding-direction", "label": "Rounded 8.55 down to 8.5", "wrong": "8.5", "message": "Your product 8.55 is right and two sig figs is the right count. Cutting after the 5 without looking at the next digit is truncating, not rounding. The dropped digit is a 5, which rounds up: 8.6."}, {"tag": "added-not-multiplied", "label": "Added instead of multiplied", "wrong": "5.92", "message": "You combined the two numbers, but with addition: 2.5 + 3.42 = 5.92. The question asks for the product. Multiply to get 8.55, then keep the fewest sig figs of the inputs, which is two from 2.5: 8.6."}]'::jsonb WHERE id = 'dc04f032-c543-4f97-8250-9aaa1c5789ec';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "count-not-value", "label": "Reported the sig-fig count, not length", "wrong": "3", "message": "Three significant figures is the right count for a ruler that reads to the millimetre. The question wants the length written that way, so show the millimetre digit even when it is zero: 12.0 cm."}, {"tag": "precision-not-value", "label": "Reported the ruler''s resolution instead", "wrong": "0.1 cm", "message": "You worked out that a millimetre is 0.1 cm, which is the ruler''s resolution and the right place to stop. Now use it: the length is 12 cm to that resolution, so write the tenths digit, 12.0 cm."}, {"tag": "decimal-shift", "label": "Moved the decimal point over", "wrong": "1.2 cm", "message": "You know the answer needs a decimal digit, but the point moved left and the length shrank ten times. Adding precision never changes the size: 12 cm stays 12 and gains a tenths digit, 12.0 cm."}]'::jsonb WHERE id = '1e3fc9e2-2ce9-4207-967d-62e4f8d4df4a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "leading-zeros-counted", "label": "Counted the leading zeros as significant", "wrong": "0.08", "message": "You cut two digits after the decimal point. The 0 before the 8 is a placeholder, so significant figures start at the 8. Two figures are 8 and 1, and the next digit is 5, which rounds up: 0.082."}, {"tag": "rounding-direction", "label": "Truncated at the second figure", "wrong": "0.081", "message": "You found the right two figures, 8 and 1, and stopped there. The digit after them is a 5, and a 5 rounds the last kept digit up. 0.081|55 becomes 0.082."}, {"tag": "sig-figs-under", "label": "Rounded to one significant figure", "wrong": "0.1", "message": "You rounded to the tenths place, which keeps only one significant figure. Two figures means two measured digits starting at the 8: 0.081|55, and the 5 after the bar rounds it to 0.082."}]'::jsonb WHERE id = '718a2ee4-80be-491a-93b0-fb917c2ae631';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "Added a zero the scale can''t justify", "wrong": "5.70 g", "message": "You wrote the reading with an extra zero. That zero is a claim that the hundredths place was measured, and a scale reading to 0.1 g never saw it. Report what the scale knows: 5.7 g."}, {"tag": "precision-not-value", "label": "Reported the scale''s resolution instead", "wrong": "0.1 g", "message": "You identified the 0.1 g resolution, which is the key fact here. The question asks how to report the coin''s mass with that resolution, so the answer is the reading itself with one decimal: 5.7 g."}, {"tag": "sig-figs-under", "label": "Rounded away the tenths digit", "wrong": "6 g", "message": "You rounded to a whole gram, which throws away a digit the scale actually measured. The tenths place is trustworthy on a 0.1 g scale, so keep it: 5.7 g, not 5.70 g and not 6 g."}]'::jsonb WHERE id = '7a49cf68-a72f-441a-84da-f9f712a7472b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-under", "label": "Rounding-position slip: whole number only", "expr": "a", "message": "You rounded to one significant figure. Three figures means the first three digits reading left to right, {a}, {b}, 4, and the fourth digit, 7, decides the rounding. Keep the point where it was."}, {"tag": "count-not-value", "label": "Count slip: answered 3, not value", "expr": "3", "message": "Three is the number of figures to keep, and you have that right. The question wants the rounded number itself: keep {a}, {b}, 4 and look at the 7 that follows to round the last one up."}]'::jsonb WHERE id = '6774650e-084e-4e04-9713-e5c42ae06962';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-rule-for-addition", "label": "Used the sig-fig rule for adding", "wrong": "20", "message": "Your sum 17.437 is right, and you noticed 0.3 has one significant figure. That rule belongs to multiplying. Adding is limited by decimal places, and 0.3 stops at tenths, so round the sum at the tenths place: 17.4."}, {"tag": "sig-figs-under", "label": "Rounded to a whole number", "wrong": "17", "message": "Your sum 17.437 is right. When adding, keep the fewest decimal places among the inputs; 0.3 has one, so the tenths place survives. Round at the tenths: 17.4."}]'::jsonb WHERE id = 'ac032260-6dfa-4705-8c31-2458230a5122';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "Kept all the calculator digits", "wrong": "1.02 m²", "message": "The product 1.02 m² is right, but it carries three figures while both lengths were measured to only two. A product cannot be more certain than its least certain input, so round to two figures: 1.0 m²."}, {"tag": "added-not-multiplied", "label": "Added the sides instead", "wrong": "2.05 m²", "message": "You combined the sides by adding: 1.2 + 0.85 = 2.05. Area is length times width, which the question gives as 1.02 m². Then keep the fewest sig figs of the inputs, two: 1.0 m²."}]'::jsonb WHERE id = '6792ab2e-1d6b-44fa-b2f0-0cdea5482381';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "precision-not-value", "label": "Reported the precision, not the measurement", "wrong": "0.1 cm", "message": "You worked out that 12.0 cm is known to 0.1 cm, which is the reasoning the question is after. It asks which measurement is more precise, so answer with that measurement: 12.0 cm."}, {"tag": "count-not-value", "label": "Answered with a sig-fig count", "wrong": "3", "message": "Three is the number of significant figures in 12.0 cm, and more figures does mean more precision. The question asks which measurement wins, so name it: 12.0 cm."}, {"tag": "count-not-value-other", "label": "Answered with the other count", "wrong": "2", "message": "Two is the number of significant figures in 12 cm. Counting figures is the right way to compare, and 12.0 cm has three, so it is the more precise one. Answer with the measurement: 12.0 cm."}]'::jsonb WHERE id = 'a47bedce-7da9-48b2-b8d7-0de00df5a375';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "Copied every calculator digit", "expr": "a + b/10 + 0.285714", "message": "The calculation is right; the calculator just shows more digits than the measurement earned. Inputs with two significant figures give a result you can trust to two, so cut after {a}.{b} and let the 2 that follows round nothing up."}, {"tag": "sig-figs-under", "label": "Rounded to one figure", "expr": "a", "message": "You rounded, but to a whole number, which keeps one significant figure. The digit before the point is the first figure and {b} is the second, so two figures is {a}.{b}. The next digit, 2, leaves it alone."}, {"tag": "count-not-value", "label": "Answered with the sig-fig count", "expr": "2", "message": "Two significant figures is the right count. The question wants the reported value: the first two digits of {a}.{b}285714 are {a} and {b}, and the 2 after them rounds nothing up, so report {a}.{b}."}]'::jsonb WHERE id = '10894097-95c4-49a4-aab0-f0c1eec1354c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "power-of-ten", "label": "Exponent one too small", "wrong": "1.50 x 10^2", "message": "The coefficient 1.50 shows exactly three figures, which is the point of the question. The exponent counts how many places the point moved from 1500 to 1.50, and that is three, so the power is 10^3."}, {"tag": "exponent-sign", "label": "Exponent one too large", "wrong": "1.50 x 10^4", "message": "The coefficient 1.50 is right for three figures. For the exponent, count the places the point slides from 1500. to 1.500: three, not four. 1.50 x 10^3 equals 1500; 10^4 would be 15 000."}, {"tag": "count-not-value", "label": "Answered with the sig-fig count", "wrong": "3", "message": "Three is the number of figures wanted, and you have that. The question asks you to write 1500 so that exactly three show. Trailing zeros are ambiguous, so use scientific notation: 1.50 x 10^3."}]'::jsonb WHERE id = 'ffd6d452-4b89-43f6-b4c3-c80dc426e243';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sig-figs-over", "label": "Kept the phone''s four figures", "wrong": "2.000 km", "message": "You reported the phone''s figure as given. Each trailing zero claims another measured place, so 2.000 km says the walk is known to the metre. A rough app cannot support that; 2.0 km says what was actually known."}, {"tag": "count-not-value", "label": "Answered with the sig-fig count", "wrong": "4", "message": "Four is the number of figures 2.000 claims, and spotting that is the heart of the problem. The question asks how the distance should be reported: drop the unearned zeros to 2.0 km."}, {"tag": "precision-not-value", "label": "Reported the claimed precision instead", "wrong": "0.001 km", "message": "You found that 2.000 km claims precision to 0.001 km, one metre, and that is exactly what a rough app cannot deliver. The report should be the distance with an honest number of figures: 2.0 km."}]'::jsonb WHERE id = '5dbacd3b-35ad-4d26-9376-57c22eea0bf0';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "Reported the difference, not the comparison", "wrong": "0.3", "message": "You subtracted to get a gap of 0.3, which is the first step. Now compare that gap with the uncertainties: 9.8 could be as low as 9.6 and 9.5 as high as 9.7, so the ranges overlap and the values are not clearly different."}, {"tag": "combined-uncertainty", "label": "Reported the combined uncertainty only", "wrong": "0.4", "message": "Adding the two uncertainties to 0.4 is a good move, because that is the smallest gap that would separate them. The measured gap is 0.3, which is less than 0.4, so the ranges overlap and the values are not clearly different."}, {"tag": "overlap-not-conclusion", "label": "Reported the size of the overlap", "wrong": "0.1", "message": "You built the ranges 9.6 to 10.0 and 9.3 to 9.7 and found they share 0.1. That overlap is the evidence; the answer it supports is that the two measurements are not clearly different."}]'::jsonb WHERE id = '7cf64cf5-9907-4c1b-a60e-d44fc825bc61';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "uncertainty-added-to-value", "label": "Added the reaction time on", "wrong": "12.5 s", "message": "You added 0.2 s to the reading. Reaction time is an uncertainty, not a correction: it could make the reading early or late. It sets how many digits you can trust, so keep the reading and cut it to the tenths: 12.3 s."}, {"tag": "sig-figs-under", "label": "Rounded to a whole second", "wrong": "12 s", "message": "You rounded because the reaction time swamps the last digit, and that instinct is right. A ±0.2 s uncertainty still leaves the tenths place meaningful, so cut only the hundredths: 12.3 s."}, {"tag": "precision-not-value", "label": "Reported the uncertainty instead", "wrong": "0.2 s", "message": "You picked out the 0.2 s uncertainty, which is what decides the rounding. The question asks for the time itself, so apply it: the hundredths digit of 12.31 s is inside that uncertainty and gets dropped, leaving 12.3 s."}]'::jsonb WHERE id = '2d99580b-a440-4a67-8d8c-18ece53edc1d';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "part-not-whole", "label": "Reported estimate as percent of true", "expr": "a*10", "message": "You compared {a}0 with 100 as a percentage, which is a fair ratio, but percent error starts from the difference. Subtract first, |{a}0 − 100|, then divide by the true value 100 and multiply by 100."}, {"tag": "inverted-ratio", "label": "Divided true value by estimate", "expr": "1000/a", "message": "You divided, but with the true value on top. Percent error is the difference between estimate and true, divided by the true value. Find |{a}0 − 100| first, then divide by 100 and multiply by 100."}]'::jsonb WHERE id = 'b6293193-6a2b-4db0-a689-cf7446092ec6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "flipped the fraction: t² over 2d", "wrong": "0.5t²/d", "message": "You moved the ½ and the t² across, but the fraction ended upside down. d = ½at² means a is being multiplied by ½t², so to undo that you divide d by ½t², which gives 2d on top and t² on the bottom: a = 2d/t²."}, {"tag": "multiplied-not-divided", "label": "kept the ½ instead of dividing", "wrong": "0.5d/t²", "message": "Dividing by t² is right. The ½ is also multiplying a, so it has to be undone by dividing — and dividing by ½ is the same as multiplying by 2. That''s where the 2 in a = 2d/t² comes from."}, {"tag": "forgot-square", "label": "dropped the square on t", "wrong": "2d/t", "message": "The 2 is in the right place and it''s on top. In d = ½at² the time is squared, and rearranging doesn''t change that: a = 2d/t². Only a square root would remove the exponent, and nothing here calls for one."}]'::jsonb WHERE id = 'e982eb25-0d36-4576-90dc-ea3f242f3ffc';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sign-dropped", "label": "moved w across with the wrong sign", "wrong": "0.5P + w", "message": "Dividing both sides by 2 first is a good move: P/2 = l + w. The w is being added to l, so to undo it you subtract w from both sides: l = P/2 − w. A term keeps its sign on its own side and flips it when it crosses."}, {"tag": "order-of-operations", "label": "subtracted w before undoing the 2", "wrong": "0.5(P − w)", "message": "You subtracted w and divided by 2, just in the other order. On the right side the 2 multiplies the whole bracket (l + w), so it is the outermost operation and gets undone first: P/2 = l + w, then l = P/2 − w."}]'::jsonb WHERE id = '235b1018-b77e-469b-9f5d-d636efb75916';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "squared-not-rooted", "label": "squared instead of taking the square root", "wrong": "4KE²/m²", "message": "Getting to v² = 2KE/m is the hard part and you have it. The last step undoes a square, and the opposite of squaring is a square root, not another square: v = √(2KE/m)."}, {"tag": "inverted-ratio", "label": "fraction upside down, no square root", "wrong": "0.5m/KE", "message": "KE = ½mv² means v² is multiplied by ½m, so to isolate v² you divide KE by ½m: v² = 2KE/m, with KE on top. Then take the square root of both sides: v = √(2KE/m)."}]'::jsonb WHERE id = 'f6c09eaf-6ff4-4901-ba89-a44f388a15cd';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "intermediate-answer", "label": "wrote the moved constant only", "wrong": "-7", "message": "Subtracting 7 from both sides is the right move. But the answer is an expression for x, not the number you moved: y − 7 = x. Write out what is left on each side after the step."}, {"tag": "attached-as-factor", "label": "turned the 7 into a multiplier", "wrong": "-7y", "message": "The 7 is being added to x, so it leaves the other side by subtraction, not multiplication: x = y − 7. Check with a number: if x = 3 then y = 10, and 10 − 7 gives 3 back."}]'::jsonb WHERE id = '38d56610-db59-4a07-a160-5b19b5e5801c';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "subtracted-not-divided", "label": "subtracted the 4 instead of dividing", "wrong": "-4 + y", "message": "You moved the 4 across by subtracting. In y = 4x the 4 is multiplying x, so it is undone by dividing both sides by 4: x = y/4. Check with a number: if x = 2 then y = 8, and 8/4 gives 2 back."}, {"tag": "intermediate-answer", "label": "wrote the step, not the expression", "wrong": "1/4", "message": "Dividing by 4 is the right step. The answer needs to say what x equals in terms of y, so carry the y through: x = y/4."}]'::jsonb WHERE id = '288d19e2-4f8a-4824-b45b-7e253e03f6f4';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "multiplied by 2π instead of dividing", "wrong": "2πC", "message": "You moved 2π across, but it is multiplying r in C = 2πr, so it leaves by division: r = C/(2π). Check the size: a circumference of 6.28 should give a radius of 1, not 39."}, {"tag": "inverted-ratio", "label": "flipped the fraction: 2π over C", "wrong": "2π/C", "message": "Dividing by 2π is the right idea, but the fraction is upside down. Divide both sides of C = 2πr by 2π and the C stays on top: r = C/(2π)."}, {"tag": "half-undone", "label": "divided by π but multiplied by 2", "wrong": "2C/π", "message": "Dividing by π is right. The 2 is also multiplying r, so it has to be divided out the same way: r = C/(2π). Both factors leave by the same operation."}]'::jsonb WHERE id = '738441e0-4bd9-4a9d-bfaa-3a98dd21ccf6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "multiplied-not-divided", "label": "kept the ½ instead of dividing", "wrong": "0.5A/b", "message": "Dividing by b is right. The ½ is also multiplying h, so it comes off by dividing — and dividing by ½ is the same as multiplying by 2: h = 2A/b."}, {"tag": "inverted-ratio", "label": "flipped the fraction: b over A", "wrong": "0.5b/A", "message": "In A = ½bh the h is being multiplied by ½b, so to isolate h you divide A by ½b — A stays on top: h = A/(½b) = 2A/b. Check: a triangle with A = 6 and b = 3 has h = 4."}]'::jsonb WHERE id = '764f4b13-e421-4bf7-b1b5-b452ca780888';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "divided-not-multiplied", "label": "divided by 2 instead of multiplying", "wrong": "0.5s − b", "message": "Subtracting b is the right second step. In s = (a + b)/2 the sum is being divided by 2, so the first step is to multiply both sides by 2: 2s = a + b, then a = 2s − b."}, {"tag": "sign-dropped", "label": "divided by 2 and kept b positive", "wrong": "0.5s + b", "message": "Two steps to revisit. The 2 is dividing (a + b), so undo it by multiplying: 2s = a + b. Then b is being added to a, so it crosses by subtraction: a = 2s − b. Check: a = 4, b = 2 gives s = 3, and 2(3) − 2 gives 4 back."}]'::jsonb WHERE id = '7705e37e-60ea-4f9a-8531-4ca2807556cf';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-not-multiplied", "label": "added m and a", "wrong": "854.2 N", "message": "You put 850 kg and 4.2 m/s² into the right places, then added them. F = ma means m times a, so the substitution reads (850 kg)(4.2 m/s²). Check: kg × m/s² is a newton; kg + m/s² isn''t a unit at all."}, {"tag": "divided-not-multiplied", "label": "divided m by a", "wrong": "202 N", "message": "Your values are in the right slots, but you divided 850 by 4.2. Written side by side, ma means multiply: (850 kg)(4.2 m/s²). A heavier car needing more force to reach the same acceleration is a quick sanity check."}, {"tag": "decimal-shift", "label": "decimal point slipped one place", "wrong": "357 N", "message": "The digits 3-5-7 are right, so the multiplication was set up correctly — the decimal point landed one place off. Estimate first: 850 × 4 is 3,400, so the answer has to be in the thousands."}]'::jsonb WHERE id = '00a96acc-b11a-4ef8-a9c6-27a198894e30';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "half-forgotten", "label": "left out the ½", "wrong": "18 J", "message": "You squared the velocity and multiplied by the mass — that part is done. The ½ in front still has to be applied: ½ × 2 kg × (3 m/s)². Halve your 18 J."}, {"tag": "forgot-square", "label": "did not square v", "wrong": "3 J", "message": "You kept the ½ and the mass, but used v instead of v². Only the velocity is squared: (3 m/s)² = 9 m²/s². Then ½ × 2 kg × 9 m²/s²."}, {"tag": "doubled-not-squared", "label": "doubled v instead of squaring", "wrong": "6 J", "message": "The ½ and the mass are in place, but 3 became 6 — that''s 3 × 2, not 3². Squaring means multiplying the number by itself: 3 × 3 = 9. Then ½ × 2 × 9."}]'::jsonb WHERE id = 'f0a41884-9072-485c-9cf8-87249462e4b6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided m by F", "wrong": "0.2 m/s^2", "message": "You divided, which is the right operation, but the other way round. Rearranged, a = F ÷ m, so the force goes on top: 50 N ÷ 10 kg. Check: a 50 N push on 10 kg should produce more than a fifth of a metre per second squared."}, {"tag": "multiplied-not-divided", "label": "multiplied F and m", "wrong": "500 m/s^2", "message": "You substituted 50 N and 10 kg, then multiplied them. F = ma has to be rearranged first: a = F ÷ m. Dividing 50 N by 10 kg gives the acceleration; units check as N/kg = m/s²."}]'::jsonb WHERE id = '93d0e697-9238-4dd5-b503-49ded64457cf';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided t by d", "wrong": "0.04 m/s", "message": "You divided the two numbers, but the other way round. Speed is distance per second, so the distance goes on top: 150 m ÷ 6 s. Check: something covering 150 m in 6 s is moving faster than 0.04 m every second."}, {"tag": "multiplied-not-divided", "label": "multiplied d and t", "wrong": "900 m/s", "message": "You substituted 150 m and 6 s correctly, then multiplied. The slash in d/t means divide: 150 m ÷ 6 s. Units help here — m/s is metres divided by seconds, not metres times seconds."}]'::jsonb WHERE id = 'd8b44617-de43-4479-a4f7-c88d8f25fa62';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-not-multiplied", "label": "added m and v", "wrong": "12 kg*m/s", "message": "You put 4 kg and 8 m/s in the right slots, then added them. p = mv means m times v: (4 kg)(8 m/s). The unit kg·m/s is your clue — it''s a product, not a sum."}, {"tag": "divided-not-multiplied", "label": "divided v by m", "wrong": "2 kg*m/s", "message": "Right values, but you divided 8 by 4. Two letters written side by side, mv, means multiply: (4 kg)(8 m/s). Check the unit: kg·m/s comes from multiplying kg by m/s."}, {"tag": "inverted-ratio", "label": "divided m by v", "wrong": "0.5 kg*m/s", "message": "Right values, but you divided 4 by 8. In p = mv the letters sit side by side, which means multiply: (4 kg)(8 m/s). A 4 kg object at 8 m/s carries more than half a unit of momentum."}]'::jsonb WHERE id = 'b1e6f294-eafe-4291-94a9-a9c58bbfd3d7';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "doubled-not-squared", "label": "doubled x instead of squaring", "expr": "2*a", "message": "You substituted x = {a}, then multiplied by 2. The small 2 means multiply the number by itself: {a} × {a}. Doubling and squaring only agree when x = 2."}, {"tag": "forgot-square", "label": "did not square x", "expr": "a", "message": "You substituted x = {a} into the formula, but the exponent didn''t get applied. y = x² means {a} × {a}. Write the substitution as ({a})² before you evaluate."}]'::jsonb WHERE id = '7b413ddd-81ce-4ed3-8754-c544fdc64956';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "order-of-operations", "label": "added the fee before multiplying", "expr": "(a+b)*c", "message": "You included all three numbers, but added ${a} and ${b} first and then multiplied by {c}. Multiplication comes before addition: ${b} × {c} for the miles, then add the flat ${a} once. The flat fee is paid one time, not once per mile."}, {"tag": "intermediate-answer", "label": "answered the mileage cost only", "expr": "b*c", "message": "${b} × {c} miles is the mileage part, and that''s computed correctly. The flat ${a} still has to be added on top — cost = fee + rate × miles."}, {"tag": "added-not-multiplied", "label": "added all three numbers", "expr": "a+b+c", "message": "You substituted all three values, then added them together. The ${b} is a rate — per mile — so it gets multiplied by the {c} miles first, and only the flat ${a} is added: ${a} + ${b} × {c}."}]'::jsonb WHERE id = '94c41b46-2c93-44d2-9caf-53faa57dd67f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "order-of-operations", "label": "multiplied before subtracting", "expr": "a*c - b", "message": "You substituted x = {c} and multiplied by {a} first, then subtracted {b}. The parentheses say the subtraction happens first: {c} − {b}, and then that whole result is multiplied by {a}."}, {"tag": "sign-dropped", "label": "added inside the parentheses", "expr": "a*(c+b)", "message": "You did the parentheses first and then multiplied — the order is right. Inside the bracket it''s x − {b}, so with x = {c} that''s {c} − {b} before multiplying by {a}."}, {"tag": "intermediate-answer", "label": "stopped after the parentheses", "expr": "c-b", "message": "{c} − {b} is the value of the parentheses, and that''s the correct first step. The {a} in front still multiplies that result: {a} × ({c} − {b})."}]'::jsonb WHERE id = '6c0822f2-e0ff-4766-b70a-55a15901ef77';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "half-forgotten", "label": "left out the ½", "expr": "a*b", "message": "You multiplied base by height — {a} cm × {b} cm — which is the rectangle. A triangle is half of that, so the ½ still has to be applied: ½ × {a} × {b} cm²."}, {"tag": "added-not-multiplied", "label": "added b and h then halved", "expr": "(a+b)/2", "message": "You applied the ½, but to {a} + {b} instead of {a} × {b}. Letters side by side, bh, mean multiply: ½ × {a} cm × {b} cm. The unit cm² comes from cm × cm."}, {"tag": "halved-twice", "label": "halved both base and height", "expr": "a*b/4", "message": "You halved {a} and halved {b}, then multiplied — that''s two halvings, so the result is a quarter of bh. The ½ is applied once to the product: ½ × ({a} × {b})."}]'::jsonb WHERE id = '92dfdd2f-12b2-419c-81d3-54fd69f3c855';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "order-of-operations", "label": "divided before adding the bottom", "expr": "c*10/a + b", "message": "You substituted x = {c}0, but divided by {a} and then added {b}. The parentheses in the denominator mean the whole bottom is built first: {a} + {b}. Then {c}0 divided by that sum."}, {"tag": "digit-not-value", "label": "used x as {c} not {c}0", "expr": "c/(a+b)", "message": "You added the denominator first and divided — the order is right. But x = {c}0, not {c}; the trailing zero makes it ten times bigger. Re-run it with {c}0 on top."}, {"tag": "inverted-ratio", "label": "divided the bottom by x", "expr": "(a+b)/(c*10)", "message": "You added {a} + {b} first, which is the right start, but then divided that sum by x. The fraction is x over the sum, so x = {c}0 goes on top: {c}0 ÷ ({a} + {b})."}]'::jsonb WHERE id = 'ff532a22-3347-4727-a026-a5c6082fa4df';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "squared-not-doubled", "label": "squared r instead of doubling", "expr": "3.14159*a^2", "message": "You used π and r = {a} cm, but squared the radius — that''s the area formula πr². Circumference is 2πr: the 2 multiplies, nothing gets squared. Evaluate 2 × π × {a}, and the unit stays cm."}, {"tag": "factor-dropped", "label": "left out the 2", "expr": "3.14159*a", "message": "π × {a} is set up correctly, but the 2 at the front didn''t get applied. C = 2πr has three factors: 2 × π × {a} cm. Double what you have."}, {"tag": "pi-dropped", "label": "left out π", "expr": "2*a", "message": "You doubled r = {a} cm, which is the diameter. The π still has to multiply in: 2 × π × {a}. A circle''s circumference is a little more than three times its diameter."}]'::jsonb WHERE id = '121add02-31ac-4cb0-8d07-dfe6fe6a8e6b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "added-not-multiplied", "label": "added l and w", "expr": "a+b", "message": "You substituted {a} cm and {b} cm correctly, then added them. The dot in l·w means multiply: {a} cm × {b} cm. Adding lengths gives a length in cm; area needs cm × cm = cm²."}, {"tag": "extra-half", "label": "halved the product", "expr": "a*b/2", "message": "You multiplied {a} × {b} and then halved it — the ½ belongs to the triangle formula. A rectangle is the full product: A = l·w = {a} cm × {b} cm, in cm²."}]'::jsonb WHERE id = 'f0dab88b-e022-4601-92e5-82a434f30209';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "inverted-ratio", "label": "divided games by points", "expr": "b/a", "message": "You divided, but the other way round. An average per game is points ÷ games, so the {a} points go on top: {a} ÷ {b}. Check: a per-game average should be a reasonable score, not a fraction of a point."}, {"tag": "multiplied-not-divided", "label": "multiplied points by games", "expr": "a*b", "message": "You used both numbers but multiplied them. Average means total ÷ count: {a} points ÷ {b} games. Sanity check: an average over several games can''t be bigger than the total."}]'::jsonb WHERE id = '7593b721-626d-4c0c-8578-07d10263f1ea';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "factor-dropped", "label": "added l and w without doubling", "expr": "a+b", "message": "{a} + {b} is one length plus one width — two of the four sides. Each 2 in P = 2l + 2w doubles a side: 2 × {a} + 2 × {b}, or double your sum."}, {"tag": "doubled-once", "label": "doubled only the length", "expr": "2*a + b", "message": "You doubled {a} m but added {b} m only once. Both terms carry a 2: 2 × {a} and 2 × {b}. A rectangle has two lengths and two widths."}, {"tag": "multiplied-not-added", "label": "multiplied l and w then doubled", "expr": "2*a*b", "message": "You doubled and you used both values, but multiplied {a} by {b} — that''s heading toward area. Perimeter adds side lengths: 2 × {a} + 2 × {b}, and the unit stays m."}]'::jsonb WHERE id = 'ed13ea35-ef46-491e-9fd0-7896138e2dd0';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "order-of-operations", "label": "added before multiplying", "expr": "a*(c+b)", "message": "You substituted x = {c} and used all three numbers, but added {b} before multiplying by {a}. With no parentheses, multiplication comes first: {a} × {c}, and then + {b}."}, {"tag": "intermediate-answer", "label": "stopped after multiplying", "expr": "a*c", "message": "{a} × {c} is the first step, done correctly. The + {b} still has to be added on to finish: {a} × {c} + {b}."}, {"tag": "digit-not-value", "label": "wrote {a} and {c} as digits", "expr": "a*10 + c + b", "message": "It looks like {a}x with x = {c} became the two-digit number {a}{c}. A number next to a letter means multiply, so {a}x = {a} × {c}. Then add {b}."}]'::jsonb WHERE id = '8eeb1cef-b182-4c35-a38f-1db6005ca6d6';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "sign-dropped", "label": "gave a positive answer", "expr": "2*b - a", "message": "You multiplied first and got 2 × {b} — that part is right. The formula is {a} minus that, and since 2 × {b} is bigger than {a}, the result is negative. Keep the minus sign."}, {"tag": "order-of-operations", "label": "subtracted 2 before multiplying", "expr": "(a-2)*b", "message": "You did {a} − 2 first, then multiplied by {b}. Multiplication happens before subtraction: 2x means 2 × {b}, and that product is subtracted from {a}."}, {"tag": "added-not-multiplied", "label": "added 2 and x", "expr": "a - 2 + b", "message": "You substituted x = {b}, but the 2x became 2 + {b}. A number written next to a letter means multiply: 2x = 2 × {b}. Then {a} minus that product."}]'::jsonb WHERE id = '22975168-2798-4050-bd40-3ef19206eb9f';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "tripled-not-cubed", "label": "multiplied x by 3", "expr": "3*a", "message": "You substituted x = {a} cm, then multiplied by 3. The small 3 means {a} × {a} × {a}, not {a} × 3. The unit works the same way: cm × cm × cm = cm³."}, {"tag": "squared-not-cubed", "label": "squared instead of cubing", "expr": "a^2", "message": "{a} × {a} is the square. The exponent is 3, so one more factor of {a} is needed: {a} × {a} × {a} cm³."}]'::jsonb WHERE id = '8f59c0bb-47b7-4dfd-ad38-56fc1f9c936a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "cross-term-dropped", "label": "squared each term separately", "expr": "a^2 + b^2", "message": "You squared {a} and {b} separately and added. The parentheses say add first, then square: ({a} + {b})². The difference is the cross term 2xy = 2 × {a} × {b}, which x² + y² leaves out."}, {"tag": "order-of-operations", "label": "squared only y", "expr": "a + b^2", "message": "You substituted both values, but the square landed on {b} alone. The parentheses group x + y together, so the whole sum {a} + {b} is what gets squared."}, {"tag": "doubled-not-squared", "label": "doubled the sum", "expr": "2*(a+b)", "message": "You added inside the parentheses first — {a} + {b} — which is the right order. Squaring that sum means multiplying it by itself, not by 2: ({a} + {b}) × ({a} + {b})."}]'::jsonb WHERE id = 'e1a2e8f5-a1a6-4069-9d69-145195cb561b';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "order-of-operations", "label": "multiplied before raising to the power", "expr": "(2*a)^b", "message": "You used x = {b} as the exponent, but multiplied {a} × 2 first and then raised that to the power. Exponents come before multiplication: 2^{b} first, then times {a}."}, {"tag": "multiplied-not-powered", "label": "computed 2 × x instead of 2^x", "expr": "a*2*b", "message": "You substituted x = {b} and multiplied by {a}, but 2^x became 2 × {b}. The exponent means repeated multiplication: 2 multiplied by itself {b} times. Then multiply by {a}."}, {"tag": "intermediate-answer", "label": "stopped at 2^x", "expr": "2^b", "message": "2^{b} is evaluated correctly — that''s the first step. The {a} in front still multiplies it: {a} × 2^{b}."}]'::jsonb WHERE id = '3c243e1f-5ae2-4632-a2bd-f424dd217b7a';
UPDATE public.math_spiral_items SET misconceptions = '[{"tag": "forgot-square", "label": "added a and b without squaring", "expr": "sqrt(a+b)", "message": "You added and then took the root, which is the right order, but neither value was squared first. Under the root it''s {a}² + {b}²: square each, add, then take the square root."}, {"tag": "intermediate-answer", "label": "stopped before the square root", "expr": "a^2 + b^2", "message": "{a}² + {b}² is correct — that''s what sits under the root. The last step is still to take the square root of that sum."}, {"tag": "root-distributed", "label": "took the root of each term", "expr": "a+b", "message": "You squared each value and rooted each one back, giving {a} + {b}. The square root doesn''t split across a plus sign: add {a}² + {b}² first, then root the total. That''s why the hypotenuse is shorter than the two legs added."}]'::jsonb WHERE id = 'bfcb9fee-f7ae-46ae-8dcf-c1c2571ecab7';
